window.LEED_TEST_6=[{"id":"UD-501","source_index":501,"q":"Brightwater School District will build 28 elementary schools from one prototype across different climates and sites. Which certification approach is most appropriate?","options":["File 28 separate CIRs asking for streamlined review","Certify the first school and display its plaque at all 28 sites","Volume certification covering every credit, including site and energy, with one review for all 28","Volume certification: review the prototype once, then document only the site- and climate-dependent items for each school"],"answer":3,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the Overview concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"certification: third-party confirmation that a project satisfies applicable LEED requirements; documentation: records used to demonstrate compliance with a LEED requirement; LEED: a third-party green building rating and certification system","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Volume certification reuses what is identical in the prototype, but sites and climates differ, so those items still need per-school documentation.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu Overview, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; LEED: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Volume tái sử dụng những phần giống nhau của mẫu, nhưng khu đất và khí hậu khác nhau nên các hạng mục đó vẫn cần hồ sơ riêng. Vì vậy phương án D đúng.","options_vi":["Gửi 28 CIR riêng yêu cầu thẩm định rút gọn","Chứng nhận trường đầu tiên và treo bảng chứng nhận ở cả 28 nơi","Volume cho mọi tín chỉ gồm cả khu đất và năng lượng, một lần thẩm định cho cả 28 trường","Chứng nhận Volume: thẩm định mẫu một lần rồi chỉ lập hồ sơ các hạng mục phụ thuộc khu đất và khí hậu cho từng trường"],"evidence_en":"Volume certification reuses what is identical in the prototype, but sites and climates differ, so those items still need per-school documentation.","evidence_vi":"Volume tái sử dụng những phần giống nhau của mẫu, nhưng khu đất và khí hậu khác nhau nên các hạng mục đó vẫn cần hồ sơ riêng.","mechanism_vi":"Volume tái sử dụng những phần giống nhau của mẫu, nhưng khu đất và khí hậu khác nhau nên các hạng mục đó vẫn cần hồ sơ riêng. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. CIR không phải đường thẩm định hàng loạt.","Sai. Bảng chứng nhận chỉ cho công trình đã đạt.","Sai. Khu đất và khí hậu khác nhau theo từng trường.","Đúng. Volume tái sử dụng những phần giống nhau của mẫu, nhưng khu đất và khí hậu khác nhau nên các hạng mục đó vẫn cần hồ sơ riêng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 501; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. CIRs are not a bulk-review route.","Incorrect. A plaque shows only certified buildings.","Incorrect. Site and climate items differ per school.","Correct. Volume certification reuses what is identical in the prototype, but sites and climates differ, so those items still need per-school documentation."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"Volume certification reuses what is identical in the prototype, but sites and climates differ, so those items still need per-school documentation.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q001","core_concept_vi":"Volume tái sử dụng những phần giống nhau của mẫu, nhưng khu đất và khí hậu khác nhau nên các hạng mục đó vẫn cần hồ sơ riêng.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-502","source_index":502,"q":"On about 20 move-out days a year, diesel forklifts push a convention center's CO₂ above 1,200 ppm and add exhaust. What is the strongest response?","options":["Run ventilation at maximum on those days","Accept it, as 20 days is a small share of the year","Remove the source by requiring electric equipment indoors; ventilation is a secondary measure","Handle it under Materials & Resources, since forklifts move materials"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"maximum: the highest permitted value or level; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy; energy efficiency: delivery of the required service with less energy use","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Eliminating combustion indoors prevents exposure and also cuts fuel use; dilution only treats the symptom.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EA vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"prerequisite: điều kiện tiên quyết bắt buộc, không mang điểm; maximum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy and atmosphere: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy efficiency: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Loại bỏ đốt trong nhà ngăn phơi nhiễm và giảm nhiên liệu; pha loãng chỉ xử lý triệu chứng. Vì vậy phương án C đúng.","options_vi":["Chạy thông gió tối đa vào những ngày đó","Chấp nhận vì 20 ngày chỉ là phần nhỏ trong năm","Loại bỏ nguồn bằng cách yêu cầu thiết bị điện trong nhà; thông gió chỉ là biện pháp phụ","Xử lý trong Materials & Resources vì xe nâng vận chuyển vật liệu"],"evidence_en":"Eliminating combustion indoors prevents exposure and also cuts fuel use; dilution only treats the symptom.","evidence_vi":"Loại bỏ đốt trong nhà ngăn phơi nhiễm và giảm nhiên liệu; pha loãng chỉ xử lý triệu chứng.","mechanism_vi":"Loại bỏ đốt trong nhà ngăn phơi nhiễm và giảm nhiên liệu; pha loãng chỉ xử lý triệu chứng. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Pha loãng tốn năng lượng và vẫn còn nguồn.","Sai. Phơi nhiễm ngắn vẫn gây hại.","Đúng. Loại bỏ đốt trong nhà ngăn phơi nhiễm và giảm nhiên liệu; pha loãng chỉ xử lý triệu chứng.","Sai. Khí thải xe nâng là vấn đề chất lượng không khí."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 502; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Dilution costs energy and leaves the source.","Incorrect. Short exposure can still harm.","Correct. Eliminating combustion indoors prevents exposure and also cuts fuel use; dilution only treats the symptom.","Incorrect. Forklift exhaust is an air-quality issue."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Eliminating combustion indoors prevents exposure and also cuts fuel use; dilution only treats the symptom.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q002","core_concept_vi":"Loại bỏ đốt trong nhà ngăn phơi nhiễm và giảm nhiên liệu; pha loãng chỉ xử lý triệu chứng.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-503","source_index":503,"q":"Pineview Corporate Campus registered under LEED v4.1 in 2022 and broke ground in 2024. The owner asks whether to move to v5. What should the project manager advise?","options":["Switch to v5: it is free and only the documentation format changes","Cancel and restart in v5 to avoid looking outdated","Stay on v4.1: a registered project continues under its registered version, and moving to v5 means new prerequisites and redesign","Switch, since the newest version is always marketable"],"answer":2,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"best: a word asking for the strongest or most effective option; documentation: records used to demonstrate compliance with a LEED requirement; LEED: a third-party green building rating and certification system","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"v5 adds prerequisites such as the resilience, human-impact and carbon assessments and a different scoring basis, so a project already in construction should not move.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc Overview vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"best: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; LEED: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"v5 bổ sung các tiên quyết như đánh giá khí hậu, tác động con người và carbon cùng cách chấm điểm khác, nên dự án đang thi công không nên chuyển. Vì vậy phương án C đúng.","options_vi":["Chuyển sang v5 vì miễn phí và chỉ đổi định dạng hồ sơ","Hủy và làm lại theo v5 để khỏi bị coi là lạc hậu","Giữ v4.1: dự án đã đăng ký tiếp tục theo phiên bản đã đăng ký, chuyển sang v5 nghĩa là có tiên quyết mới và phải thiết kế lại","Chuyển vì phiên bản mới nhất luôn có giá trị thị trường"],"evidence_en":"v5 adds prerequisites such as the resilience, human-impact and carbon assessments and a different scoring basis, so a project already in construction should not move.","evidence_vi":"v5 bổ sung các tiên quyết như đánh giá khí hậu, tác động con người và carbon cùng cách chấm điểm khác, nên dự án đang thi công không nên chuyển.","mechanism_vi":"v5 bổ sung các tiên quyết như đánh giá khí hậu, tác động con người và carbon cùng cách chấm điểm khác, nên dự án đang thi công không nên chuyển. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. v5 đổi nội dung, không chỉ định dạng.","Sai. Hủy bỏ làm lãng phí công việc đã làm.","Đúng. v5 bổ sung các tiên quyết như đánh giá khí hậu, tác động con người và carbon cùng cách chấm điểm khác, nên dự án đang thi công không nên chuyển.","Sai. Mới nhất không đồng nghĩa phù hợp nhất với dự án đang xây."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 503; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. v5 changes content, not only format.","Incorrect. Cancelling wastes completed work.","Correct. v5 adds prerequisites such as the resilience, human-impact and carbon assessments and a different scoring basis, so a project already in construction should not move.","Incorrect. Newest is not automatically best for a built project."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"v5 adds prerequisites such as the resilience, human-impact and carbon assessments and a different scoring basis, so a project already in construction should not move.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q003","core_concept_vi":"v5 bổ sung các tiên quyết như đánh giá khí hậu, tác động con người và carbon cùng cách chấm điểm khác, nên dự án đang thi công không nên chuyển.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-504","source_index":504,"q":"Three years after certification, metered data show Westbrook Publishing House uses 28% more energy and 15% more water than predicted. What should the sustainability manager recommend?","options":["Revoke the certification for misrepresentation","Adjust the baseline so the gap looks smaller","Use the metered data to drive a retro-commissioning investigation and corrections","Take no action, since certification is permanent"],"answer":2,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"commissioning: a quality-focused process that verifies systems meet the owner’s project requirements; baseline: the reference case against which project performance is compared; certification: third-party confirmation that a project satisfies applicable LEED requirements","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"A prediction gap is a diagnostic signal: schedules, controls and plug loads usually explain it, and fixing them recovers the savings.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm Overview đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; commissioning: quá trình xác minh có hệ thống rằng công trình và hệ thống đáp ứng OPR và BOD; baseline: đường cơ sở dùng để so sánh hiệu suất của dự án","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Chênh lệch dự báo là tín hiệu chẩn đoán: lịch vận hành, điều khiển và tải cắm thường giải thích được và sửa chúng giúp lấy lại mức tiết kiệm. Vì vậy phương án C đúng.","options_vi":["Thu hồi chứng nhận vì khai sai","Điều chỉnh mức cơ sở để chênh lệch nhìn nhỏ hơn","Dùng dữ liệu đo để dẫn dắt điều tra retro-commissioning và khắc phục","Không làm gì vì chứng nhận là vĩnh viễn"],"evidence_en":"A prediction gap is a diagnostic signal: schedules, controls and plug loads usually explain it, and fixing them recovers the savings.","evidence_vi":"Chênh lệch dự báo là tín hiệu chẩn đoán: lịch vận hành, điều khiển và tải cắm thường giải thích được và sửa chúng giúp lấy lại mức tiết kiệm.","mechanism_vi":"Chênh lệch dự báo là tín hiệu chẩn đoán: lịch vận hành, điều khiển và tải cắm thường giải thích được và sửa chúng giúp lấy lại mức tiết kiệm. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Chênh lệch không phải khai sai.","Sai. Đổi mức cơ sở che giấu vấn đề.","Đúng. Chênh lệch dự báo là tín hiệu chẩn đoán: lịch vận hành, điều khiển và tải cắm thường giải thích được và sửa chúng giúp lấy lại mức tiết kiệm.","Sai. Không hành động thì lãng phí tiếp diễn."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 504; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. A gap is not misrepresentation.","Incorrect. Changing the baseline hides the problem.","Correct. A prediction gap is a diagnostic signal: schedules, controls and plug loads usually explain it, and fixing them recovers the savings.","Incorrect. Waste continues without action."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"A prediction gap is a diagnostic signal: schedules, controls and plug loads usually explain it, and fixing them recovers the savings.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q004","core_concept_vi":"Chênh lệch dự báo là tín hiệu chẩn đoán: lịch vận hành, điều khiển và tải cắm thường giải thích được và sửa chúng giúp lấy lại mức tiết kiệm.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-505","source_index":505,"q":"Northgate Office Tower is 60% built when the owner adds a rooftop bar and restaurant. Which response is most appropriate?","options":["Ignore it because it is above the roofline","Withdraw from LEED because earlier documentation is invalid","Update only the energy model","Re-run the energy model and operational carbon projection, check kitchen fuel against Electrification, and update water, waste and ventilation documentation"],"answer":3,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"energy model: a simulation used to estimate and compare building energy performance; certification: third-party confirmation that a project satisfies applicable LEED requirements; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"A restaurant adds energy, fuel, water, waste and exhaust loads, so several credits and the carbon projection change.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc Overview vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; energy model: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Nhà hàng làm tăng năng lượng, nhiên liệu, nước, chất thải và thải khí nên nhiều tín chỉ và dự báo carbon thay đổi. Vì vậy phương án D đúng.","options_vi":["Bỏ qua vì nằm trên đường mái","Rút khỏi LEED vì hồ sơ trước đó vô hiệu","Chỉ cập nhật mô hình năng lượng","Chạy lại mô hình năng lượng và dự báo carbon vận hành, kiểm tra nhiên liệu bếp so với Electrification, cập nhật hồ sơ nước, chất thải và thông gió"],"evidence_en":"A restaurant adds energy, fuel, water, waste and exhaust loads, so several credits and the carbon projection change.","evidence_vi":"Nhà hàng làm tăng năng lượng, nhiên liệu, nước, chất thải và thải khí nên nhiều tín chỉ và dự báo carbon thay đổi.","mechanism_vi":"Nhà hàng làm tăng năng lượng, nhiên liệu, nước, chất thải và thải khí nên nhiều tín chỉ và dự báo carbon thay đổi. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Nó thêm tải lớn.","Sai. Hồ sơ có thể cập nhật.","Sai. Nhiều hạng mục bị ảnh hưởng.","Đúng. Nhà hàng làm tăng năng lượng, nhiên liệu, nước, chất thải và thải khí nên nhiều tín chỉ và dự báo carbon thay đổi."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 505; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. It adds large loads.","Incorrect. Documentation can be updated.","Incorrect. Several categories are affected.","Correct. A restaurant adds energy, fuel, water, waste and exhaust loads, so several credits and the carbon projection change."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"A restaurant adds energy, fuel, water, waste and exhaust loads, so several credits and the carbon projection change.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q005","core_concept_vi":"Nhà hàng làm tăng năng lượng, nhiên liệu, nước, chất thải và thải khí nên nhiều tín chỉ và dự báo carbon thay đổi.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-506","source_index":506,"q":"Nexus Research Center's cooling tower records show makeup 450,000 gal/month, blowdown 150,000, evaporation 280,000 and drift 20,000. What are the cycles of concentration?","options":["3.0 (450,000 ÷ 150,000), near optimal","About 1.6 (280,000 ÷ 170,000)","About 4.5, since drift is excluded","About 2.6 (450,000 ÷ 170,000), low compared with a typical 5–8 target"],"answer":3,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the WE concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"cycles of concentration: the ratio of dissolved solids in cooling-tower water to those in makeup water; cooling tower: heat-rejection equipment that commonly uses evaporation; blowdown: water discharged from a cooling tower to control dissolved solids; makeup water: water added to replace evaporation, drift, and blowdown losses; best: a word asking for the strongest or most effective option","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Cycles = makeup ÷ (blowdown + drift) = 450,000 ÷ 170,000 ≈ 2.6, so there is room to raise cycles and cut makeup.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm WE đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng; verification: việc dùng dữ liệu hoặc hồ sơ để xác nhận yêu cầu đã được đáp ứng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Chu kỳ = nước bù ÷ (xả đáy + drift) = 450.000 ÷ 170.000 ≈ 2,6 nên còn dư địa tăng chu kỳ để giảm nước bù. Vì vậy phương án D đúng.","options_vi":["3,0 (450.000 ÷ 150.000), gần tối ưu","Khoảng 1,6 (280.000 ÷ 170.000)","Khoảng 4,5 vì bỏ qua drift","Khoảng 2,6 (450.000 ÷ 170.000), thấp so với mục tiêu thường gặp 5–8"],"evidence_en":"Cycles = makeup ÷ (blowdown + drift) = 450,000 ÷ 170,000 ≈ 2.6, so there is room to raise cycles and cut makeup.","evidence_vi":"Chu kỳ = nước bù ÷ (xả đáy + drift) = 450.000 ÷ 170.000 ≈ 2,6 nên còn dư địa tăng chu kỳ để giảm nước bù.","mechanism_vi":"Chu kỳ = nước bù ÷ (xả đáy + drift) = 450.000 ÷ 170.000 ≈ 2,6 nên còn dư địa tăng chu kỳ để giảm nước bù. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Drift là tổn thất và phải tính.","Sai. Bay hơi không phải số chia.","Sai. Drift là một phần nước mất.","Đúng. Chu kỳ = nước bù ÷ (xả đáy + drift) = 450.000 ÷ 170.000 ≈ 2,6 nên còn dư địa tăng chu kỳ để giảm nước bù."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 506; Water Efficiency","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Drift is a loss and must be included.","Incorrect. Evaporation is not the divisor.","Incorrect. Drift is part of the water lost.","Correct. Cycles = makeup ÷ (blowdown + drift) = 450,000 ÷ 170,000 ≈ 2.6, so there is room to raise cycles and cut makeup."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Cycles = makeup ÷ (blowdown + drift) = 450,000 ÷ 170,000 ≈ 2.6, so there is room to raise cycles and cut makeup.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q006","core_concept_vi":"Chu kỳ = nước bù ÷ (xả đáy + drift) = 450.000 ÷ 170.000 ≈ 2,6 nên còn dư địa tăng chu kỳ để giảm nước bù.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-507","source_index":507,"q":"Bellingham Nature Center's parking lies 30 ft from a wetland boundary where regulations require a 50 ft setback. What is the correct action?","options":["Keep it if the lot is paved with asphalt","Move the parking to meet the stricter of local law and rating requirements","Apply the buffer to the building only","Accept 30 ft, as buffers are discretionary"],"answer":1,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"sustainable sites: strategies that protect site ecology and manage construction and operational site impacts; site disturbance: physical alteration of soil, vegetation, or existing site conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Buffers protect the wetland from all development, so the stricter requirement governs.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"sustainable sites: khu đất bền vững; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Vùng đệm bảo vệ vùng ngập nước khỏi mọi hạng mục xây dựng nên yêu cầu chặt hơn áp dụng. Vì vậy phương án B đúng.","options_vi":["Giữ nguyên nếu bãi lát nhựa","Dời bãi đỗ để đáp ứng yêu cầu chặt hơn giữa luật địa phương và hệ thống chứng nhận","Chỉ áp dụng vùng đệm cho tòa nhà","Chấp nhận 30 ft vì vùng đệm là tùy ý"],"evidence_en":"Buffers protect the wetland from all development, so the stricter requirement governs.","evidence_vi":"Vùng đệm bảo vệ vùng ngập nước khỏi mọi hạng mục xây dựng nên yêu cầu chặt hơn áp dụng.","mechanism_vi":"Vùng đệm bảo vệ vùng ngập nước khỏi mọi hạng mục xây dựng nên yêu cầu chặt hơn áp dụng. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Lát nhựa không đổi khoảng lùi.","Đúng. Vùng đệm bảo vệ vùng ngập nước khỏi mọi hạng mục xây dựng nên yêu cầu chặt hơn áp dụng.","Sai. Vùng đệm áp dụng cho bãi đỗ.","Sai. Chúng không tùy ý."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 507; Sustainable Sites","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Paving does not change setback.","Correct. Buffers protect the wetland from all development, so the stricter requirement governs.","Incorrect. Buffers apply to parking.","Incorrect. They are not discretionary."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Buffers protect the wetland from all development, so the stricter requirement governs.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q007","core_concept_vi":"Vùng đệm bảo vệ vùng ngập nước khỏi mọi hạng mục xây dựng nên yêu cầu chặt hơn áp dụng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-508","source_index":508,"q":"Pacific Innovation Hub proposes a material passport, bolted steel connections for disassembly, and a carpet take-back agreement. How should the team pursue recognition?","options":["Submit them as Project Priorities proposals, each with a defined metric and verification, since none is awarded automatically","Each is automatically awarded a point","They are already required by v5 prerequisites","Only the bolted connections can be submitted"],"answer":0,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"innovation: a strategy with significant benefit not adequately addressed by existing LEED credits; credit: an optional LEED requirement that can earn points; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Project Priorities credits require a documented outcome and verification, not just good intentions.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu MR, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; CIR: yêu cầu giải thích chính thức cách áp dụng credit cho tình huống dự án; innovation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tín chỉ Project Priorities đòi hỏi kết quả có hồ sơ và kiểm chứng, không chỉ ý định tốt. Vì vậy phương án A đúng.","options_vi":["Nộp như đề xuất Project Priorities, mỗi đề xuất có chỉ số và cách kiểm chứng xác định, vì không điểm nào được tự động cấp","Mỗi hạng mục tự động được một điểm","Chúng đã bắt buộc trong tiên quyết v5","Chỉ liên kết bu lông mới nộp được"],"evidence_en":"Project Priorities credits require a documented outcome and verification, not just good intentions.","evidence_vi":"Tín chỉ Project Priorities đòi hỏi kết quả có hồ sơ và kiểm chứng, không chỉ ý định tốt.","mechanism_vi":"Tín chỉ Project Priorities đòi hỏi kết quả có hồ sơ và kiểm chứng, không chỉ ý định tốt. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Tín chỉ Project Priorities đòi hỏi kết quả có hồ sơ và kiểm chứng, không chỉ ý định tốt.","Sai. Không có gì tự động.","Sai. Chúng không phải tiên quyết.","Sai. Cả ba đều có thể đề xuất."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 508; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Correct. Project Priorities credits require a documented outcome and verification, not just good intentions.","Incorrect. Nothing is automatic.","Incorrect. They are not prerequisites.","Incorrect. All three can be proposed."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Project Priorities credits require a documented outcome and verification, not just good intentions.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q008","core_concept_vi":"Tín chỉ Project Priorities đòi hỏi kết quả có hồ sơ và kiểm chứng, không chỉ ý định tốt.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-509","source_index":509,"q":"Westwood Mixed-Use has time-of-use rates (3× price 4–9 PM), a $50/kW demand-response program, 300 kW of PV, 500 kWh of storage and 200 EV ports. How should these assets be operated?","options":["Maximize PV export at all times","Charge storage from midday PV, discharge during 4–9 PM, enroll in demand response, and manage EV charging","Operate storage and EV charging independently","Treat storage as irrelevant to LEED"],"answer":1,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"demand response: temporary adjustment of electric demand in response to grid conditions or signals; certification: third-party confirmation that a project satisfies applicable LEED requirements; maximum: the highest permitted value or level","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Coordinating storage, PV and EV loads against the price signal cuts cost and is the behavior Grid Interactive rewards.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EA vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; demand response: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; maximum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Phối hợp pin, PV và sạc EV theo tín hiệu giá giảm chi phí và đúng là hành vi Grid Interactive thưởng. Vì vậy phương án B đúng.","options_vi":["Tối đa hóa xuất PV mọi lúc","Sạc pin từ PV giữa ngày, xả trong 4–9 giờ tối, tham gia đáp ứng nhu cầu và quản lý sạc EV","Vận hành pin và sạc EV độc lập","Coi lưu trữ không liên quan đến LEED"],"evidence_en":"Coordinating storage, PV and EV loads against the price signal cuts cost and is the behavior Grid Interactive rewards.","evidence_vi":"Phối hợp pin, PV và sạc EV theo tín hiệu giá giảm chi phí và đúng là hành vi Grid Interactive thưởng.","mechanism_vi":"Phối hợp pin, PV và sạc EV theo tín hiệu giá giảm chi phí và đúng là hành vi Grid Interactive thưởng. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Xuất điện ngoài giờ cao giá không phải mục tiêu.","Đúng. Phối hợp pin, PV và sạc EV theo tín hiệu giá giảm chi phí và đúng là hành vi Grid Interactive thưởng.","Sai. Thiết bị không phối hợp bỏ lỡ giá trị.","Sai. Lưu trữ hỗ trợ Grid Interactive."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 509; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Export at peak-price hours is not the aim.","Correct. Coordinating storage, PV and EV loads against the price signal cuts cost and is the behavior Grid Interactive rewards.","Incorrect. Uncoordinated assets miss value.","Incorrect. Storage supports Grid Interactive."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Coordinating storage, PV and EV loads against the price signal cuts cost and is the behavior Grid Interactive rewards.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q009","core_concept_vi":"Phối hợp pin, PV và sạc EV theo tín hiệu giá giảm chi phí và đúng là hành vi Grid Interactive thưởng.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-510","source_index":510,"q":"Clearwater Medical Center weighs Enhanced Commissioning (+$180,000) against Fundamental only. Similar hospitals saw $220,000 of avoided change orders plus 12–18% extra energy savings. What is the best recommendation?","options":["Skip it, since Fundamental satisfies the prerequisite","Skip it, as it only suits buildings over 1,000,000 sf","Skip it, since it is generally not worth the cost","Proceed: avoided change orders alone exceed the cost, and energy savings are additional"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this sequence question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"commissioning: a quality-focused process that verifies systems meet the owner’s project requirements; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy; energy efficiency: delivery of the required service with less energy use","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"$220,000 of avoided change orders already exceeds the $180,000 premium before counting energy savings.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"commissioning: quá trình xác minh có hệ thống rằng công trình và hệ thống đáp ứng OPR và BOD; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"220.000 USD thay đổi tránh được đã vượt 180.000 USD chi phí thêm trước khi tính tiết kiệm năng lượng. Vì vậy phương án D đúng.","options_vi":["Bỏ qua vì Fundamental đã đáp ứng tiên quyết","Bỏ qua vì chỉ phù hợp công trình trên 1.000.000 sf","Bỏ qua vì nhìn chung không đáng chi phí","Thực hiện: riêng chi phí thay đổi tránh được đã vượt chi phí, còn tiết kiệm năng lượng là phần thêm"],"evidence_en":"$220,000 of avoided change orders already exceeds the $180,000 premium before counting energy savings.","evidence_vi":"220.000 USD thay đổi tránh được đã vượt 180.000 USD chi phí thêm trước khi tính tiết kiệm năng lượng.","mechanism_vi":"220.000 USD thay đổi tránh được đã vượt 180.000 USD chi phí thêm trước khi tính tiết kiệm năng lượng. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Fundamental là mức tối thiểu, không phải giá trị tốt nhất.","Sai. Không có ngưỡng diện tích.","Sai. Số liệu cho thấy hoàn vốn.","Đúng. 220.000 USD thay đổi tránh được đã vượt 180.000 USD chi phí thêm trước khi tính tiết kiệm năng lượng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 510; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Fundamental is the minimum, not the best value.","Incorrect. There is no size cut-off.","Incorrect. The numbers show payback.","Correct. $220,000 of avoided change orders already exceeds the $180,000 premium before counting energy savings."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"$220,000 of avoided change orders already exceeds the $180,000 premium before counting energy savings.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q010","core_concept_vi":"220.000 USD thay đổi tránh được đã vượt 180.000 USD chi phí thêm trước khi tính tiết kiệm năng lượng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-511","source_index":511,"q":"Six months after Ironwood Office Complex added R-30 continuous exterior insulation, moisture stains appear around windows. An envelope specialist finds condensation caused by window details that ignored the insulation change. What is the lesson?","options":["It is a construction defect unrelated to the design","Remove the insulation","Window installation details must be redesigned for continuous insulation, and envelope commissioning would have caught it","Raise indoor humidity setpoints"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"commissioning: a quality-focused process that verifies systems meet the owner’s project requirements; energy model: a simulation used to estimate and compare building energy performance; indoor environmental quality: indoor conditions affecting occupant health, comfort, and well-being","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Changing insulation location moves the dew point, so interfaces need design and verification.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"commissioning: quá trình xác minh có hệ thống rằng công trình và hệ thống đáp ứng OPR và BOD; indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Đổi vị trí cách nhiệt làm dịch điểm sương nên các mối nối cần thiết kế và kiểm chứng. Vì vậy phương án C đúng.","options_vi":["Là lỗi thi công không liên quan thiết kế","Gỡ lớp cách nhiệt","Chi tiết lắp cửa sổ phải thiết kế lại cho lớp cách nhiệt liên tục và commissioning vỏ bao che đã có thể phát hiện","Tăng độ ẩm cài đặt trong nhà"],"evidence_en":"Changing insulation location moves the dew point, so interfaces need design and verification.","evidence_vi":"Đổi vị trí cách nhiệt làm dịch điểm sương nên các mối nối cần thiết kế và kiểm chứng.","mechanism_vi":"Đổi vị trí cách nhiệt làm dịch điểm sương nên các mối nối cần thiết kế và kiểm chứng. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Đó là vấn đề mối nối thiết kế.","Sai. Cách nhiệt giảm năng lượng.","Đúng. Đổi vị trí cách nhiệt làm dịch điểm sương nên các mối nối cần thiết kế và kiểm chứng.","Sai. Thêm ẩm làm ngưng tụ nặng hơn."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 511; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. It is a design interface issue.","Incorrect. Insulation reduces energy.","Correct. Changing insulation location moves the dew point, so interfaces need design and verification.","Incorrect. More humidity worsens condensation."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Changing insulation location moves the dew point, so interfaces need design and verification.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q011","core_concept_vi":"Đổi vị trí cách nhiệt làm dịch điểm sương nên các mối nối cần thiết kế và kiểm chứng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-512","source_index":512,"q":"Three weeks before signing a $1.2M curtain-wall contract, the supplier says it provides no EPDs or HPDs. What should the coordinator recommend?","options":["Request a CIR exempting curtain walls","Make disclosure a contract condition or switch to a supplier who can document it","Sign now and expect documents later","Proceed, since disclosure is optional for curtain wall"],"answer":1,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"documentation: records used to demonstrate compliance with a LEED requirement; EPD: an Environmental Product Declaration reporting verified life-cycle impacts; HPD: a Health Product Declaration reporting product ingredients and health information","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Documentation is cheapest to secure before signature, when the buyer has leverage.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm MR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng; verification: việc dùng dữ liệu hoặc hồ sơ để xác nhận yêu cầu đã được đáp ứng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Hồ sơ rẻ nhất khi giành được trước chữ ký, lúc bên mua còn lợi thế. Vì vậy phương án B đúng.","options_vi":["Gửi CIR xin miễn trừ tường kính","Đưa công bố thông tin thành điều kiện hợp đồng hoặc đổi nhà cung cấp có thể chứng minh","Ký ngay và mong có hồ sơ sau","Tiếp tục vì công bố là tùy chọn với tường kính"],"evidence_en":"Documentation is cheapest to secure before signature, when the buyer has leverage.","evidence_vi":"Hồ sơ rẻ nhất khi giành được trước chữ ký, lúc bên mua còn lợi thế.","mechanism_vi":"Hồ sơ rẻ nhất khi giành được trước chữ ký, lúc bên mua còn lợi thế. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Miễn trừ khó được chấp thuận.","Đúng. Hồ sơ rẻ nhất khi giành được trước chữ ký, lúc bên mua còn lợi thế.","Sai. Lời hứa sau không có tính ràng buộc.","Sai. Tùy chọn không có nghĩa vô ích."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 512; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Exemptions are unlikely.","Correct. Documentation is cheapest to secure before signature, when the buyer has leverage.","Incorrect. Later promises are unenforceable.","Incorrect. Optional does not mean unhelpful."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Documentation is cheapest to secure before signature, when the buyer has leverage.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q012","core_concept_vi":"Hồ sơ rẻ nhất khi giành được trước chữ ký, lúc bên mua còn lợi thế.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-513","source_index":513,"q":"A CLT building saves 3,500 t CO₂e upfront compared with concrete but uses 30 t CO₂e more per year in operation, over a 25-year assessment period. How should the team evaluate it?","options":["Concrete is better since energy rises","CLT is disqualified by the 4% energy rise","Net about 2,750 t lower (3,500 − 750), then confirm sourcing and biogenic assumptions","Count only operational energy"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"energy model: a simulation used to estimate and compare building energy performance; embodied carbon: greenhouse gas emissions associated with materials and construction; innovation: a strategy with significant benefit not adequately addressed by existing LEED credits","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"30 t × 25 years = 750 t, far below the 3,500 t upfront saving.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; embodied carbon: carbon hàm chứa; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"30 t × 25 năm = 750 t, thấp hơn nhiều so với 3.500 t tiết kiệm ban đầu. Vì vậy phương án C đúng.","options_vi":["Bê tông tốt hơn vì năng lượng tăng","CLT bị loại vì năng lượng tăng 4%","Thấp hơn ròng khoảng 2.750 t (3.500 − 750), rồi xác nhận nguồn gốc và giả định carbon sinh học","Chỉ tính năng lượng vận hành"],"evidence_en":"30 t × 25 years = 750 t, far below the 3,500 t upfront saving.","evidence_vi":"30 t × 25 năm = 750 t, thấp hơn nhiều so với 3.500 t tiết kiệm ban đầu.","mechanism_vi":"30 t × 25 năm = 750 t, thấp hơn nhiều so với 3.500 t tiết kiệm ban đầu. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Khoản tiết kiệm ban đầu chiếm ưu thế.","Sai. Tăng năng lượng không phải lý do loại.","Đúng. 30 t × 25 năm = 750 t, thấp hơn nhiều so với 3.500 t tiết kiệm ban đầu.","Sai. Carbon hàm chứa cũng được tính."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 513; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. The upfront saving dominates.","Incorrect. Energy rise is not disqualifying.","Correct. 30 t × 25 years = 750 t, far below the 3,500 t upfront saving.","Incorrect. Embodied carbon also counts."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"30 t × 25 years = 750 t, far below the 3,500 t upfront saving.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q013","core_concept_vi":"30 t × 25 năm = 750 t, thấp hơn nhiều so với 3.500 t tiết kiệm ban đầu.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-514","source_index":514,"q":"A LEED Gold building shows 38% modeled savings against the code baseline. How should communications describe it?","options":["38% less energy than a conventional building","Modeled source-energy savings of 38% versus the code baseline, not a measured comparison with conventional buildings","GBCI authorizes any energy claim","The claim cannot be made at all"],"answer":1,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; energy performance: the measured or modeled energy use of a building or system; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"The figure is a model result relative to a defined baseline, not a measurement relative to the building stock.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"baseline: đường cơ sở dùng để so sánh hiệu suất của dự án; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Con số là kết quả mô hình so với mức cơ sở xác định, không phải số đo so với hiện trạng. Vì vậy phương án B đúng.","options_vi":["Ít hơn 38% năng lượng so với công trình thông thường","Tiết kiệm năng lượng sơ cấp theo mô hình 38% so với mức cơ sở quy chuẩn, không phải so sánh đo đạc với công trình thông thường","GBCI cho phép mọi tuyên bố năng lượng","Không thể nêu tuyên bố"],"evidence_en":"The figure is a model result relative to a defined baseline, not a measurement relative to the building stock.","evidence_vi":"Con số là kết quả mô hình so với mức cơ sở xác định, không phải số đo so với hiện trạng.","mechanism_vi":"Con số là kết quả mô hình so với mức cơ sở xác định, không phải số đo so với hiện trạng. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Mức cơ sở không phải công trình trung bình.","Đúng. Con số là kết quả mô hình so với mức cơ sở xác định, không phải số đo so với hiện trạng.","Sai. GBCI không phê duyệt tuyên bố.","Sai. Có thể nêu tuyên bố chính xác."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 514; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Baseline is not the average building.","Correct. The figure is a model result relative to a defined baseline, not a measurement relative to the building stock.","Incorrect. GBCI does not authorize claims.","Incorrect. A precise claim is allowed."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"The figure is a model result relative to a defined baseline, not a measurement relative to the building stock.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q014","core_concept_vi":"Con số là kết quả mô hình so với mức cơ sở xác định, không phải số đo so với hiện trạng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-515","source_index":515,"q":"Riverfront Commons counted its own café, gym and childcare as diverse uses for the compact and connected development credit. The reviewer denied it. Why?","options":["The reviewer erred; campus amenities always count","The credit measures external destinations accessible to the public, not uses internal to the campus","The campus can request a waiver for being large","A separate legal parcel would fix it by itself"],"answer":1,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"surrounding density: the concentration of development around a project site; diverse uses: different destination types that support daily needs within walking distance; credit: an optional LEED requirement that can earn points","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Surrounding-use credits reflect what a site connects to, not what the project provides itself.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc Overview vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; surrounding density: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; diverse uses: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tín chỉ về công năng xung quanh phản ánh nơi khu đất kết nối tới, không phải thứ dự án tự cung cấp. Vì vậy phương án B đúng.","options_vi":["Người thẩm định sai; tiện ích khuôn viên luôn được tính","Tín chỉ đo các điểm đến bên ngoài mà công chúng tiếp cận được, không phải tiện ích nội bộ khuôn viên","Khuôn viên có thể xin miễn trừ vì lớn","Tách thành lô đất riêng là tự đủ"],"evidence_en":"Surrounding-use credits reflect what a site connects to, not what the project provides itself.","evidence_vi":"Tín chỉ về công năng xung quanh phản ánh nơi khu đất kết nối tới, không phải thứ dự án tự cung cấp.","mechanism_vi":"Tín chỉ về công năng xung quanh phản ánh nơi khu đất kết nối tới, không phải thứ dự án tự cung cấp. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Tiện ích là nội bộ.","Đúng. Tín chỉ về công năng xung quanh phản ánh nơi khu đất kết nối tới, không phải thứ dự án tự cung cấp.","Sai. Không có miễn trừ vì quy mô.","Sai. Lô đất pháp lý không tạo điểm đến ngoài."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 515; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Amenities are internal.","Correct. Surrounding-use credits reflect what a site connects to, not what the project provides itself.","Incorrect. Waivers are not granted for size.","Incorrect. Legal parcels do not create external uses."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"Surrounding-use credits reflect what a site connects to, not what the project provides itself.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q015","core_concept_vi":"Tín chỉ về công năng xung quanh phản ánh nơi khu đất kết nối tới, không phải thứ dự án tự cung cấp.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-516","source_index":516,"q":"Northgate Research Institute finds 8,000 sf of millwork was swapped from no-added-formaldehyde plywood to standard plywood, and testing shows 45 ppb formaldehyde against a 16.3 ppb limit. What is the best response?","options":["Flush out alone, because dilution removes the source","Apply sealers and consider it done","Accept the result because the substitution saved money","Remove the non-compliant source and retest to confirm compliance"],"answer":3,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the MR concept and solve this best-fit question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"best: a word asking for the strongest or most effective option; materials and resources: strategies addressing life-cycle impacts, product selection, sourcing, and waste; product documentation: verified records supporting environmental and material claims","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Emissions continue from the source, so remedies that treat air or surfaces must be proven by retesting; removal is the only fix that ends the source.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm MR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"materials and resources: vật liệu và tài nguyên; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Phát thải vẫn tiếp diễn từ nguồn nên biện pháp xử lý không khí hay bề mặt phải được chứng minh bằng thử lại; chỉ loại bỏ mới chấm dứt nguồn. Vì vậy phương án D đúng.","options_vi":["Chỉ xả khí vì pha loãng sẽ loại nguồn","Phủ chất bịt và coi như xong","Chấp nhận kết quả vì thay thế tiết kiệm tiền","Loại bỏ nguồn không đạt và thử lại để xác nhận"],"evidence_en":"Emissions continue from the source, so remedies that treat air or surfaces must be proven by retesting; removal is the only fix that ends the source.","evidence_vi":"Phát thải vẫn tiếp diễn từ nguồn nên biện pháp xử lý không khí hay bề mặt phải được chứng minh bằng thử lại; chỉ loại bỏ mới chấm dứt nguồn.","mechanism_vi":"Phát thải vẫn tiếp diễn từ nguồn nên biện pháp xử lý không khí hay bề mặt phải được chứng minh bằng thử lại; chỉ loại bỏ mới chấm dứt nguồn. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Xả khí chỉ là tạm thời.","Sai. Chất bịt cần kiểm chứng.","Sai. Tiết kiệm chi phí không đạt giới hạn.","Đúng. Phát thải vẫn tiếp diễn từ nguồn nên biện pháp xử lý không khí hay bề mặt phải được chứng minh bằng thử lại; chỉ loại bỏ mới chấm dứt nguồn."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 516; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Flush-out is temporary.","Incorrect. Sealers need verification.","Incorrect. Cost savings do not meet the limit.","Correct. Emissions continue from the source, so remedies that treat air or surfaces must be proven by retesting; removal is the only fix that ends the source."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Emissions continue from the source, so remedies that treat air or surfaces must be proven by retesting; removal is the only fix that ends the source.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q016","core_concept_vi":"Phát thải vẫn tiếp diễn từ nguồn nên biện pháp xử lý không khí hay bề mặt phải được chứng minh bằng thử lại; chỉ loại bỏ mới chấm dứt nguồn.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-517","source_index":517,"q":"Cascadia Science Museum reuses timbers, flooring and beams from a demolished 1920s factory. How are these counted?","options":["They count as reuse and contribute near-zero upfront embodied carbon, with transport and refinishing included","They are not recognized because they lack EPDs","They can earn only one credit","They count only within 500 miles"],"answer":0,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"embodied carbon: greenhouse gas emissions associated with materials and construction; credit: an optional LEED requirement that can earn points; EPD: an Environmental Product Declaration reporting verified life-cycle impacts","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Reuse avoids new production, so its upfront carbon is mostly transport and processing.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm MR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; embodied carbon: carbon hàm chứa; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tái sử dụng tránh sản xuất mới nên carbon ban đầu chủ yếu là vận chuyển và gia công. Vì vậy phương án A đúng.","options_vi":["Được tính là tái sử dụng và đóng góp carbon ban đầu gần bằng không, có tính vận chuyển và hoàn thiện lại","Không được công nhận vì thiếu EPD","Chỉ được một tín chỉ","Chỉ tính trong bán kính 500 dặm"],"evidence_en":"Reuse avoids new production, so its upfront carbon is mostly transport and processing.","evidence_vi":"Tái sử dụng tránh sản xuất mới nên carbon ban đầu chủ yếu là vận chuyển và gia công.","mechanism_vi":"Tái sử dụng tránh sản xuất mới nên carbon ban đầu chủ yếu là vận chuyển và gia công. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Tái sử dụng tránh sản xuất mới nên carbon ban đầu chủ yếu là vận chuyển và gia công.","Sai. Tái sử dụng không cần EPD.","Sai. Một hạng mục có thể hỗ trợ nhiều kết quả.","Sai. Khoảng cách không phải ngưỡng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 517; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. Reuse avoids new production, so its upfront carbon is mostly transport and processing.","Incorrect. Reuse needs no EPD.","Incorrect. One item can support several outcomes.","Incorrect. Distance is not a gate."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Reuse avoids new production, so its upfront carbon is mostly transport and processing.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q017","core_concept_vi":"Tái sử dụng tránh sản xuất mới nên carbon ban đầu chủ yếu là vận chuyển và gia công.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-518","source_index":518,"q":"Thornwood Corporate Campus converts a 20-acre golf course: 8 acres native prairie, 4 acres retained trees, 2 acres bioretention, 6 acres built. What does this support?","options":["Only one credit","Several site credits at once (habitat, rainwater, heat island), each earned on its own documented criteria","None, since 6 acres are developed","Nothing, because golf-course conversion is prohibited"],"answer":1,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the SS concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"heat island: elevated temperatures caused by heat-absorbing built surfaces; credit: an optional LEED requirement that can earn points; sustainable sites: strategies that protect site ecology and manage construction and operational site impacts","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Different land uses serve different credits, but each must meet its own requirements.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; sustainable sites: khu đất bền vững; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Các loại sử dụng đất phục vụ các tín chỉ khác nhau nhưng mỗi tín chỉ phải đáp ứng yêu cầu riêng. Vì vậy phương án B đúng.","options_vi":["Chỉ một tín chỉ","Nhiều tín chỉ khu đất cùng lúc (sinh cảnh, nước mưa, đảo nhiệt), mỗi tín chỉ theo tiêu chí có hồ sơ riêng","Không tín chỉ nào vì có 6 acre xây dựng","Không gì cả vì cấm chuyển sân golf"],"evidence_en":"Different land uses serve different credits, but each must meet its own requirements.","evidence_vi":"Các loại sử dụng đất phục vụ các tín chỉ khác nhau nhưng mỗi tín chỉ phải đáp ứng yêu cầu riêng.","mechanism_vi":"Các loại sử dụng đất phục vụ các tín chỉ khác nhau nhưng mỗi tín chỉ phải đáp ứng yêu cầu riêng. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Phục hồi hỗ trợ nhiều tín chỉ.","Đúng. Các loại sử dụng đất phục vụ các tín chỉ khác nhau nhưng mỗi tín chỉ phải đáp ứng yêu cầu riêng.","Sai. Diện tích xây dựng không loại bỏ tín chỉ.","Sai. Cho phép chuyển đổi."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 518; Sustainable Sites","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Restoration supports multiple credits.","Correct. Different land uses serve different credits, but each must meet its own requirements.","Incorrect. Developed area does not eliminate credits.","Incorrect. Conversion is allowed."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Different land uses serve different credits, but each must meet its own requirements.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q018","core_concept_vi":"Các loại sử dụng đất phục vụ các tín chỉ khác nhau nhưng mỗi tín chỉ phải đáp ứng yêu cầu riêng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-519","source_index":519,"q":"Magnolia Laboratory uses 100% outside air with no recirculation for chemical safety. The IAQ consultant says this earns IAQ credit automatically; the energy consultant says it ruins energy credit. Who is right?","options":["Neither: 100% outside air is a safety requirement, not an IAQ credit, and the energy model uses lab-appropriate baselines","The IAQ consultant: it always earns IAQ credit","The energy consultant: labs cannot earn energy credit","Both are fully correct"],"answer":0,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; energy performance: the measured or modeled energy use of a building or system; credit: an optional LEED requirement that can earn points","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Required safety ventilation is not a credit strategy, and the baseline accounts for lab needs; energy recovery can still reduce load.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"baseline: đường cơ sở dùng để so sánh hiệu suất của dự án; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Thông gió an toàn bắt buộc không phải chiến lược lấy điểm và mức cơ sở đã tính nhu cầu phòng thí nghiệm; thu hồi năng lượng vẫn giảm tải. Vì vậy phương án A đúng.","options_vi":["Không ai đúng hoàn toàn: 100% gió ngoài là yêu cầu an toàn, không tự thành tín chỉ IAQ, và mô hình năng lượng dùng mức cơ sở phù hợp phòng thí nghiệm","Chuyên gia IAQ: luôn được tín chỉ IAQ","Chuyên gia năng lượng: phòng thí nghiệm không đạt tín chỉ năng lượng","Cả hai hoàn toàn đúng"],"evidence_en":"Required safety ventilation is not a credit strategy, and the baseline accounts for lab needs; energy recovery can still reduce load.","evidence_vi":"Thông gió an toàn bắt buộc không phải chiến lược lấy điểm và mức cơ sở đã tính nhu cầu phòng thí nghiệm; thu hồi năng lượng vẫn giảm tải.","mechanism_vi":"Thông gió an toàn bắt buộc không phải chiến lược lấy điểm và mức cơ sở đã tính nhu cầu phòng thí nghiệm; thu hồi năng lượng vẫn giảm tải. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Thông gió an toàn bắt buộc không phải chiến lược lấy điểm và mức cơ sở đã tính nhu cầu phòng thí nghiệm; thu hồi năng lượng vẫn giảm tải.","Sai. Yêu cầu không phải tín chỉ.","Sai. Phòng thí nghiệm đạt được tín chỉ năng lượng.","Sai. Không tuyên bố nào hoàn toàn đúng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 519; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. Required safety ventilation is not a credit strategy, and the baseline accounts for lab needs; energy recovery can still reduce load.","Incorrect. Requirement is not credit.","Incorrect. Labs can earn energy credit.","Incorrect. Neither claim is fully right."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Required safety ventilation is not a credit strategy, and the baseline accounts for lab needs; energy recovery can still reduce load.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q019","core_concept_vi":"Thông gió an toàn bắt buộc không phải chiến lược lấy điểm và mức cơ sở đã tính nhu cầu phòng thí nghiệm; thu hồi năng lượng vẫn giảm tải.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-520","source_index":520,"q":"A consultant tells Greentown Logistics Center that warehouses cannot earn location credits. Which response is accurate?","options":["Correct: logistics sites earn no location credits","Oversimplified: EV infrastructure, transportation demand management, and site-dependent credits remain achievable","Waived: location credits do not apply to industrial buildings","Warehouses earn the same as downtown offices"],"answer":1,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"brownfield: previously developed land with actual or perceived contamination; credit: an optional LEED requirement that can earn points; location and transportation: strategies that reduce travel impacts through site selection and mobility options","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Remote location limits transit-based points but not every location-related strategy.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm LT đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; location and transportation: vị trí và giao thông; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Vị trí xa hạn chế điểm dựa vào giao thông công cộng nhưng không phải mọi chiến lược liên quan vị trí. Vì vậy phương án B đúng.","options_vi":["Đúng: kho vận không có tín chỉ vị trí","Quá đơn giản: hạ tầng EV, quản lý nhu cầu đi lại và tín chỉ phụ thuộc khu đất vẫn đạt được","Miễn: tín chỉ vị trí không áp dụng cho công trình công nghiệp","Kho đạt như văn phòng trung tâm"],"evidence_en":"Remote location limits transit-based points but not every location-related strategy.","evidence_vi":"Vị trí xa hạn chế điểm dựa vào giao thông công cộng nhưng không phải mọi chiến lược liên quan vị trí.","mechanism_vi":"Vị trí xa hạn chế điểm dựa vào giao thông công cộng nhưng không phải mọi chiến lược liên quan vị trí. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Không phải mọi tín chỉ bị chặn.","Đúng. Vị trí xa hạn chế điểm dựa vào giao thông công cộng nhưng không phải mọi chiến lược liên quan vị trí.","Sai. Không được miễn.","Sai. Vị trí vẫn quan trọng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 520; Location & Transportation","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Not all credits are blocked.","Correct. Remote location limits transit-based points but not every location-related strategy.","Incorrect. They are not waived.","Incorrect. Location still matters."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"Remote location limits transit-based points but not every location-related strategy.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q020","core_concept_vi":"Vị trí xa hạn chế điểm dựa vào giao thông công cộng nhưng không phải mọi chiến lược liên quan vị trí.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-521","source_index":521,"q":"Forty-seven parents report headaches and eye irritation at Willowbrook Elementary, mostly in the new wing; symptoms improve on weekends. HVAC logs are normal. What is the best diagnostic step?","options":["Investigate systematically: air testing for CO₂ and VOCs, review recent material substitutions and actual ventilation","Raise ventilation across the school immediately","Call the complaints psychosomatic","Stop investigating since HVAC logs look normal"],"answer":0,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this best-fit question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"primarily: a word asking for the main or most direct purpose; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Weekend improvement points to a building source, so identify it before changing systems.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Triệu chứng giảm cuối tuần chỉ đến nguồn trong công trình nên phải xác định nguồn trước khi thay hệ thống. Vì vậy phương án A đúng.","options_vi":["Điều tra hệ thống: đo CO₂ và VOC, xem lại vật liệu thay thế gần đây và thông gió thực tế","Tăng thông gió toàn trường ngay","Cho rằng các phàn nàn là do tâm lý","Dừng điều tra vì nhật ký HVAC bình thường"],"evidence_en":"Weekend improvement points to a building source, so identify it before changing systems.","evidence_vi":"Triệu chứng giảm cuối tuần chỉ đến nguồn trong công trình nên phải xác định nguồn trước khi thay hệ thống.","mechanism_vi":"Triệu chứng giảm cuối tuần chỉ đến nguồn trong công trình nên phải xác định nguồn trước khi thay hệ thống. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Triệu chứng giảm cuối tuần chỉ đến nguồn trong công trình nên phải xác định nguồn trước khi thay hệ thống.","Sai. Thay đổi mù có thể không xử lý nguyên nhân.","Sai. Quy luật cho thấy có nguồn thực.","Sai. Nhật ký không đo phơi nhiễm."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 521; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. Weekend improvement points to a building source, so identify it before changing systems.","Incorrect. Blind changes may not fix the cause.","Incorrect. The pattern suggests a real source.","Incorrect. Logs do not measure exposure."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Weekend improvement points to a building source, so identify it before changing systems.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q021","core_concept_vi":"Triệu chứng giảm cuối tuần chỉ đến nguồn trong công trình nên phải xác định nguồn trước khi thay hệ thống.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-522","source_index":522,"q":"Meridian Convention Center is 80% through construction documents and has tracked no materials data; construction starts in six weeks. What should come first?","options":["Cancel the Gold target","Complete the embodied-carbon quantification prerequisite and set up tracking for the largest materials categories","Start tracking at day one and write off earlier work","Consider all materials credits lost"],"answer":1,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; documentation: records used to demonstrate compliance with a LEED requirement; triage: rapid prioritization of the most consequential actions under limited time or resources; EPD: an Environmental Product Declaration reporting verified life-cycle impacts; HPD: a Health Product Declaration reporting product ingredients and health information","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"The quantification prerequisite is mandatory and cannot be skipped, while selective tracking of major categories still captures most value.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu MR, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; triage: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; EPD: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tiên quyết định lượng là bắt buộc và không thể bỏ qua, còn theo dõi chọn lọc các nhóm lớn vẫn giữ phần lớn giá trị. Vì vậy phương án B đúng.","options_vi":["Hủy mục tiêu Gold","Hoàn tất tiên quyết định lượng carbon hàm chứa và thiết lập theo dõi cho các nhóm vật liệu lớn nhất","Bắt đầu theo dõi từ ngày một và bỏ phần việc trước","Coi mọi tín chỉ vật liệu đã mất"],"evidence_en":"The quantification prerequisite is mandatory and cannot be skipped, while selective tracking of major categories still captures most value.","evidence_vi":"Tiên quyết định lượng là bắt buộc và không thể bỏ qua, còn theo dõi chọn lọc các nhóm lớn vẫn giữ phần lớn giá trị.","mechanism_vi":"Tiên quyết định lượng là bắt buộc và không thể bỏ qua, còn theo dõi chọn lọc các nhóm lớn vẫn giữ phần lớn giá trị. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Gold vẫn đạt được.","Đúng. Tiên quyết định lượng là bắt buộc và không thể bỏ qua, còn theo dõi chọn lọc các nhóm lớn vẫn giữ phần lớn giá trị.","Sai. Dữ liệu trước đó có thể khôi phục.","Sai. Không phải mọi tín chỉ đều mất."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 522; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Gold is still reachable.","Correct. The quantification prerequisite is mandatory and cannot be skipped, while selective tracking of major categories still captures most value.","Incorrect. Earlier data can be recovered.","Incorrect. Credits are not all lost."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"The quantification prerequisite is mandatory and cannot be skipped, while selective tracking of major categories still captures most value.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q022","core_concept_vi":"Tiên quyết định lượng là bắt buộc và không thể bỏ qua, còn theo dõi chọn lọc các nhóm lớn vẫn giữ phần lớn giá trị.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-523","source_index":523,"q":"During functional testing at Pinnacle Research Tower, VAV minimum airflow setpoints are 40% above design, adding about 18% to annual fan and conditioning energy. What next?","options":["Accept them for better air quality","Set minimums to zero for savings","Issue a deficiency, reprogram the setpoints and retest before occupancy","Record it without correction"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"commissioning: a quality-focused process that verifies systems meet the owner’s project requirements; minimum: the lowest acceptable value or level; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Commissioning exists to correct deviations from design before they become operating costs.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"commissioning: quá trình xác minh có hệ thống rằng công trình và hệ thống đáp ứng OPR và BOD; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Commissioning tồn tại để sửa sai lệch so với thiết kế trước khi thành chi phí vận hành. Vì vậy phương án C đúng.","options_vi":["Chấp nhận vì chất lượng không khí tốt hơn","Đặt mức tối thiểu bằng không để tiết kiệm","Phát hành lỗi, lập trình lại điểm đặt và thử lại trước khi vào ở","Ghi nhận mà không sửa"],"evidence_en":"Commissioning exists to correct deviations from design before they become operating costs.","evidence_vi":"Commissioning tồn tại để sửa sai lệch so với thiết kế trước khi thành chi phí vận hành.","mechanism_vi":"Commissioning tồn tại để sửa sai lệch so với thiết kế trước khi thành chi phí vận hành. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Lưu lượng dư là lãng phí.","Sai. Lưu lượng bằng không phá thông gió.","Đúng. Commissioning tồn tại để sửa sai lệch so với thiết kế trước khi thành chi phí vận hành.","Sai. Báo cáo không sửa làm uổng phát hiện."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 523; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Excess airflow is waste.","Incorrect. Zero airflow breaks ventilation.","Correct. Commissioning exists to correct deviations from design before they become operating costs.","Incorrect. A report without correction wastes the finding."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Commissioning exists to correct deviations from design before they become operating costs.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q023","core_concept_vi":"Commissioning tồn tại để sửa sai lệch so với thiết kế trước khi thành chi phí vận hành.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-524","source_index":524,"q":"Centurion Law Firm's floors run at 150 sf per person while the base building supplies a fixed 12 cfm/person. With an office breathing-zone rate of 5 cfm/person plus 0.06 cfm/sf, what follows?","options":["12 cfm/person meets 62.1 at any density","Only CO₂ monitoring matters","The area component applies only to restaurants","The calculated need is about 14 cfm/person, so 12 is insufficient; use the full ASHRAE 62.1 calculation or demand-controlled ventilation"],"answer":3,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"minimum: the lowest acceptable value or level; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"5 + 0.06 × 150 = 14 cfm/person, above the 12 supplied.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"5 + 0,06 × 150 = 14 cfm/người, cao hơn 12 được cấp. Vì vậy phương án D đúng.","options_vi":["12 cfm/người đạt 62.1 ở mọi mật độ","Chỉ cần giám sát CO₂","Thành phần theo diện tích chỉ áp dụng cho nhà hàng","Nhu cầu tính được khoảng 14 cfm/người nên 12 là thiếu; dùng tính toán đầy đủ ASHRAE 62.1 hoặc điều khiển thông gió theo nhu cầu"],"evidence_en":"5 + 0.06 × 150 = 14 cfm/person, above the 12 supplied.","evidence_vi":"5 + 0,06 × 150 = 14 cfm/người, cao hơn 12 được cấp.","mechanism_vi":"5 + 0,06 × 150 = 14 cfm/người, cao hơn 12 được cấp. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Mật độ đổi yêu cầu.","Sai. CO₂ không phải phép tính.","Sai. Thành phần diện tích áp dụng mọi không gian.","Đúng. 5 + 0,06 × 150 = 14 cfm/người, cao hơn 12 được cấp."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 524; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Density changes the requirement.","Incorrect. CO₂ is not a calculation.","Incorrect. The area term applies to all spaces.","Correct. 5 + 0.06 × 150 = 14 cfm/person, above the 12 supplied."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"5 + 0.06 × 150 = 14 cfm/person, above the 12 supplied.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q024","core_concept_vi":"5 + 0,06 × 150 = 14 cfm/người, cao hơn 12 được cấp.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-525","source_index":525,"q":"Riverfront Office Tower has $12.5M of materials, with EPDs for $4.2M (34%) and HPDs for $3.8M (30%). How should the team estimate points?","options":["34% EPD earns 2 points and 30% HPD earns 1","Do not apply old cost-share rules; check the current v5 product selection credit's options and documentation requirements","Any product with both documents earns the maximum","Only products with both documents count"],"answer":1,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; maximum: the highest permitted value or level; EPD: an Environmental Product Declaration reporting verified life-cycle impacts; HPD: a Health Product Declaration reporting product ingredients and health information","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"v5 restructured product credits, so percentages from earlier versions cannot be assumed to apply.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc MR vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; maximum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; EPD: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; HPD: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"v5 tái cấu trúc tín chỉ sản phẩm nên không thể mặc định áp dụng tỷ lệ phần trăm của phiên bản trước. Vì vậy phương án B đúng.","options_vi":["34% EPD được 2 điểm và 30% HPD được 1 điểm","Không áp dụng quy tắc tỷ lệ chi phí cũ; kiểm tra các lựa chọn và yêu cầu hồ sơ của tín chỉ chọn sản phẩm v5 hiện hành","Sản phẩm có cả hai hồ sơ được điểm tối đa","Chỉ sản phẩm có cả hai hồ sơ được tính"],"evidence_en":"v5 restructured product credits, so percentages from earlier versions cannot be assumed to apply.","evidence_vi":"v5 tái cấu trúc tín chỉ sản phẩm nên không thể mặc định áp dụng tỷ lệ phần trăm của phiên bản trước.","mechanism_vi":"v5 tái cấu trúc tín chỉ sản phẩm nên không thể mặc định áp dụng tỷ lệ phần trăm của phiên bản trước. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Ngưỡng cũ có thể không áp dụng.","Đúng. v5 tái cấu trúc tín chỉ sản phẩm nên không thể mặc định áp dụng tỷ lệ phần trăm của phiên bản trước.","Sai. Có cả hai không bảo đảm điểm tối đa.","Sai. Sản phẩm có một hồ sơ vẫn có thể tính."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 525; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Old thresholds may not apply.","Correct. v5 restructured product credits, so percentages from earlier versions cannot be assumed to apply.","Incorrect. Having both does not guarantee maximum.","Incorrect. Products with one document may count."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"v5 restructured product credits, so percentages from earlier versions cannot be assumed to apply.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q025","core_concept_vi":"v5 tái cấu trúc tín chỉ sản phẩm nên không thể mặc định áp dụng tỷ lệ phần trăm của phiên bản trước.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-526","source_index":526,"q":"Lakeshore Tower has a 15,000 sf roof, 1.2 in/month of summer rain, 85% capture efficiency and 500 gal/day of toilet demand. Is the cistern enough?","options":["No: about 9,500 gal/month is captured against 15,000 gal/month demand (≈64%), so a backup supply is needed","Yes: about 11,970 gal/month covers 80%","Yes, since any 15,000 sf roof is sufficient","No credit is possible unless 100% is met"],"answer":0,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the WE concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; documentation: records used to demonstrate compliance with a LEED requirement; water efficiency: reduction and responsible management of indoor, outdoor, and process water use","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"15,000 sf × 0.1 ft × 7.48 ≈ 11,200 gal; × 0.85 ≈ 9,500 gal, compared with 15,000 gal of demand.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm WE đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; water efficiency: hiệu quả sử dụng nước; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"15.000 sf × 0,1 ft × 7,48 ≈ 11.200 gal; × 0,85 ≈ 9.500 gal, so với nhu cầu 15.000 gal. Vì vậy phương án A đúng.","options_vi":["Không: thu khoảng 9.500 gal/tháng so với nhu cầu 15.000 gal/tháng (≈64%) nên cần nguồn dự phòng","Có: khoảng 11.970 gal/tháng đáp ứng 80%","Có vì mái 15.000 sf nào cũng đủ","Không được tín chỉ nếu chưa đạt 100%"],"evidence_en":"15,000 sf × 0.1 ft × 7.48 ≈ 11,200 gal; × 0.85 ≈ 9,500 gal, compared with 15,000 gal of demand.","evidence_vi":"15.000 sf × 0,1 ft × 7,48 ≈ 11.200 gal; × 0,85 ≈ 9.500 gal, so với nhu cầu 15.000 gal.","mechanism_vi":"15.000 sf × 0,1 ft × 7,48 ≈ 11.200 gal; × 0,85 ≈ 9.500 gal, so với nhu cầu 15.000 gal. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. 15.000 sf × 0,1 ft × 7,48 ≈ 11.200 gal; × 0,85 ≈ 9.500 gal, so với nhu cầu 15.000 gal.","Sai. Phép tính thổi phồng lượng thu.","Sai. Chỉ diện tích mái không bảo đảm nguồn cấp.","Sai. Cấp một phần vẫn có giá trị."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 526; Water Efficiency","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. 15,000 sf × 0.1 ft × 7.48 ≈ 11,200 gal; × 0.85 ≈ 9,500 gal, compared with 15,000 gal of demand.","Incorrect. The arithmetic overstates capture.","Incorrect. Roof area alone does not guarantee supply.","Incorrect. Partial supply still has value."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"15,000 sf × 0.1 ft × 7.48 ≈ 11,200 gal; × 0.85 ≈ 9,500 gal, compared with 15,000 gal of demand.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q026","core_concept_vi":"15.000 sf × 0,1 ft × 7,48 ≈ 11.200 gal; × 0,85 ≈ 9.500 gal, so với nhu cầu 15.000 gal.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-527","source_index":527,"q":"Cascade Tech Campus earned LEED Platinum under BD+C in 2017. What is the most accurate guidance?","options":["The design-and-construction certification does not expire but does not verify current performance; consider operations certification","It expired in 2022","It is permanent and needs nothing","The plaque alone satisfies ESG reporting"],"answer":0,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"certification: third-party confirmation that a project satisfies applicable LEED requirements; LEED: a third-party green building rating and certification system; compliance: satisfaction of the applicable requirement and documentation","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"BD+C recognizes design and construction at a point in time; operating performance is addressed by operations certification.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm Overview đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"BD+C ghi nhận thiết kế và thi công tại một thời điểm; hiệu năng vận hành thuộc chứng nhận vận hành. Vì vậy phương án A đúng.","options_vi":["Chứng nhận thiết kế và xây dựng không hết hạn nhưng không xác nhận hiệu năng hiện tại; cân nhắc chứng nhận vận hành","Đã hết hạn năm 2022","Là vĩnh viễn và không cần gì","Chỉ bảng chứng nhận là đủ cho báo cáo ESG"],"evidence_en":"BD+C recognizes design and construction at a point in time; operating performance is addressed by operations certification.","evidence_vi":"BD+C ghi nhận thiết kế và thi công tại một thời điểm; hiệu năng vận hành thuộc chứng nhận vận hành.","mechanism_vi":"BD+C ghi nhận thiết kế và thi công tại một thời điểm; hiệu năng vận hành thuộc chứng nhận vận hành. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. BD+C ghi nhận thiết kế và thi công tại một thời điểm; hiệu năng vận hành thuộc chứng nhận vận hành.","Sai. BD+C không hết hạn.","Sai. Vĩnh viễn không có nghĩa hiện hành.","Sai. Bảng chứng nhận không phải dữ liệu hiệu năng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 527; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. BD+C recognizes design and construction at a point in time; operating performance is addressed by operations certification.","Incorrect. BD+C does not expire.","Incorrect. Permanent does not imply current.","Incorrect. A plaque is not performance data."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"BD+C recognizes design and construction at a point in time; operating performance is addressed by operations certification.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q027","core_concept_vi":"BD+C ghi nhận thiết kế và thi công tại một thời điểm; hiệu năng vận hành thuộc chứng nhận vận hành.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-528","source_index":528,"q":"A startup proposes 400 air-purifying plants to replace mechanical ventilation in a 200-person office. What should the consultant advise?","options":["Plants fully replace mechanical ventilation","Plants do not replace ventilation; add them only for biophilic benefit","Plants earn IAQ credit by themselves","Install plants only if the HVAC is removed"],"answer":1,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"mechanical ventilation: outdoor air supplied by fans and ducted systems; credit: an optional LEED requirement that can earn points; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Plants remove negligible contaminant mass compared with outdoor air exchange.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Cây loại bỏ khối lượng chất ô nhiễm không đáng kể so với trao đổi gió ngoài. Vì vậy phương án B đúng.","options_vi":["Cây thay hoàn toàn thông gió cơ khí","Cây không thay thông gió; chỉ thêm để lợi ích sinh học","Cây tự được tín chỉ IAQ","Chỉ trồng cây nếu bỏ HVAC"],"evidence_en":"Plants remove negligible contaminant mass compared with outdoor air exchange.","evidence_vi":"Cây loại bỏ khối lượng chất ô nhiễm không đáng kể so với trao đổi gió ngoài.","mechanism_vi":"Cây loại bỏ khối lượng chất ô nhiễm không đáng kể so với trao đổi gió ngoài. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Thông gió vẫn bắt buộc.","Đúng. Cây loại bỏ khối lượng chất ô nhiễm không đáng kể so với trao đổi gió ngoài.","Sai. Tín chỉ cần hiệu quả kiểm chứng.","Sai. Bỏ HVAC vi phạm yêu cầu."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 528; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Ventilation remains required.","Correct. Plants remove negligible contaminant mass compared with outdoor air exchange.","Incorrect. Credit needs verified effect.","Incorrect. Removing HVAC breaks requirements."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Plants remove negligible contaminant mass compared with outdoor air exchange.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q028","core_concept_vi":"Cây loại bỏ khối lượng chất ô nhiễm không đáng kể so với trao đổi gió ngoài.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-529","source_index":529,"q":"Lakewood Senior Living has independent apartments, assisted living and memory care. How should the energy model handle baselines?","options":["Model everything as an office","Treat memory care and assisted living identically","Apply the correct baseline for each space type and combine by area","Exempt senior living"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; energy model: a simulation used to estimate and compare building energy performance; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Different uses carry different loads and baseline requirements.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"baseline: đường cơ sở dùng để so sánh hiệu suất của dự án; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Các chức năng khác nhau có tải và yêu cầu mức cơ sở khác nhau. Vì vậy phương án C đúng.","options_vi":["Mô hình tất cả như văn phòng","Coi chăm sóc trí nhớ và hỗ trợ sinh hoạt như nhau","Áp dụng mức cơ sở đúng cho từng loại không gian và gộp theo diện tích","Miễn trừ nhà dưỡng lão"],"evidence_en":"Different uses carry different loads and baseline requirements.","evidence_vi":"Các chức năng khác nhau có tải và yêu cầu mức cơ sở khác nhau.","mechanism_vi":"Các chức năng khác nhau có tải và yêu cầu mức cơ sở khác nhau. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Văn phòng khác.","Sai. Mức chăm sóc khác.","Đúng. Các chức năng khác nhau có tải và yêu cầu mức cơ sở khác nhau.","Sai. Không có miễn trừ."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 529; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Offices differ.","Incorrect. Care levels differ.","Correct. Different uses carry different loads and baseline requirements.","Incorrect. There is no exemption."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Different uses carry different loads and baseline requirements.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q029","core_concept_vi":"Các chức năng khác nhau có tải và yêu cầu mức cơ sở khác nhau.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-530","source_index":530,"q":"The Orion Data Center is a 200,000 sf facility with 60% data hall space. Which rating system fits?","options":["BD+C: New Construction for more points","BD+C: Data Centers, which uses baselines suited to continuous high-density loads","O+M because data centers run 24/7","Certify only the offices"],"answer":1,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the Overview concept and solve this best-fit question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; most appropriate: a phrase asking for the option that best fits all stated conditions; LEED: a third-party green building rating and certification system","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"The specific rating system fits the building type and its energy baseline.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc Overview vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"baseline: đường cơ sở dùng làm mốc so sánh hiệu suất; credit: yêu cầu tự chọn có thể mang lại điểm; most appropriate: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; LEED: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Hệ thống chuyên biệt phù hợp loại công trình và mức cơ sở năng lượng. Vì vậy phương án B đúng.","options_vi":["BD+C: New Construction vì nhiều điểm hơn","BD+C: Data Centers với mức cơ sở phù hợp tải liên tục mật độ cao","O+M vì trung tâm dữ liệu chạy 24/7","Chỉ chứng nhận phần văn phòng"],"evidence_en":"The specific rating system fits the building type and its energy baseline.","evidence_vi":"Hệ thống chuyên biệt phù hợp loại công trình và mức cơ sở năng lượng.","mechanism_vi":"Hệ thống chuyên biệt phù hợp loại công trình và mức cơ sở năng lượng. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Số điểm không quyết định.","Đúng. Hệ thống chuyên biệt phù hợp loại công trình và mức cơ sở năng lượng.","Sai. O+M dành cho vận hành hiện hữu.","Sai. Loại phòng máy bỏ sót phần lớn năng lượng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 530; LEED Overview & Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Points do not decide.","Correct. The specific rating system fits the building type and its energy baseline.","Incorrect. O+M is for existing operations.","Incorrect. Excluding halls omits most energy."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"The specific rating system fits the building type and its energy baseline.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q030","core_concept_vi":"Hệ thống chuyên biệt phù hợp loại công trình và mức cơ sở năng lượng.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-531","source_index":531,"q":"Cascade Tech Park will electrify its four buildings in two phases, two this year and two in year three. How does this affect documentation?","options":["Phased work cannot be documented","Credit is earned for the whole campus immediately","Electric equipment must replace gas regardless of cost","Points follow installed equipment; the later phase belongs in the documented decarbonization plan"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; documentation: records used to demonstrate compliance with a LEED requirement; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Credits reflect what is built; future phases are planning, not points.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu EA, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy and atmosphere: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tín chỉ phản ánh phần đã xây; giai đoạn tương lai là kế hoạch, không phải điểm. Vì vậy phương án D đúng.","options_vi":["Làm theo giai đoạn không thể lập hồ sơ","Được tín chỉ cho cả khuôn viên ngay lập tức","Thiết bị điện phải thay khí bất kể chi phí","Điểm theo thiết bị đã lắp; giai đoạn sau thuộc kế hoạch khử carbon có hồ sơ"],"evidence_en":"Credits reflect what is built; future phases are planning, not points.","evidence_vi":"Tín chỉ phản ánh phần đã xây; giai đoạn tương lai là kế hoạch, không phải điểm.","mechanism_vi":"Tín chỉ phản ánh phần đã xây; giai đoạn tương lai là kế hoạch, không phải điểm. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Kế hoạch có thể lập hồ sơ.","Sai. Giai đoạn chưa xây không có điểm.","Sai. Chi phí là một phần kế hoạch.","Đúng. Tín chỉ phản ánh phần đã xây; giai đoạn tương lai là kế hoạch, không phải điểm."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 531; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Plans can be documented.","Incorrect. Unbuilt phases earn nothing.","Incorrect. Cost is part of planning.","Correct. Credits reflect what is built; future phases are planning, not points."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Credits reflect what is built; future phases are planning, not points.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q031","core_concept_vi":"Tín chỉ phản ánh phần đã xây; giai đoạn tương lai là kế hoạch, không phải điểm.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-532","source_index":532,"q":"Veritas University Library's building automation system has run in occupied mode all 8,760 hours instead of the designed 3,500 for 18 months. What is the best course?","options":["Revoke certification","Leave it, as continuous operation is required","Correct through retro-commissioning and restore schedules; certification status is unaffected","Treat it as a water issue"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"commissioning: a quality-focused process that verifies systems meet the owner’s project requirements; water efficiency: the reduction and responsible management of potable and process water use; credit: an optional LEED requirement that can earn points; certification: third-party confirmation that a project satisfies applicable LEED requirements","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Controls drift is a performance problem fixed by correcting schedules, not a certification matter.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; commissioning: quá trình xác minh có hệ thống rằng công trình và hệ thống đáp ứng OPR và BOD; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; water efficiency: hiệu quả sử dụng nước","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Lệch điều khiển là vấn đề hiệu năng được sửa bằng cách chỉnh lịch, không phải vấn đề chứng nhận. Vì vậy phương án C đúng.","options_vi":["Thu hồi chứng nhận","Giữ nguyên vì vận hành liên tục là bắt buộc","Sửa bằng retro-commissioning và khôi phục lịch vận hành; trạng thái chứng nhận không bị ảnh hưởng","Coi là vấn đề nước"],"evidence_en":"Controls drift is a performance problem fixed by correcting schedules, not a certification matter.","evidence_vi":"Lệch điều khiển là vấn đề hiệu năng được sửa bằng cách chỉnh lịch, không phải vấn đề chứng nhận.","mechanism_vi":"Lệch điều khiển là vấn đề hiệu năng được sửa bằng cách chỉnh lịch, không phải vấn đề chứng nhận. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Chứng nhận không bị thu hồi vì điều này.","Sai. Không bắt buộc vận hành liên tục.","Đúng. Lệch điều khiển là vấn đề hiệu năng được sửa bằng cách chỉnh lịch, không phải vấn đề chứng nhận.","Sai. Đây là vấn đề năng lượng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 532; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Certification is not revoked for this.","Incorrect. Continuous operation is not required.","Correct. Controls drift is a performance problem fixed by correcting schedules, not a certification matter.","Incorrect. It is an energy issue."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Controls drift is a performance problem fixed by correcting schedules, not a certification matter.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q032","core_concept_vi":"Lệch điều khiển là vấn đề hiệu năng được sửa bằng cách chỉnh lịch, không phải vấn đề chứng nhận.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-533","source_index":533,"q":"Cedar Grove Business Park wants a central graywater system serving toilets in eight buildings. What should be checked first?","options":["Whether women's restrooms supply the water","Nothing; it earns every water credit","Local codes for multi-building distribution, plus submetering and potable backup","It is prohibited"],"answer":2,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the WE concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"cooling tower: heat-rejection equipment that commonly uses evaporation; submetering: separate measurement of water or energy use by system or end use; credit: an optional LEED requirement that can earn points; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Reuse systems depend on local approval and verification.","purpose_vi":"Kiểm tra khả năng xác định đúng hồ sơ hoặc dữ liệu dùng để chứng minh yêu cầu WE, không nhầm với tài liệu có chức năng khác.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Hệ thống tái sử dụng phụ thuộc phê duyệt và kiểm chứng tại địa phương. Vì vậy phương án C đúng.","options_vi":["Nước có từ nhà vệ sinh nữ hay không","Không cần gì; được mọi tín chỉ nước","Quy định địa phương về phân phối nhiều tòa nhà, cùng đo phụ và nguồn nước uống dự phòng","Bị cấm"],"evidence_en":"Reuse systems depend on local approval and verification.","evidence_vi":"Hệ thống tái sử dụng phụ thuộc phê duyệt và kiểm chứng tại địa phương.","mechanism_vi":"Hệ thống tái sử dụng phụ thuộc phê duyệt và kiểm chứng tại địa phương. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Giới tính nguồn nước không liên quan.","Sai. Tín chỉ cần hồ sơ.","Đúng. Hệ thống tái sử dụng phụ thuộc phê duyệt và kiểm chứng tại địa phương.","Sai. Không bị cấm."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 533; Water Efficiency","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Source gender is irrelevant.","Incorrect. Credits require documentation.","Correct. Reuse systems depend on local approval and verification.","Incorrect. It is not prohibited."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Reuse systems depend on local approval and verification.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q033","core_concept_vi":"Hệ thống tái sử dụng phụ thuộc phê duyệt và kiểm chứng tại địa phương.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-534","source_index":534,"q":"Summit Hotel's $2.4M of furniture has no EPDs or HPDs. What is the best approach?","options":["Replace all furniture","Claim credit without documents","Remove all furniture","Request disclosure from suppliers or define the scope consistently, documenting any exclusion"],"answer":3,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this best-fit question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"best: a word asking for the strongest or most effective option; documentation: records used to demonstrate compliance with a LEED requirement; EPD: an Environmental Product Declaration reporting verified life-cycle impacts; HPD: a Health Product Declaration reporting product ingredients and health information","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Asking suppliers first, then defining scope transparently, avoids wasteful replacement.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc MR vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; best: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; EPD: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Hỏi nhà cung cấp trước rồi xác định phạm vi minh bạch tránh thay thế lãng phí. Vì vậy phương án D đúng.","options_vi":["Thay toàn bộ nội thất","Xin tín chỉ không cần hồ sơ","Gỡ toàn bộ nội thất","Yêu cầu nhà cung cấp công bố hoặc xác định phạm vi nhất quán và ghi rõ phần loại trừ"],"evidence_en":"Asking suppliers first, then defining scope transparently, avoids wasteful replacement.","evidence_vi":"Hỏi nhà cung cấp trước rồi xác định phạm vi minh bạch tránh thay thế lãng phí.","mechanism_vi":"Hỏi nhà cung cấp trước rồi xác định phạm vi minh bạch tránh thay thế lãng phí. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Thay thế là quá mức.","Sai. Tuyên bố cần bằng chứng.","Sai. Gỡ bỏ là không cần thiết.","Đúng. Hỏi nhà cung cấp trước rồi xác định phạm vi minh bạch tránh thay thế lãng phí."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 534; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Replacement is excessive.","Incorrect. Claims need evidence.","Incorrect. Removal is unnecessary.","Correct. Asking suppliers first, then defining scope transparently, avoids wasteful replacement."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Asking suppliers first, then defining scope transparently, avoids wasteful replacement.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q034","core_concept_vi":"Hỏi nhà cung cấp trước rồi xác định phạm vi minh bạch tránh thay thế lãng phí.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-535","source_index":535,"q":"Millbrook Headquarters is 400 m from stops of three bus routes with 50, 30 and 12 weekday trips. A colleague says only Route 1 counts. Who is right?","options":["Right: overlapping routes cancel","Only the highest-frequency route counts","The colleague is wrong: trips from qualifying routes add together, here 92 weekday trips","Only rail counts"],"answer":2,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; location and transportation: strategies that reduce travel impacts through site selection and mobility options; transportation demand management: programs that reduce single-occupancy vehicle travel and parking demand","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"50 + 30 + 12 = 92 trips; service adds together.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc LT vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; location and transportation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; transportation demand management: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"50 + 30 + 12 = 92 chuyến; dịch vụ cộng dồn. Vì vậy phương án C đúng.","options_vi":["Đúng: tuyến chồng nhau triệt tiêu","Chỉ tuyến tần suất cao nhất được tính","Đồng nghiệp sai: chuyến của các tuyến đủ điều kiện cộng lại, ở đây 92 chuyến ngày thường","Chỉ đường sắt được tính"],"evidence_en":"50 + 30 + 12 = 92 trips; service adds together.","evidence_vi":"50 + 30 + 12 = 92 chuyến; dịch vụ cộng dồn.","mechanism_vi":"50 + 30 + 12 = 92 chuyến; dịch vụ cộng dồn. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Các tuyến cộng dồn.","Sai. Tần suất cộng dồn.","Đúng. 50 + 30 + 12 = 92 chuyến; dịch vụ cộng dồn.","Sai. Xe buýt có thể tính."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 535; Location & Transportation","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Routes add.","Incorrect. Frequency sums.","Correct. 50 + 30 + 12 = 92 trips; service adds together.","Incorrect. Buses can count."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"50 + 30 + 12 = 92 trips; service adds together.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q035","core_concept_vi":"50 + 30 + 12 = 92 chuyến; dịch vụ cộng dồn.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-536","source_index":536,"q":"Aurora Heights uses 2,000,000 kWh/year. Option A is 500,000 kWh/year of on-site PV; option B is a PPA for 100% renewable electricity. How should they be compared?","options":["The two earn identical points","Neither earns points","The PPA always outranks PV","PV covers 25% of use and the PPA up to 100%, so compare coverage and renewable tier together rather than assume one is better"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"renewable energy: energy from sources that are naturally replenished; credit: an optional LEED requirement that can earn points; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"500,000 ÷ 2,000,000 = 25%; strategies differ in coverage and in how they are classified.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"500.000 ÷ 2.000.000 = 25%; các chiến lược khác nhau về mức phủ và cách phân loại. Vì vậy phương án D đúng.","options_vi":["Hai phương án được điểm như nhau","Không phương án nào được điểm","PPA luôn hơn PV","PV phủ 25% mức dùng còn PPA tới 100%, nên so sánh cả mức phủ và bậc năng lượng tái tạo thay vì giả định bên nào tốt hơn"],"evidence_en":"500,000 ÷ 2,000,000 = 25%; strategies differ in coverage and in how they are classified.","evidence_vi":"500.000 ÷ 2.000.000 = 25%; các chiến lược khác nhau về mức phủ và cách phân loại.","mechanism_vi":"500.000 ÷ 2.000.000 = 25%; các chiến lược khác nhau về mức phủ và cách phân loại. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Mức phủ khác nhau.","Sai. Cả hai có thể được tính.","Sai. Xếp hạng phụ thuộc phân loại.","Đúng. 500.000 ÷ 2.000.000 = 25%; các chiến lược khác nhau về mức phủ và cách phân loại."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 536; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Coverage differs.","Incorrect. Both can count.","Incorrect. Rank depends on classification.","Correct. 500,000 ÷ 2,000,000 = 25%; strategies differ in coverage and in how they are classified."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"500,000 ÷ 2,000,000 = 25%; strategies differ in coverage and in how they are classified.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q036","core_concept_vi":"500.000 ÷ 2.000.000 = 25%; các chiến lược khác nhau về mức phủ và cách phân loại.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-537","source_index":537,"q":"Crystal Tower Hotel has 450 rooms, a 200-seat restaurant, a pool and a 2,000-ton cooling plant. How should conservation be prioritized?","options":["Start with the pool, as it is visible","Start with showerheads, as guests see them","Build a water balance and target the largest metered uses first","Treat all uses as equal"],"answer":2,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the WE concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"cooling tower: heat-rejection equipment that commonly uses evaporation; water efficiency: reduction and responsible management of indoor, outdoor, and process water use; water performance: measured water consumption and the effectiveness of water-saving strategies","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Savings come from the biggest uses, which only a balance reveals.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm WE đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"water efficiency: hiệu quả sử dụng nước; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tiết kiệm đến từ các hạng mục lớn nhất, chỉ cân bằng nước mới cho thấy. Vì vậy phương án C đúng.","options_vi":["Bắt đầu với hồ bơi vì dễ thấy","Bắt đầu với vòi sen vì khách thấy","Lập cân bằng nước và nhắm vào các hạng mục dùng nhiều nhất đã đo trước","Coi mọi hạng mục như nhau"],"evidence_en":"Savings come from the biggest uses, which only a balance reveals.","evidence_vi":"Tiết kiệm đến từ các hạng mục lớn nhất, chỉ cân bằng nước mới cho thấy.","mechanism_vi":"Tiết kiệm đến từ các hạng mục lớn nhất, chỉ cân bằng nước mới cho thấy. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Dễ thấy không phải lượng lớn.","Sai. Vòi sen có thể không chiếm nhiều.","Đúng. Tiết kiệm đến từ các hạng mục lớn nhất, chỉ cân bằng nước mới cho thấy.","Sai. Các hạng mục không bằng nhau."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 537; Water Efficiency","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Visibility is not volume.","Incorrect. Showerheads may not dominate.","Correct. Savings come from the biggest uses, which only a balance reveals.","Incorrect. Uses are not equal."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Savings come from the biggest uses, which only a balance reveals.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q037","core_concept_vi":"Tiết kiệm đến từ các hạng mục lớn nhất, chỉ cân bằng nước mới cho thấy.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-538","source_index":538,"q":"Controls at Ridgewood Office Park fail in a storm and turbid water reaches a stream for four hours before repair. How does it affect the runoff prerequisite?","options":["A single event fails it","Only discharges above 24 hours matter","One brief, promptly corrected and documented event does not by itself fail the prerequisite, but permit reporting and corrective action still apply","It must be reported to GBCI within 24 hours"],"answer":2,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the SS concept and solve this sequence question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"construction activity pollution prevention: measures that prevent soil erosion, sedimentation, and construction-related pollution; erosion control: a measure that prevents soil from being detached and transported; prerequisite: a mandatory requirement that earns no points but is required for certification; certification: third-party confirmation that a project satisfies applicable LEED requirements","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Prompt correction and records show the plan worked as intended, while regulatory reporting remains.","purpose_vi":"Kiểm tra khả năng xác định đúng trình tự hành động trong nhóm SS, khi thời điểm thực hiện quyết định hiệu quả của giải pháp.","vocabulary_vi":"prerequisite: điều kiện tiên quyết bắt buộc, không mang điểm; erosion control: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Khắc phục kịp thời và hồ sơ cho thấy kế hoạch vận hành đúng, còn báo cáo pháp lý vẫn có. Vì vậy phương án C đúng.","options_vi":["Một sự cố là hỏng","Chỉ xả trên 24 giờ mới tính","Một sự cố ngắn được khắc phục kịp thời và có hồ sơ không tự làm hỏng tiên quyết, nhưng báo cáo theo giấy phép và hành động khắc phục vẫn áp dụng","Phải báo cáo GBCI trong 24 giờ"],"evidence_en":"Prompt correction and records show the plan worked as intended, while regulatory reporting remains.","evidence_vi":"Khắc phục kịp thời và hồ sơ cho thấy kế hoạch vận hành đúng, còn báo cáo pháp lý vẫn có.","mechanism_vi":"Khắc phục kịp thời và hồ sơ cho thấy kế hoạch vận hành đúng, còn báo cáo pháp lý vẫn có. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Không có quy tắc tự động.","Sai. Không có quy tắc 24 giờ.","Đúng. Khắc phục kịp thời và hồ sơ cho thấy kế hoạch vận hành đúng, còn báo cáo pháp lý vẫn có.","Sai. Nghĩa vụ báo cáo là với cơ quan quản lý."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 538; Sustainable Sites","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. No such automatic rule.","Incorrect. No 24-hour rule.","Correct. Prompt correction and records show the plan worked as intended, while regulatory reporting remains.","Incorrect. The reporting duty is to regulators."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Prompt correction and records show the plan worked as intended, while regulatory reporting remains.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q038","core_concept_vi":"Khắc phục kịp thời và hồ sơ cho thấy kế hoạch vận hành đúng, còn báo cáo pháp lý vẫn có.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-539","source_index":539,"q":"Aurora Pharmaceutical's fume hood sashes average 18 inches open versus 6 inches recommended, and each extra inch adds ~5% to exhaust energy. What is the integrated solution?","options":["VAV hoods with sash management and researcher training: safer containment and lower energy","Accept current practice","Add more filtration","Replace every hood with air-curtain hoods"],"answer":0,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"best: a word asking for the strongest or most effective option; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Lower sash height reduces exhaust volume and improves containment.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Hạ cửa chắn giảm lưu lượng hút và cải thiện kiểm soát. Vì vậy phương án A đúng.","options_vi":["Tủ hút VAV với quản lý cửa chắn và đào tạo nhà nghiên cứu: an toàn hơn và ít năng lượng hơn","Chấp nhận thực hành hiện tại","Thêm lọc","Thay mọi tủ bằng tủ màn khí"],"evidence_en":"Lower sash height reduces exhaust volume and improves containment.","evidence_vi":"Hạ cửa chắn giảm lưu lượng hút và cải thiện kiểm soát.","mechanism_vi":"Hạ cửa chắn giảm lưu lượng hút và cải thiện kiểm soát. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Hạ cửa chắn giảm lưu lượng hút và cải thiện kiểm soát.","Sai. Lãng phí.","Sai. Lọc không sửa lưu lượng.","Sai. Thay hàng loạt là không cần."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 539; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. Lower sash height reduces exhaust volume and improves containment.","Incorrect. Wasteful.","Incorrect. Filtration does not fix airflow.","Incorrect. Wholesale replacement is unnecessary."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Lower sash height reduces exhaust volume and improves containment.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q039","core_concept_vi":"Hạ cửa chắn giảm lưu lượng hút và cải thiện kiểm soát.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-540","source_index":540,"q":"A post-occupancy survey shows 65% thermal, 72% lighting and 82% air-quality satisfaction against an 80% goal. With limited funds, what is the priority?","options":["Air quality, as it meets the goal","Equal spending on all","Thermal comfort first (largest gap), then lighting","Replace all HVAC"],"answer":2,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"thermal comfort: satisfaction with the thermal environment; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Funds go first to the largest shortfall against the goal: 15 points on thermal, 8 on lighting, none on air.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EQ vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"thermal comfort: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; indoor environmental quality: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; occupant health: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Ngân sách ưu tiên khoảng thiếu lớn nhất: 15 điểm ở nhiệt, 8 ở chiếu sáng, 0 ở không khí. Vì vậy phương án C đúng.","options_vi":["Chất lượng không khí vì đã đạt mục tiêu","Chi đều cho tất cả","Tiện nghi nhiệt trước (chênh lệch lớn nhất), rồi chiếu sáng","Thay toàn bộ HVAC"],"evidence_en":"Funds go first to the largest shortfall against the goal: 15 points on thermal, 8 on lighting, none on air.","evidence_vi":"Ngân sách ưu tiên khoảng thiếu lớn nhất: 15 điểm ở nhiệt, 8 ở chiếu sáng, 0 ở không khí.","mechanism_vi":"Ngân sách ưu tiên khoảng thiếu lớn nhất: 15 điểm ở nhiệt, 8 ở chiếu sáng, 0 ở không khí. Vì vậy phương án C đúng.","wrong_reasons_vi":["Sai. Không khí đã đạt 80%.","Sai. Chi đều bỏ qua khoảng cách.","Đúng. Ngân sách ưu tiên khoảng thiếu lớn nhất: 15 điểm ở nhiệt, 8 ở chiếu sáng, 0 ở không khí.","Sai. Chênh 15 điểm không có nghĩa hỏng."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 540; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Air already meets 80%.","Incorrect. Equal spending ignores gaps.","Correct. Funds go first to the largest shortfall against the goal: 15 points on thermal, 8 on lighting, none on air.","Incorrect. A 15-point gap does not imply failure."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Funds go first to the largest shortfall against the goal: 15 points on thermal, 8 on lighting, none on air.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q040","core_concept_vi":"Ngân sách ưu tiên khoảng thiếu lớn nhất: 15 điểm ở nhiệt, 8 ở chiếu sáng, 0 ở không khí.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-541","source_index":541,"q":"After abatement and clearance testing, concrete from a 1960s laboratory meets regulatory standards. Can it count toward construction waste diversion?","options":["No, asbestos buildings must be landfilled","Yes, if properly abated, cleared and recycled","Only at 50% value","Never"],"answer":1,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the MR concept and solve this sequence question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"waste diversion: keeping waste out of landfill or incineration through reuse, recycling, or recovery; best: a word asking for the strongest or most effective option; materials and resources: strategies addressing life-cycle impacts, product selection, sourcing, and waste","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Once materials pass clearance and are recycled, they are diverted.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm MR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"materials and resources: vật liệu và tài nguyên; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Khi vật liệu qua thông quan và được tái chế thì được tính là chuyển hướng. Vì vậy phương án B đúng.","options_vi":["Không, công trình có amiăng phải chôn lấp","Có, nếu đã xử lý, thông quan và tái chế đúng cách","Chỉ tính 50% giá trị","Không bao giờ"],"evidence_en":"Once materials pass clearance and are recycled, they are diverted.","evidence_vi":"Khi vật liệu qua thông quan và được tái chế thì được tính là chuyển hướng.","mechanism_vi":"Khi vật liệu qua thông quan và được tái chế thì được tính là chuyển hướng. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Vật liệu đã thông quan có thể tái chế.","Đúng. Khi vật liệu qua thông quan và được tái chế thì được tính là chuyển hướng.","Sai. Không có quy tắc chôn lấp tự động.","Sai. Không có quy tắc một phần."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 541; Materials & Resources","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Cleared material can be recycled.","Correct. Once materials pass clearance and are recycled, they are diverted.","Incorrect. No automatic landfill rule.","Incorrect. No partial rule."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Once materials pass clearance and are recycled, they are diverted.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q041","core_concept_vi":"Khi vật liệu qua thông quan và được tái chế thì được tính là chuyển hướng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-542","source_index":542,"q":"A concrete truck overturns and spills about 500 gallons near a storm drain. What is the right response?","options":["Wait for it to harden","Contain, clean up, document and report per the site's pollution prevention plan","Wash it down with a hose","Clean the visible part and continue"],"answer":1,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"sustainable sites: strategies that protect site ecology and manage construction and operational site impacts; site disturbance: physical alteration of soil, vegetation, or existing site conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Rapid containment prevents discharge to the drain; the plan sets reporting.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc SS vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"prerequisite: điều kiện tiên quyết bắt buộc, không mang điểm; sustainable sites: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; site disturbance: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Ngăn chặn nhanh tránh xả vào cống; kế hoạch quy định báo cáo. Vì vậy phương án B đúng.","options_vi":["Chờ cho đông cứng","Ngăn chặn, dọn sạch, lập hồ sơ và báo cáo theo kế hoạch phòng ngừa ô nhiễm của công trường","Xối nước bằng vòi","Dọn phần nhìn thấy rồi tiếp tục"],"evidence_en":"Rapid containment prevents discharge to the drain; the plan sets reporting.","evidence_vi":"Ngăn chặn nhanh tránh xả vào cống; kế hoạch quy định báo cáo.","mechanism_vi":"Ngăn chặn nhanh tránh xả vào cống; kế hoạch quy định báo cáo. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Bê tông đông cứng gần cống là nguy cơ.","Đúng. Ngăn chặn nhanh tránh xả vào cống; kế hoạch quy định báo cáo.","Sai. Xối nước làm lan rộng.","Sai. Dọn một phần còn rủi ro."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 542; Sustainable Sites","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Hardened concrete near a drain is a hazard.","Correct. Rapid containment prevents discharge to the drain; the plan sets reporting.","Incorrect. Hosing spreads it.","Incorrect. Partial cleanup leaves risk."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Rapid containment prevents discharge to the drain; the plan sets reporting.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q042","core_concept_vi":"Ngăn chặn nhanh tránh xả vào cống; kế hoạch quy định báo cáo.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-543","source_index":543,"q":"At Cascade Heights Senior Center, exhaust from the fitness room and woodworking room is routed to the central AHU for heat recovery. Why is this wrong?","options":["MERV 13 makes it fine","Heat recovery from fitness rooms is standard","Wood dust is natural","It recirculates contaminants; use dedicated exhaust with air-to-air heat recovery and no cross-leakage"],"answer":3,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Contaminated exhaust must not mix into supply air.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Khí thải nhiễm bẩn không được trộn vào gió cấp. Vì vậy phương án D đúng.","options_vi":["MERV 13 làm cho ổn","Thu hồi nhiệt từ phòng tập là thông lệ","Bụi gỗ là tự nhiên","Nó tái tuần hoàn chất ô nhiễm; dùng hút riêng với thu hồi nhiệt gió-gió không rò chéo"],"evidence_en":"Contaminated exhaust must not mix into supply air.","evidence_vi":"Khí thải nhiễm bẩn không được trộn vào gió cấp.","mechanism_vi":"Khí thải nhiễm bẩn không được trộn vào gió cấp. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Bộ lọc không loại mùi và khí.","Sai. Không áp dụng cho khí thải nhiễm bẩn.","Sai. Bụi vẫn là chất ô nhiễm.","Đúng. Khí thải nhiễm bẩn không được trộn vào gió cấp."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 543; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Filters do not remove odors and gases.","Incorrect. Not for contaminated exhaust.","Incorrect. Dust remains a pollutant.","Correct. Contaminated exhaust must not mix into supply air."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Contaminated exhaust must not mix into supply air.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q043","core_concept_vi":"Khí thải nhiễm bẩn không được trộn vào gió cấp.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-544","source_index":544,"q":"Sunrise Office is inside a LEED-ND neighborhood. The consultant claims this automatically earns every location credit. Who is right?","options":["The consultant: all are earned automatically","The architect: neighborhood certification can support some location credits but each must be demonstrated","Neither can pursue both","The building is Platinum"],"answer":1,"category":"Innovation & Regional Priority","source_domain":"Innovation & Regional Priority","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the PR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; certification: third-party confirmation that a project satisfies applicable LEED requirements; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Credits are earned by documented performance of the project.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm PR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Tín chỉ được cấp theo hiệu năng có hồ sơ của dự án. Vì vậy phương án B đúng.","options_vi":["Chuyên gia tư vấn: tất cả tự động được","Kiến trúc sư: chứng nhận khu phố có thể hỗ trợ một số tín chỉ vị trí nhưng mỗi tín chỉ phải chứng minh","Không thể theo đuổi cả hai","Công trình là Platinum"],"evidence_en":"Credits are earned by documented performance of the project.","evidence_vi":"Tín chỉ được cấp theo hiệu năng có hồ sơ của dự án.","mechanism_vi":"Tín chỉ được cấp theo hiệu năng có hồ sơ của dự án. Vì vậy phương án B đúng.","wrong_reasons_vi":["Sai. Không tự động.","Đúng. Tín chỉ được cấp theo hiệu năng có hồ sơ của dự án.","Sai. Có thể cùng tồn tại.","Sai. Không bậc nào tự động."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 544; Innovation & Regional Priority","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. Not automatic.","Correct. Credits are earned by documented performance of the project.","Incorrect. They can coexist.","Incorrect. No level is automatic."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Ưu tiên khu vực - Innovation & Regional Priority","english_explanation_version":"v7.5.19-english-only","core_concept":"Credits are earned by documented performance of the project.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q044","core_concept_vi":"Tín chỉ được cấp theo hiệu năng có hồ sơ của dự án.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-545","source_index":545,"q":"Trillium Pediatric Hospital has 70% window-to-wall ratio and an infection control concern about fabric blinds. Which solution best serves daylight, privacy and cleanability?","options":["Fabric blinds","Reduce windows to 30%","Exterior louvers only","Dynamic glazing or cleanable integrated shading, with no fabric to harbor contaminants"],"answer":3,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"daylight: natural light admitted into an interior space; maximum: the highest permitted value or level; best: a word asking for the strongest or most effective option","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Integrated or glazing-based control avoids hard-to-clean fabric while keeping daylight.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EQ vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; daylight: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; maximum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; best: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Kiểm soát tích hợp hoặc bằng kính tránh vải khó lau mà vẫn giữ ánh sáng ngày. Vì vậy phương án D đúng.","options_vi":["Rèm vải","Giảm cửa sổ còn 30%","Chỉ lam chắn nắng ngoài","Kính điều chỉnh hoặc che nắng tích hợp dễ lau, không có vải giữ chất bẩn"],"evidence_en":"Integrated or glazing-based control avoids hard-to-clean fabric while keeping daylight.","evidence_vi":"Kiểm soát tích hợp hoặc bằng kính tránh vải khó lau mà vẫn giữ ánh sáng ngày.","mechanism_vi":"Kiểm soát tích hợp hoặc bằng kính tránh vải khó lau mà vẫn giữ ánh sáng ngày. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Bỏ qua mối quan ngại.","Sai. Mất ánh sáng ngày.","Sai. Không đảm bảo riêng tư.","Đúng. Kiểm soát tích hợp hoặc bằng kính tránh vải khó lau mà vẫn giữ ánh sáng ngày."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 545; Indoor Environmental Quality","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Ignores the concern.","Incorrect. Loses daylight.","Incorrect. Does not give privacy.","Correct. Integrated or glazing-based control avoids hard-to-clean fabric while keeping daylight."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Integrated or glazing-based control avoids hard-to-clean fabric while keeping daylight.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q045","core_concept_vi":"Kiểm soát tích hợp hoặc bằng kính tránh vải khó lau mà vẫn giữ ánh sáng ngày.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-546","source_index":546,"q":"Northgate Transit Center's team wants to exclude the enclosed, conditioned bus terminal from the energy model as 'transportation infrastructure'. Is that valid?","options":["Yes, all infrastructure is excluded","Yes, because it serves buses","Treat it as process energy","Not automatically: enclosed conditioned space is generally within the boundary; confirm with the reference guide or a CIR"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this exception question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"energy model: a simulation used to estimate and compare building energy performance; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy; energy efficiency: delivery of the required service with less energy use","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Boundaries follow the conditioned space, so exclusion needs support.","purpose_vi":"Kiểm tra khả năng nhận diện từ khóa phủ định và loại phương án đi ngược nguyên tắc kỹ thuật của nhóm EA.","vocabulary_vi":"CIR: yêu cầu giải thích chính thức cách áp dụng credit cho tình huống dự án; energy model: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy and atmosphere: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy efficiency: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Ranh giới theo không gian có điều hòa nên việc loại trừ cần căn cứ. Vì vậy phương án D đúng.","options_vi":["Có, mọi hạ tầng đều bị loại","Có, vì phục vụ xe buýt","Coi là năng lượng quy trình","Không tự động: không gian kín có điều hòa thường nằm trong ranh giới; xác nhận với tài liệu hướng dẫn hoặc CIR"],"evidence_en":"Boundaries follow the conditioned space, so exclusion needs support.","evidence_vi":"Ranh giới theo không gian có điều hòa nên việc loại trừ cần căn cứ.","mechanism_vi":"Ranh giới theo không gian có điều hòa nên việc loại trừ cần căn cứ. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Không có loại trừ chung.","Sai. Người dùng vẫn được điều hòa.","Sai. Không phải tải quy trình.","Đúng. Ranh giới theo không gian có điều hòa nên việc loại trừ cần căn cứ."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 546; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. No blanket exclusion.","Incorrect. Users are still conditioned.","Incorrect. Not process load.","Correct. Boundaries follow the conditioned space, so exclusion needs support."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Boundaries follow the conditioned space, so exclusion needs support.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q046","core_concept_vi":"Ranh giới theo không gian có điều hòa nên việc loại trừ cần căn cứ.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-547","source_index":547,"q":"Meridian Science Center sits on a former surface parking lot, will bury parking and restore meadow above. The team claims a sensitive land protection credit. Is that valid?","options":["No: that credit rewards avoiding sensitive land, and restoration is evaluated under habitat credits instead","Yes, since restoration improves ecology","Yes if the original designation is removed","No, as the garage makes the site ineligible"],"answer":0,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; sustainable sites: strategies that protect site ecology and manage construction and operational site impacts; site disturbance: physical alteration of soil, vegetation, or existing site conditions","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Protection is about not developing sensitive land; restoring a developed site is a different outcome.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; sustainable sites: khu đất bền vững; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Bảo vệ là không phát triển đất nhạy cảm; phục hồi khu đã xây dựng là một kết quả khác. Vì vậy phương án A đúng.","options_vi":["Không: tín chỉ đó thưởng việc tránh đất nhạy cảm, còn phục hồi được đánh giá ở tín chỉ sinh cảnh","Có vì phục hồi cải thiện sinh thái","Có nếu bỏ chỉ định ban đầu","Không vì hầm xe khiến khu đất không đủ điều kiện"],"evidence_en":"Protection is about not developing sensitive land; restoring a developed site is a different outcome.","evidence_vi":"Bảo vệ là không phát triển đất nhạy cảm; phục hồi khu đã xây dựng là một kết quả khác.","mechanism_vi":"Bảo vệ là không phát triển đất nhạy cảm; phục hồi khu đã xây dựng là một kết quả khác. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Bảo vệ là không phát triển đất nhạy cảm; phục hồi khu đã xây dựng là một kết quả khác.","Sai. Tín chỉ không nói về phục hồi.","Sai. Chỉ định không quan trọng.","Sai. Hầm xe không chặn mọi tín chỉ."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 547; Sustainable Sites","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. Protection is about not developing sensitive land; restoring a developed site is a different outcome.","Incorrect. The credit is not about restoration.","Incorrect. Designation does not matter.","Incorrect. A garage does not bar all credits."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Protection is about not developing sensitive land; restoring a developed site is a different outcome.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q047","core_concept_vi":"Bảo vệ là không phát triển đất nhạy cảm; phục hồi khu đã xây dựng là một kết quả khác.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-548","source_index":548,"q":"Riverside Office Complex is 0.8 miles from a rail station and proposes a shuttle every 10 minutes at peak. How is it treated?","options":["Shuttles never count","Only if run by the transit authority","The distance disqualifies it","It can count if it meets the credit's frequency and distance conditions"],"answer":3,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the LT concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; minimum: the lowest acceptable value or level; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Qualifying service can extend access when it meets the stated conditions.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu LT, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; minimum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Dịch vụ đủ điều kiện có thể mở rộng khả năng tiếp cận khi đáp ứng điều kiện nêu. Vì vậy phương án D đúng.","options_vi":["Shuttle không bao giờ được tính","Chỉ khi do cơ quan giao thông vận hành","Khoảng cách loại bỏ hoàn toàn","Có thể được tính nếu đáp ứng điều kiện tần suất và khoảng cách của tín chỉ"],"evidence_en":"Qualifying service can extend access when it meets the stated conditions.","evidence_vi":"Dịch vụ đủ điều kiện có thể mở rộng khả năng tiếp cận khi đáp ứng điều kiện nêu.","mechanism_vi":"Dịch vụ đủ điều kiện có thể mở rộng khả năng tiếp cận khi đáp ứng điều kiện nêu. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Một số shuttle được tính.","Sai. Đơn vị vận hành không phải ngưỡng.","Sai. Khoảng cách có thể được bắc cầu.","Đúng. Dịch vụ đủ điều kiện có thể mở rộng khả năng tiếp cận khi đáp ứng điều kiện nêu."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 548; Location & Transportation","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. Some shuttles count.","Incorrect. Operator is not the gate.","Incorrect. Distance can be bridged.","Correct. Qualifying service can extend access when it meets the stated conditions."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"Qualifying service can extend access when it meets the stated conditions.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q048","core_concept_vi":"Dịch vụ đủ điều kiện có thể mở rộng khả năng tiếp cận khi đáp ứng điều kiện nêu.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-549","source_index":549,"q":"At Aurora Community Library, HVAC condensate (45,000 gal/yr) and roof runoff (120,000 gal/yr) feed a cistern for toilets using 95,000 gal/yr. What does this show?","options":["A plumbing detail unrelated to integration","Only cost-cutting","Only rainwater management","Integrative water-energy thinking: two waste streams meet a non-potable demand"],"answer":3,"category":"Integrative Process","source_domain":"Integrative Process","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the IP concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"integrative process: an early collaborative process used to identify system interactions and improve decisions; rainwater management: strategies that retain, infiltrate, evapotranspire, or reuse rainfall on site; water efficiency: the reduction and responsible management of potable and process water use","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Combining sources (165,000 gal) exceeds the 95,000 gal demand.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm IP đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"water efficiency: hiệu quả sử dụng nước; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Gộp các nguồn (165.000 gal) vượt nhu cầu 95.000 gal. Vì vậy phương án D đúng.","options_vi":["Chi tiết cấp thoát nước không liên quan tích hợp","Chỉ cắt giảm chi phí","Chỉ quản lý nước mưa","Tư duy tích hợp nước – năng lượng: hai dòng thải đáp ứng nhu cầu không uống được"],"evidence_en":"Combining sources (165,000 gal) exceeds the 95,000 gal demand.","evidence_vi":"Gộp các nguồn (165.000 gal) vượt nhu cầu 95.000 gal.","mechanism_vi":"Gộp các nguồn (165.000 gal) vượt nhu cầu 95.000 gal. Vì vậy phương án D đúng.","wrong_reasons_vi":["Sai. Đó là liên hệ giữa các hệ.","Sai. Không chỉ là chi phí.","Sai. Có liên quan thiết bị năng lượng.","Đúng. Gộp các nguồn (165.000 gal) vượt nhu cầu 95.000 gal."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 549; Integrative Process","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. It is cross-system.","Incorrect. It is more than cost.","Incorrect. It involves energy equipment.","Correct. Combining sources (165,000 gal) exceeds the 95,000 gal demand."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Quy trình tích hợp - quy trình tích hợp","english_explanation_version":"v7.5.19-english-only","core_concept":"Combining sources (165,000 gal) exceeds the 95,000 gal demand.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q049","core_concept_vi":"Gộp các nguồn (165.000 gal) vượt nhu cầu 95.000 gal.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-550","source_index":550,"q":"Brightside Passive House uses 65% less energy than baseline by Passive House calculations. How should it be handled for LEED energy credit?","options":["Run the required energy model using the rating system's methodology","Submit the Passive House calculation as-is","The methods are identical","Passive House is exempt"],"answer":0,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"APPLICATION","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; energy model: a simulation used to estimate and compare building energy performance; energy performance: the measured or modeled energy use of a building or system; credit: an optional LEED requirement that can earn points; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Identify the decisive condition in the stem (scope, metric, sequence, or applicability under LEED v5) and test each option against it; near-correct options usually fail on one of these.","logic":"Credit scoring needs the specified baseline and method.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"baseline: đường cơ sở dùng để so sánh hiệu suất của dự án; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Xác định điều kiện quyết định trong đề (phạm vi, chỉ số, trình tự hoặc điều kiện áp dụng theo LEED v5) rồi kiểm tra từng phương án; phương án gần đúng thường sai đúng một điểm trong số đó.","logic_vi":"Chấm điểm tín chỉ cần mức cơ sở và phương pháp quy định. Vì vậy phương án A đúng.","options_vi":["Chạy mô hình năng lượng theo phương pháp mà hệ thống chứng nhận yêu cầu","Nộp nguyên tính toán Passive House","Hai phương pháp giống hệt","Passive House được miễn"],"evidence_en":"Credit scoring needs the specified baseline and method.","evidence_vi":"Chấm điểm tín chỉ cần mức cơ sở và phương pháp quy định.","mechanism_vi":"Chấm điểm tín chỉ cần mức cơ sở và phương pháp quy định. Vì vậy phương án A đúng.","wrong_reasons_vi":["Đúng. Chấm điểm tín chỉ cần mức cơ sở và phương pháp quy định.","Sai. Phương pháp khác nhau.","Sai. Không giống hệt.","Sai. Không có miễn trừ."],"source":"Rewritten for difficulty and LEED v5 alignment (original source: Exam sample (Udemy).docx)","source_ref":"Source question 550; Energy & Atmosphere","source_integrity":"Question stem, options, answer and explanation rewritten; original topic and category retained.","quote_status":"ORIGINAL_WRITING_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. Credit scoring needs the specified baseline and method.","Incorrect. Methods differ.","Incorrect. Not identical.","Incorrect. No exemption."],"explanation_format":"VI_EN_PER_OPTION_V11","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Credit scoring needs the specified baseline and method.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q050","core_concept_vi":"Chấm điểm tín chỉ cần mức cơ sở và phương pháp quy định.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"REWRITTEN_REVIEWED","deep_editorial_status":"REWRITTEN_V11_HARD_LEED_V5","difficulty":"HARD","source_ref_deep":"USGBC LEED v5 BD+C New Construction scorecard and reference guide (2025-2026); verify credit-level details against the current reference guide.","question_revision":"REWRITTEN_HARD_LEED_V5","editorial_version":"v11-hard-v5"},{"id":"UD-551","source_index":551,"q":"The Halcyon Medical Center is 3 weeks from construction review submission and has only 38 documented points — 2 short of the 40-point Certified minimum — with no sustainability budget remaining. What is the best strategic approach?","options":["Withdraw the certification application and pursue LEED O+M in 5 years","Look for unclaimed RP credits and partially-documented credits that need minimal effort","Submit with 38 points and negotiate with the reviewer for special healthcare consideration","Add a small solar PV system in the last 3 weeks to earn energy credit points"],"answer":1,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"BEST_FIRST","purpose":"Assess whether the learner can apply the Overview concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; certification: third-party confirmation that a project satisfies applicable LEED requirements; minimum: the lowest acceptable value or level; best: a word asking for the strongest or most effective option","keywords":"Identify the exact minimum, maximum, or numerical threshold requested; decisive value or condition: Look for unclaimed RP credits and partially-documented credits that need minimal effort.","logic":"When close to a threshold with limited budget, strategic analysis matters: RP credits require no additional work if the base credit is already earned; partially-documented credits may only need a final form or calculation. Targeted effort can close a 2-point gap.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu Overview, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; minimum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; best: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Look cho unclaimed RP tín chỉ và partially-documented tín chỉ đó need minimal effort” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Cấp chứng nhận LEED được xác định bằng tổng điểm sau khi tất cả điều kiện tiên quyết được đáp ứng. Điểm quyết định Certified, Silver, Gold hoặc Platinum; prerequisite không tạo điểm. Trong bối cảnh câu hỏi, “Look cho unclaimed RP tín chỉ và partially-documented tín chỉ đó need minimal effort” áp dụng đúng nguyên tắc này; vì vậy phương án B đúng.","options_vi":["Withdraw chứng nhận application và pursue LEED O+M trong 5 years","Look cho unclaimed RP tín chỉ và partially-documented tín chỉ đó need minimal effort","Nộp với 38 điểm và negotiate với reviewer cho special healthcare consideration","Add small mặt trời PV hệ thống trong last 3 weeks để nhận năng lượng tín chỉ điểm"],"evidence_en":"When close to a threshold with limited budget, strategic analysis matters: RP credits require no additional work if the base credit is already earned; partially-documented credits may only need a final form or calculation. Targeted effort can close a 2-point gap.","evidence_vi":"Cấp chứng nhận LEED được xác định bằng tổng điểm sau khi tất cả điều kiện tiên quyết được đáp ứng. Điểm quyết định Certified, Silver, Gold hoặc Platinum; prerequisite không tạo điểm.","mechanism_vi":"Cấp chứng nhận LEED được xác định bằng tổng điểm sau khi tất cả điều kiện tiên quyết được đáp ứng. Điểm quyết định Certified, Silver, Gold hoặc Platinum; prerequisite không tạo điểm.","wrong_reasons_vi":["Sai. “Withdraw chứng nhận application và pursue LEED O+M trong 5 years” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Cấp chứng nhận LEED được xác định bằng tổng điểm sau khi tất cả điều kiện tiên quyết được đáp ứng. Điểm quyết định Certified, Silver, Gold hoặc Platinum; prerequisite không tạo điểm.","Sai. “Nộp với 38 điểm và negotiate với reviewer cho special healthcare consideration” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Add small mặt trời PV hệ thống trong last 3 weeks để nhận năng lượng tín chỉ điểm” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 551; LEED Overview & Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Withdraw the certification application and pursue LEED O+M in 5 years” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Look for unclaimed RP credits and partially-documented credits that need minimal effort.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Submit with 38 points and negotiate with the reviewer for special healthcare consideration” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Look for unclaimed RP credits and partially-documented credits that need minimal effort.”","Incorrect. “Add a small solar PV system in the last 3 weeks to earn energy credit points” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Look for unclaimed RP credits and partially-documented credits that need minimal effort.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"When close to a threshold with limited budget, strategic analysis matters: RP credits require no additional work if the base credit is already earned; partially-documented credits may only need a final form or calculation. Targeted effort can close a 2-point gap.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q051","core_concept_vi":"Cấp chứng nhận LEED được xác định bằng tổng điểm sau khi tất cả điều kiện tiên quyết được đáp ứng. Điểm quyết định Certified, Silver, Gold hoặc Platinum; prerequisite không tạo điểm.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-552","source_index":552,"q":"Orion Pharmaceutical Laboratory has very high process energy loads — HVAC for lab exhaust systems uses 4× more energy than a comparable-size office. Much of this is mandated by OSHA ventilation standards and cannot be reduced. How does LEED address this in its energy performance credit calculations?","options":["Process energy is as the default approach excluded from LEED energy calculations","LEED as the default approach uses the same baseline for all building types regardless of code requirements","Use a lab-appropriate ASHRAE baseline; reward improvements above code-mandated minimums","Laboratory buildings are exempt from all LEED energy credits"],"answer":2,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; energy performance: the measured or modeled energy use of a building or system; credit: an optional LEED requirement that can earn points; minimum: the lowest acceptable value or level","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Use a lab-appropriate ASHRAE baseline; reward improvements above code-mandated minimums.","logic":"Laboratories face a genuine challenge: much of their high energy use is mandated by safety codes, not design choices. LEED addresses this by using lab-appropriate ASHRAE 90.1 baselines that already incorporate code-mandated ventilation minimums — recognizing baseline loads while still rewarding efficiencies above those minimums (heat recovery, VAV fume hoods, DCV).","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"baseline: đường cơ sở dùng để so sánh hiệu suất của dự án; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","options_vi":["Quy trình năng lượng là Luôn luôn excluded từ LEED năng lượng calculations","LEED Luôn luôn uses same đường cơ sở cho tất cả công trình types regardless của code yêu cầu","Sử dụng một lab-appropriate ASHRAE đường cơ sở; reward improvements above code-mandated minimums","Laboratory công trình là exempt từ tất cả LEED năng lượng tín chỉ"],"evidence_en":"Laboratories face a genuine challenge: much of their high energy use is mandated by safety codes, not design choices. LEED addresses this by using lab-appropriate ASHRAE 90.1 baselines that already incorporate code-mandated ventilation minimums — recognizing baseline loads while still rewarding efficiencies above those minimums (heat recovery, VAV fume hoods, DCV).","evidence_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","mechanism_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","wrong_reasons_vi":["Sai. “Quy trình năng lượng là Luôn luôn excluded từ LEED năng lượng calculations” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “LEED Luôn luôn uses same đường cơ sở cho tất cả công trình types regardless của code yêu cầu” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","Sai. “Laboratory công trình là exempt từ tất cả LEED năng lượng tín chỉ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 552; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Process energy is always excluded from LEED energy calculations” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use a lab-appropriate ASHRAE baseline; reward improvements above code-mandated minimums.”","Incorrect. “LEED always uses the same baseline for all building types regardless of code requirements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use a lab-appropriate ASHRAE baseline; reward improvements above code-mandated minimums.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Laboratory buildings are exempt from all LEED energy credits” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use a lab-appropriate ASHRAE baseline; reward improvements above code-mandated minimums.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Laboratories face a genuine challenge: much of their high energy use is mandated by safety codes, not design choices. LEED addresses this by using lab-appropriate ASHRAE 90.1 baselines that already incorporate code-mandated ventilation minimums — recognizing baseline loads while still rewarding efficiencies above those minimums (heat recovery, VAV fume hoods, DCV).","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q052","core_concept_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-553","source_index":553,"q":"Fairview Community Hospital wants to use extensive decorative exterior lighting for their patient-facing identity. The sustainability manager raises LEED Light Pollution Reduction concerns. The lighting designer argues decorative lighting is necessary. How should the team resolve this tension?","options":["Specify decorative luminaires with proper BUG ratings — the credit doesn't ban decorative lighting","All exterior lighting must be turned off between dusk and dawn to earn the credit","The decorative lighting must be substantially eliminated to earn the LEED credit","Healthcare facilities are exempt from Light Pollution Reduction requirements"],"answer":0,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; sustainable sites: strategies that protect site ecology and manage construction and operational site impacts; site disturbance: physical alteration of soil, vegetation, or existing site conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Specify decorative luminaires with proper BUG ratings — the credit doesn't ban decorative lighting.","logic":"LEED Light Pollution Reduction is about how light is directed (BUG ratings — backlight, uplight, glare), not eliminating all exterior lighting. Decorative lighting that illuminates the building facade with appropriate BUG-rated luminaires in warm color temperatures, pointed downward, and dimmed after 11 PM can earn the credit while meeting the hospital's image objectives.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; sustainable sites: khu đất bền vững; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Tập trung vào “exterior lighting”. Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm ô nhiễm ánh sáng kiểm soát hướng, cường độ và thời gian chiếu sáng ngoài nhà để hạn chế ánh sáng hướng lên, skyglow và ánh sáng xâm nhập. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Specify decorative luminaires với proper BUG ratings - tín chỉ doesn't ban decorative chiếu sáng","Tất cả exterior chiếu sáng phải là turned off trong khoảng dusk và dawn để nhận tín chỉ","Decorative chiếu sáng phải là completely eliminated để nhận LEED tín chỉ","Healthcare facilities là exempt từ giảm ô nhiễm ánh sáng các yêu cầu"],"evidence_en":"LEED Light Pollution Reduction is about how light is directed (BUG ratings — backlight, uplight, glare), not eliminating all exterior lighting. Decorative lighting that illuminates the building facade with appropriate BUG-rated luminaires in warm color temperatures, pointed downward, and dimmed after 11 PM can earn the credit while meeting the hospital's image objectives.","evidence_vi":"Giảm ô nhiễm ánh sáng kiểm soát hướng, cường độ và thời gian chiếu sáng ngoài nhà để hạn chế ánh sáng hướng lên, skyglow và ánh sáng xâm nhập. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"Giảm ô nhiễm ánh sáng kiểm soát hướng, cường độ và thời gian chiếu sáng ngoài nhà để hạn chế ánh sáng hướng lên, skyglow và ánh sáng xâm nhập. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. Giảm ô nhiễm ánh sáng kiểm soát hướng, cường độ và thời gian chiếu sáng ngoài nhà để hạn chế ánh sáng hướng lên, skyglow và ánh sáng xâm nhập. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “Tất cả exterior chiếu sáng phải là turned off trong khoảng dusk và dawn để nhận tín chỉ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Decorative chiếu sáng phải là completely eliminated để nhận LEED tín chỉ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. Giảm ô nhiễm ánh sáng kiểm soát hướng, cường độ và thời gian chiếu sáng ngoài nhà để hạn chế ánh sáng hướng lên, skyglow và ánh sáng xâm nhập. Chức năng này không trùng với đối tượng và phạm vi mà câu hỏi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 553; Sustainable Sites","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “All exterior lighting must be turned off between dusk and dawn to earn the credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Specify decorative luminaires with proper BUG ratings — the credit doesn't ban decorative lighting.”","Incorrect. “The decorative lighting must be completely eliminated to earn the LEED credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Specify decorative luminaires with proper BUG ratings — the credit doesn't ban decorative lighting.”","Incorrect. “Healthcare facilities are exempt from Light Pollution Reduction requirements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Specify decorative luminaires with proper BUG ratings — the credit doesn't ban decorative lighting.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED Light Pollution Reduction is about how light is directed (BUG ratings — backlight, uplight, glare), not eliminating all exterior lighting. Decorative lighting that illuminates the building facade with appropriate BUG-rated luminaires in warm color temperatures, pointed downward, and dimmed after 11 PM can earn the credit while meeting the hospital's image objectives.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q053","core_concept_vi":"Giảm ô nhiễm ánh sáng kiểm soát hướng, cường độ và thời gian chiếu sáng ngoài nhà để hạn chế ánh sáng hướng lên, skyglow và ánh sáng xâm nhập. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-554","source_index":554,"q":"Pinnacle Tower's whole-building LCA shows GWP contributors: Concrete structure (75,000 tonnes CO₂e), Steel reinforcement (12,000 tonnes), Aluminum curtain wall (8,500 tonnes), MEP systems (4,200 tonnes), Interior finishes (2,100 tonnes). Total: 101,800 tonnes. Reference building: 115,000 tonnes. What is the GWP reduction percentage, and which material offers the greatest opportunity for further improvement?","options":["The total reduction is achieved — no further improvement is possible","The aluminum curtain wall should be the primary target for GWP reduction","A 11.5% reduction is too small to earn any LEED whole-building LCA credit","11.5% reduction — concrete (74% of GWP) is the biggest opportunity for further cuts"],"answer":3,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the MR concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; materials and resources: strategies addressing life-cycle impacts, product selection, sourcing, and waste; product documentation: verified records supporting environmental and material claims","keywords":"Identify the exact minimum, maximum, or numerical threshold requested; decisive value or condition: 11.5% reduction — concrete (74% of GWP) is the biggest opportunity for further cuts.","logic":"GWP reduction: (115,000 − 101,800) ÷ 115,000 = 11.5% — likely meeting the typical 10% LCA credit threshold. Concrete at 74% of total GWP is clearly the primary target for further improvement: a 40% SCM (fly ash/slag) replacement could reduce concrete GWP by 35–40%, potentially saving 26,000–30,000 tonnes CO₂e and pushing total reduction to 35%+.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc MR vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; materials and resources: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; product documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “11.5% mức giảm - concrete (74% của GWP) là biggest opportunity cho further cuts” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Quy trình tích hợp phải bắt đầu đủ sớm để phân tích tương tác giữa khu đất, nước, năng lượng, vật liệu và người sử dụng trước khi các quyết định lớn trở nên khó hoặc tốn kém để thay đổi. Trong bối cảnh câu hỏi, “11.5% mức giảm - concrete (74% của GWP) là biggest opportunity cho further cuts” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Tổng mức giảm là achieved - Không further improvement là possible","Aluminum curtain wall nên là chính target cho GWP mức giảm","11.5% mức giảm là too small để nhận bất kỳ LEED whole-công trình LCA tín chỉ","11.5% mức giảm - concrete (74% của GWP) là biggest opportunity cho further cuts"],"evidence_en":"GWP reduction: (115,000 − 101,800) ÷ 115,000 = 11.5% — likely meeting the typical 10% LCA credit threshold. Concrete at 74% of total GWP is clearly the primary target for further improvement: a 40% SCM (fly ash/slag) replacement could reduce concrete GWP by 35–40%, potentially saving 26,000–30,000 tonnes CO₂e and pushing total reduction to 35%+.","evidence_vi":"Quy trình tích hợp phải bắt đầu đủ sớm để phân tích tương tác giữa khu đất, nước, năng lượng, vật liệu và người sử dụng trước khi các quyết định lớn trở nên khó hoặc tốn kém để thay đổi.","mechanism_vi":"Quy trình tích hợp phải bắt đầu đủ sớm để phân tích tương tác giữa khu đất, nước, năng lượng, vật liệu và người sử dụng trước khi các quyết định lớn trở nên khó hoặc tốn kém để thay đổi.","wrong_reasons_vi":["Sai. “Tổng mức giảm là achieved - Không further improvement là possible” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Aluminum curtain wall nên là chính target cho GWP mức giảm” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “11.5% mức giảm là too small để nhận bất kỳ LEED whole-công trình LCA tín chỉ” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Quy trình tích hợp phải bắt đầu đủ sớm để phân tích tương tác giữa khu đất, nước, năng lượng, vật liệu và người sử dụng trước khi các quyết định lớn trở nên khó hoặc tốn kém để thay đổi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 554; Materials & Resources","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “The total reduction is achieved — no further improvement is possible” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “11.5% reduction — concrete (74% of GWP) is the biggest opportunity for further cuts.”","Incorrect. “The aluminum curtain wall should be the primary target for GWP reduction” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “11.5% reduction — concrete (74% of GWP) is the biggest opportunity for further cuts.”","Incorrect. “A 11.5% reduction is too small to earn any LEED whole-building LCA credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “11.5% reduction — concrete (74% of GWP) is the biggest opportunity for further cuts.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"GWP reduction: (115,000 − 101,800) ÷ 115,000 = 11.5% — likely meeting the typical 10% LCA credit threshold. Concrete at 74% of total GWP is clearly the primary target for further improvement: a 40% SCM (fly ash/slag) replacement could reduce concrete GWP by 35–40%, potentially saving 26,000–30,000 tonnes CO₂e and pushing total reduction to 35%+.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q054","core_concept_vi":"Quy trình tích hợp phải bắt đầu đủ sớm để phân tích tương tác giữa khu đất, nước, năng lượng, vật liệu và người sử dụng trước khi các quyết định lớn trở nên khó hoặc tốn kém để thay đổi.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-555","source_index":555,"q":"Greenwood Elementary School is specifying interior materials: painted drywall walls, VCT flooring with adhesive, acoustical ceiling tiles, and solid wood casework. What is the most important product category to focus on for LEED Low-Emitting Materials compliance?","options":["primarily ceiling tiles matter since they are above occupant breathing height","Flooring system (VCT + adhesive) — highest VOC source close to children","All product categories are equally important and should be treated identically","Focus primarily on the paint since it is the most visible applied product"],"answer":1,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the MR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"low-emitting materials: products evaluated for low emissions of volatile organic compounds; materials and resources: strategies addressing life-cycle impacts, product selection, sourcing, and waste; product documentation: verified records supporting environmental and material claims","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Flooring system (VCT + adhesive) — highest VOC source close to children.","logic":"Priority should be based on emission potential × exposure. Flooring adhesives are historically the highest VOC emitters in commercial interiors and are applied in confined spaces. Flooring covers large areas close to occupants — especially critical in schools where children are closest to the floor. Each component (adhesive, flooring, sealers) needs separate documentation.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm MR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"materials and resources: vật liệu và tài nguyên; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Chỉ ceiling tiles matter vì they là above người sử dụng breathing height","Flooring hệ thống (VCT + adhesive) - highest VOC nguồn close để children","Tất cả sản phẩm categories là equally important và nên là treated identically","Focus chỉ trên paint vì it là nhiều nhất có thể nhìn thấy applied sản phẩm"],"evidence_en":"Priority should be based on emission potential × exposure. Flooring adhesives are historically the highest VOC emitters in commercial interiors and are applied in confined spaces. Flooring covers large areas close to occupants — especially critical in schools where children are closest to the floor. Each component (adhesive, flooring, sealers) needs separate documentation.","evidence_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Chỉ ceiling tiles matter vì they là above người sử dụng breathing height” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Tất cả sản phẩm categories là equally important và nên là treated identically” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Focus chỉ trên paint vì it là nhiều nhất có thể nhìn thấy applied sản phẩm” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 555; Materials & Resources","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Only ceiling tiles matter since they are above occupant breathing height” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Flooring system (VCT + adhesive) — highest VOC source close to children.”","Correct. This option directly satisfies the governing condition.","Incorrect. “All product categories are equally important and should be treated identically” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Flooring system (VCT + adhesive) — highest VOC source close to children.”","Incorrect. “Focus only on the paint since it is the most visible applied product” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Flooring system (VCT + adhesive) — highest VOC source close to children.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Priority should be based on emission potential × exposure. Flooring adhesives are historically the highest VOC emitters in commercial interiors and are applied in confined spaces. Flooring covers large areas close to occupants — especially critical in schools where children are closest to the floor. Each component (adhesive, flooring, sealers) needs separate documentation.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q055","core_concept_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-556","source_index":556,"q":"Highpoint mixed-use development is in a water-stressed American Southwest region. The local utility offers a $3/1,000-gallon rebate for demonstrated water conservation. The team is evaluating: (A) native landscaping with no irrigation ($85,000 incremental cost), (B) WaterSense fixture upgrades ($45,000), (C) cooling tower optimization system ($35,000). Which investment likely provides the best combined return?","options":["Option B because WaterSense fixtures are the most recognizable sustainable feature","Option C because cooling towers use the most water in all climates","All three options provide identical water savings and LEED credit value","Option A — landscape eliminates 60–70% of water use in arid climates"],"answer":3,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"BEST_FIRST","purpose":"Assess whether the learner can apply the WE concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"cooling tower: heat-rejection equipment that commonly uses evaporation; credit: an optional LEED requirement that can earn points; best: a word asking for the strongest or most effective option","keywords":"Distinguish the technical requirement from the document or evidence that verifies it; decisive evidence: Option A — landscape eliminates 60–70% of water use in arid climates.","logic":"Climate context is critical for water strategy prioritization. In the American Southwest, landscape irrigation typically represents 50–70% of total water use. Eliminating irrigation through native planting provides dramatically more total water savings than fixture upgrades, making it the highest-value strategy despite higher upfront cost.","purpose_vi":"Kiểm tra khả năng xác định đúng hồ sơ hoặc dữ liệu dùng để chứng minh yêu cầu WE, không nhầm với tài liệu có chức năng khác.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Phương án B vì WaterSense fixtures là nhất recognizable sustainable feature","Phương án C vì cooling towers sử dụng nhất nước trong tất cả climates","Tất cả three options provide identical nước savings và LEED tín chỉ value","Phương án - landscape eliminates 60-70% của mức sử dụng nước trong arid climates"],"evidence_en":"Climate context is critical for water strategy prioritization. In the American Southwest, landscape irrigation typically represents 50–70% of total water use. Eliminating irrigation through native planting provides dramatically more total water savings than fixture upgrades, making it the highest-value strategy despite higher upfront cost.","evidence_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Chức năng này không trùng với đối tượng và phạm vi mà câu hỏi yêu cầu.","Sai. Hiệu quả nước của tháp giải nhiệt phụ thuộc vào tăng an toàn chu kỳ cô đặc và kiểm soát xả đáy dựa trên chất lượng nước. Chức năng này không trùng với đối tượng và phạm vi mà câu hỏi yêu cầu.","Sai. “Tất cả three options provide identical nước savings và LEED tín chỉ value” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 556; Water Efficiency","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Option B because WaterSense fixtures are the most recognizable sustainable feature” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Option A — landscape eliminates 60–70% of water use in arid climates.”","Incorrect. “Option C because cooling towers use the most water in all climates” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Option A — landscape eliminates 60–70% of water use in arid climates.”","Incorrect. “All three options provide identical water savings and LEED credit value” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Option A — landscape eliminates 60–70% of water use in arid climates.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Climate context is critical for water strategy prioritization. In the American Southwest, landscape irrigation typically represents 50–70% of total water use. Eliminating irrigation through native planting provides dramatically more total water savings than fixture upgrades, making it the highest-value strategy despite higher upfront cost.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q056","core_concept_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-557","source_index":557,"q":"Sunset Career Academy high school project includes a 600-seat auditorium, 40 classrooms, athletic facilities, and cafeteria. The acoustic consultant says 'LEED for Schools has one acoustic standard for all spaces.' The LEED coordinator knows this is incorrect. What is the accurate description of acoustic requirements across different space types?","options":["Schools have space-type-specific acoustic requirements per ANSI/ASA S12.60 and others","Auditoriums and gymnasiums are exempt from LEED acoustic requirements","primarily classrooms require acoustic compliance; all other school spaces are exempted","All spaces in schools require identical acoustic treatment under LEED"],"answer":0,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Schools have space-type-specific acoustic requirements per ANSI/ASA S12.60 and others.","logic":"LEED for Schools' acoustic prerequisite and credits require space-type-appropriate acoustic performance. Classrooms target NC 35 max and specific reverberation times per ANSI/ASA S12.60 for speech intelligibility. Auditoriums, gymnasiums, and cafeterias each present entirely different acoustic challenges with different objectives — separate acoustic design is required.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EQ vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"prerequisite: điều kiện tiên quyết bắt buộc, không mang điểm; credit: yêu cầu tự chọn có thể mang lại điểm; indoor environmental quality: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; occupant health: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Schools có space-type-specific acoustic các yêu cầu per ANSI/ASA S12.60 và others” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Hiệu năng âm học phụ thuộc vào tiếng ồn nền, truyền âm và thời gian vang. Giải pháp đúng phải xử lý nguồn hoặc đường truyền âm tương ứng, không thay thế bằng một biện pháp IEQ khác. Trong bối cảnh câu hỏi, “Schools có space-type-specific acoustic các yêu cầu per ANSI/ASA S12.60 và others” áp dụng đúng nguyên tắc này; vì vậy phương án A đúng.","options_vi":["Schools có space-type-specific acoustic các yêu cầu per ANSI/ASA S12.60 và others","Auditoriums và gymnasiums là exempt từ LEED acoustic các yêu cầu","Chỉ classrooms yêu cầu acoustic sự tuân thủ; tất cả khác school spaces là exempted","Tất cả spaces trong schools yêu cầu identical acoustic treatment theo LEED"],"evidence_en":"LEED for Schools' acoustic prerequisite and credits require space-type-appropriate acoustic performance. Classrooms target NC 35 max and specific reverberation times per ANSI/ASA S12.60 for speech intelligibility. Auditoriums, gymnasiums, and cafeterias each present entirely different acoustic challenges with different objectives — separate acoustic design is required.","evidence_vi":"Hiệu năng âm học phụ thuộc vào tiếng ồn nền, truyền âm và thời gian vang. Giải pháp đúng phải xử lý nguồn hoặc đường truyền âm tương ứng, không thay thế bằng một biện pháp IEQ khác.","mechanism_vi":"Hiệu năng âm học phụ thuộc vào tiếng ồn nền, truyền âm và thời gian vang. Giải pháp đúng phải xử lý nguồn hoặc đường truyền âm tương ứng, không thay thế bằng một biện pháp IEQ khác.","wrong_reasons_vi":["Đúng. Hiệu năng âm học phụ thuộc vào tiếng ồn nền, truyền âm và thời gian vang. Giải pháp đúng phải xử lý nguồn hoặc đường truyền âm tương ứng, không thay thế bằng một biện pháp IEQ khác.","Sai. “Auditoriums và gymnasiums là exempt từ LEED acoustic các yêu cầu” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Chỉ classrooms yêu cầu acoustic sự tuân thủ; tất cả khác school spaces là exempted” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Tất cả spaces trong schools yêu cầu identical acoustic treatment theo LEED” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 557; Indoor Environmental Quality","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “Auditoriums and gymnasiums are exempt from LEED acoustic requirements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Schools have space-type-specific acoustic requirements per ANSI/ASA S12.60 and others.”","Incorrect. “Only classrooms require acoustic compliance; all other school spaces are exempted” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Schools have space-type-specific acoustic requirements per ANSI/ASA S12.60 and others.”","Incorrect. “All spaces in schools require identical acoustic treatment under LEED” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Schools have space-type-specific acoustic requirements per ANSI/ASA S12.60 and others.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED for Schools' acoustic prerequisite and credits require space-type-appropriate acoustic performance. Classrooms target NC 35 max and specific reverberation times per ANSI/ASA S12.60 for speech intelligibility. Auditoriums, gymnasiums, and cafeterias each present entirely different acoustic challenges with different objectives — separate acoustic design is required.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q057","core_concept_vi":"Hiệu năng âm học phụ thuộc vào tiếng ồn nền, truyền âm và thời gian vang. Giải pháp đúng phải xử lý nguồn hoặc đường truyền âm tương ứng, không thay thế bằng một biện pháp IEQ khác.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-558","source_index":558,"q":"Mapleview Elementary School's custodian has been using conventional janitorial products from the district's standard supply list — including bleach-based floor cleaner, petroleum-based furniture polish, and aerosol air fresheners. The principal notices occasional strong chemical odors and some student headaches. How does this relate to LEED's IEQ approach and what changes are needed?","options":["Replace the HVAC filters since they must be clogged if odors are detectable","Janitorial products are outside LEED's scope once the building is occupied","Implement a green cleaning program with EPA Safer Choice products and eliminate aerosols","Increase ventilation rates to dilute the cleaning chemical odors"],"answer":2,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Implement a green cleaning program with EPA Safer Choice products and eliminate aerosols.","logic":"Post-occupancy chemical management through green cleaning is as important as pre-occupancy low-emitting materials specification. A building designed with zero-VOC paints can have its IAQ degraded by conventional cleaning products (aerosol fresheners, petroleum polishes, bleach). For schools where children are vulnerable, EPA Safer Choice cleaning products and eliminating aerosols are essential.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","options_vi":["Replace HVAC filters vì they phải là clogged if odors là detectable","Janitorial sản phẩm là outside LEED's phạm vi once công trình là occupied","Triển khai xanh cleaning program với EPA Safer Choice sản phẩm và eliminate aerosols","Tăng thông gió lưu lượng để dilute cleaning chemical odors"],"evidence_en":"Post-occupancy chemical management through green cleaning is as important as pre-occupancy low-emitting materials specification. A building designed with zero-VOC paints can have its IAQ degraded by conventional cleaning products (aerosol fresheners, petroleum polishes, bleach). For schools where children are vulnerable, EPA Safer Choice cleaning products and eliminating aerosols are essential.","evidence_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","mechanism_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","wrong_reasons_vi":["Sai. “Replace HVAC filters vì they phải là clogged if odors là detectable” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Janitorial sản phẩm là outside LEED's phạm vi once công trình là occupied” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","Sai. “Tăng thông gió lưu lượng để dilute cleaning chemical odors” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 558; Indoor Environmental Quality","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Replace the HVAC filters since they must be clogged if odors are detectable” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Implement a green cleaning program with EPA Safer Choice products and eliminate aerosols.”","Incorrect. “Janitorial products are outside LEED's scope once the building is occupied” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Implement a green cleaning program with EPA Safer Choice products and eliminate aerosols.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Increase ventilation rates to dilute the cleaning chemical odors” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Implement a green cleaning program with EPA Safer Choice products and eliminate aerosols.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Post-occupancy chemical management through green cleaning is as important as pre-occupancy low-emitting materials specification. A building designed with zero-VOC paints can have its IAQ degraded by conventional cleaning products (aerosol fresheners, petroleum polishes, bleach). For schools where children are vulnerable, EPA Safer Choice cleaning products and eliminating aerosols are essential.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q058","core_concept_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-559","source_index":559,"q":"Meridian Corporate Campus plans to install 1 MW of rooftop solar generating ~1,300,000 kWh/year. Building uses 5,000,000 kWh/year. The finance team wants to sell all the RECs generated for $0.05/REC = $65,000/year revenue. The LEED team objects. What is the LEED issue and how should it be resolved?","options":["Selling RECs has no effect on LEED renewable energy credits","Selling RECs increases the LEED credit value since more money is invested in renewables","REC sales are irrelevant to LEED renewable energy credits in all circumstances","Selling RECs transfers the renewable attribute — building can't claim the RE Production credit"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"renewable energy: energy from sources that are naturally replenished; credit: an optional LEED requirement that can earn points; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Selling RECs transfers the renewable attribute — building can't claim the RE Production credit.","logic":"RECs represent the renewable attribute of generated electricity. When sold, that attribute belongs to the buyer. A building that installs solar PV but sells all RECs has, from an accounting perspective, generated unclaimed renewable electricity — it cannot claim the LEED Renewable Energy Production credit for generation whose renewable attribute has been legally transferred away. Retain the RECs.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Selling RECs có Không effect trên LEED năng lượng tái tạo tín chỉ","Selling RECs increases LEED tín chỉ value vì nhiều hơn money là invested trong renewables","REC sales là irrelevant để LEED năng lượng tái tạo tín chỉ trong tất cả circumstances","Selling RECs transfers renewable attribute - công trình can't claim RE Production tín chỉ"],"evidence_en":"RECs represent the renewable attribute of generated electricity. When sold, that attribute belongs to the buyer. A building that installs solar PV but sells all RECs has, from an accounting perspective, generated unclaimed renewable electricity — it cannot claim the LEED Renewable Energy Production credit for generation whose renewable attribute has been legally transferred away. Retain the RECs.","evidence_vi":"Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Trong khi đó, câu hỏi đang kiểm tra năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích.","Sai. Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Trong khi đó, câu hỏi đang kiểm tra năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích.","Sai. Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Trong khi đó, câu hỏi đang kiểm tra năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích.","Đúng. Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 559; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Selling RECs has no effect on LEED renewable energy credits” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Selling RECs transfers the renewable attribute — building can't claim the RE Production credit.”","Incorrect. “Selling RECs increases the LEED credit value since more money is invested in renewables” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Selling RECs transfers the renewable attribute — building can't claim the RE Production credit.”","Incorrect. “REC sales are irrelevant to LEED renewable energy credits in all circumstances” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Selling RECs transfers the renewable attribute — building can't claim the RE Production credit.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"RECs represent the renewable attribute of generated electricity. When sold, that attribute belongs to the buyer. A building that installs solar PV but sells all RECs has, from an accounting perspective, generated unclaimed renewable electricity — it cannot claim the LEED Renewable Energy Production credit for generation whose renewable attribute has been legally transferred away. Retain the RECs.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q059","core_concept_vi":"Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-560","source_index":560,"q":"Solstice Energy Campus is tracking 54 points (Silver) and needs 6 more for Gold. The sustainability team proposes: (A) converting 1 acre of parking to bioretention prairie, (B) installing a green roof on 50% of the roof area, (C) upgrading all exterior lighting to dark-sky compliant LED. How much can the SS category contribute to closing this gap?","options":["The SS strategies provide 0 points since the building is already past design","All three together could earn 5–7 SS points — sufficient to reach Gold","All three strategies together earn exactly 1 SS point","SS credits cannot be changed after the schematic design phase"],"answer":1,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"green roof: a vegetated roof assembly that can reduce runoff and heat gain; credit: an optional LEED requirement that can earn points; sustainable sites: strategies that protect site ecology and manage construction and operational site impacts","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: All three together could earn 5–7 SS points — sufficient to reach Gold.","logic":"This case tests practical LEED strategy optimization: when close to a certification threshold, understanding the point value of each strategy enables targeted investment. Strategy A earns 3–4 points (Rainwater + Habitat + Open Space), Strategy B earns 1–2 (Heat Island), Strategy C earns 1 (Light Pollution) — collectively 5–7 SS points, enough to close the Silver-to-Gold gap.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; sustainable sites: khu đất bền vững; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Tập trung vào “exterior lighting”. Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["SS giải pháp provide 0 điểm vì công trình là already past thiết kế","Tất cả three together có thể nhận 5-7 SS điểm - sufficient để reach Gold","Tất cả three giải pháp together nhận exactly 1 SS điểm","SS tín chỉ cannot là changed sau khi schematic thiết kế giai đoạn"],"evidence_en":"This case tests practical LEED strategy optimization: when close to a certification threshold, understanding the point value of each strategy enables targeted investment. Strategy A earns 3–4 points (Rainwater + Habitat + Open Space), Strategy B earns 1–2 (Heat Island), Strategy C earns 1 (Light Pollution) — collectively 5–7 SS points, enough to close the Silver-to-Gold gap.","evidence_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “SS giải pháp provide 0 điểm vì công trình là already past thiết kế” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Tất cả three giải pháp together nhận exactly 1 SS điểm” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “SS tín chỉ cannot là changed sau khi schematic thiết kế giai đoạn” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 560; Sustainable Sites","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “The SS strategies provide 0 points since the building is already past design” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “All three together could earn 5–7 SS points — sufficient to reach Gold.”","Correct. This option directly satisfies the governing condition.","Incorrect. “All three strategies together earn exactly 1 SS point” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “All three together could earn 5–7 SS points — sufficient to reach Gold.”","Incorrect. “SS credits cannot be changed after the schematic design phase” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “All three together could earn 5–7 SS points — sufficient to reach Gold.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"This case tests practical LEED strategy optimization: when close to a certification threshold, understanding the point value of each strategy enables targeted investment. Strategy A earns 3–4 points (Rainwater + Habitat + Open Space), Strategy B earns 1–2 (Heat Island), Strategy C earns 1 (Light Pollution) — collectively 5–7 SS points, enough to close the Silver-to-Gold gap.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q060","core_concept_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-561","source_index":561,"q":"Westgate Legal Services occupies 3 floors of a downtown office tower. Their LEED ID+C project specifies low-VOC materials throughout. Three months after moving in, air quality testing shows formaldehyde at 24 ppb — above the LEED limit of 16.3 ppb. The LEED consultant identifies the base building's existing acoustic ceiling tiles (not part of the tenant fit-out) as the likely formaldehyde source. Is this the tenant's LEED problem, and what are the options?","options":["The tenant must immediately remove and replace all base building ceiling tiles regardless of lease terms","The tenant cannot be held responsible for base building materials","Formaldehyde from base building materials is by itself excluded from LEED testing requirements","Genuinely complex — engage the base building owner, supplement ventilation, document"],"answer":3,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Genuinely complex — engage the base building owner, supplement ventilation, document.","logic":"Tenant LEED certifications are complicated by base building materials outside the tenant's scope. The tenant's low-emitting materials credit covers only their installed products. However, occupant health is affected regardless of who specified the tiles. The practical path: engage the base building owner to replace, implement supplemental ventilation, apply sealers as a stopgap, and document that the source is outside tenant scope.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Tenant phải immediately remove và replace tất cả base công trình ceiling tiles regardless của lease terms","Tenant cannot là held có trách nhiệm cho base công trình vật liệu","Formaldehyde từ base công trình vật liệu là Tự động excluded từ LEED testing các yêu cầu","Genuinely complex - engage base công trình owner, supplement thông gió, document"],"evidence_en":"Tenant LEED certifications are complicated by base building materials outside the tenant's scope. The tenant's low-emitting materials credit covers only their installed products. However, occupant health is affected regardless of who specified the tiles. The practical path: engage the base building owner to replace, implement supplemental ventilation, apply sealers as a stopgap, and document that the source is outside tenant scope.","evidence_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. “Tenant phải immediately remove và replace tất cả base công trình ceiling tiles regardless của lease terms” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Tenant cannot là held có trách nhiệm cho base công trình vật liệu” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Formaldehyde từ base công trình vật liệu là Tự động excluded từ LEED testing các yêu cầu” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 561; Indoor Environmental Quality","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “The tenant must immediately remove and replace all base building ceiling tiles regardless of lease terms” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Genuinely complex — engage the base building owner, supplement ventilation, document.”","Incorrect. “The tenant cannot be held responsible for base building materials” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Genuinely complex — engage the base building owner, supplement ventilation, document.”","Incorrect. “Formaldehyde from base building materials is automatically excluded from LEED testing requirements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Genuinely complex — engage the base building owner, supplement ventilation, document.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Tenant LEED certifications are complicated by base building materials outside the tenant's scope. The tenant's low-emitting materials credit covers only their installed products. However, occupant health is affected regardless of who specified the tiles. The practical path: engage the base building owner to replace, implement supplemental ventilation, apply sealers as a stopgap, and document that the source is outside tenant scope.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q061","core_concept_vi":"Vật liệu phát thải thấp kiểm soát nguồn ô nhiễm bên trong lớp chống thời tiết; yêu cầu có thể bao gồm hàm lượng VOC và phát thải VOC tùy nhóm sản phẩm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-562","source_index":562,"q":"Verdant Pharmaceutical Campus has significant process water demands from laboratory purification systems (30 gallons reject per 10 gallons purified), autoclaves, and process cooling. The sustainability manager wants to claim all water reductions in the Indoor Water Use Reduction credit. Should process water be included?","options":["All process water must be included in the LEED Indoor Water Use Reduction calculation","Including process water is prohibited for laboratories due to safety concerns","Process water in pharmaceutical facilities is by itself excluded by LEED default","Inclusion is typically better when efficiency measures exist for high-volume process water"],"answer":3,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the WE concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"indoor water use reduction: reduction of water used by indoor fixtures, fittings, and appliances; credit: an optional LEED requirement that can earn points; water efficiency: reduction and responsible management of indoor, outdoor, and process water use","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Inclusion is typically better when efficiency measures exist for high-volume process water.","logic":"Process water inclusion/exclusion is an elective decision. For pharmaceutical campuses where process water may dwarf domestic fixture use (3–5×), inclusion is typically better if meaningful efficiency measures exist. RO reject water recycling, air-cooled autoclaves, and closed-loop process cooling can dramatically reduce process water use — claiming these reductions through inclusion yields much higher percentage reductions.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc WE vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; indoor water use reduction: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; water efficiency: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Inclusion là typically better khi nào hiệu suất đo exist cho high-volume quy trình nước” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị. Trong bối cảnh câu hỏi, “Inclusion là typically better khi nào hiệu suất đo exist cho high-volume quy trình nước” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Tất cả quy trình nước phải là included trong LEED trong nhà mức sử dụng nước mức giảm calculation","Including quy trình nước là prohibited cho laboratories due để safety concerns","Quy trình nước trong pharmaceutical facilities là Tự động excluded bằng LEED default","Inclusion là typically better khi nào hiệu suất đo exist cho high-volume quy trình nước"],"evidence_en":"Process water inclusion/exclusion is an elective decision. For pharmaceutical campuses where process water may dwarf domestic fixture use (3–5×), inclusion is typically better if meaningful efficiency measures exist. RO reject water recycling, air-cooled autoclaves, and closed-loop process cooling can dramatically reduce process water use — claiming these reductions through inclusion yields much higher percentage reductions.","evidence_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","mechanism_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","wrong_reasons_vi":["Sai. “Tất cả quy trình nước phải là included trong LEED trong nhà mức sử dụng nước mức giảm calculation” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Including quy trình nước là prohibited cho laboratories due để safety concerns” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Quy trình nước trong pharmaceutical facilities là Tự động excluded bằng LEED default” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 562; Water Efficiency","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “All process water must be included in the LEED Indoor Water Use Reduction calculation” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Inclusion is typically better when efficiency measures exist for high-volume process water.”","Incorrect. “Including process water is prohibited for laboratories due to safety concerns” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Inclusion is typically better when efficiency measures exist for high-volume process water.”","Incorrect. “Process water in pharmaceutical facilities is automatically excluded by LEED default” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Inclusion is typically better when efficiency measures exist for high-volume process water.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Process water inclusion/exclusion is an elective decision. For pharmaceutical campuses where process water may dwarf domestic fixture use (3–5×), inclusion is typically better if meaningful efficiency measures exist. RO reject water recycling, air-cooled autoclaves, and closed-loop process cooling can dramatically reduce process water use — claiming these reductions through inclusion yields much higher percentage reductions.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q062","core_concept_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-563","source_index":563,"q":"Lakewood Community Center received 58 points (Silver) with two denied credits in their construction review. They were targeting Gold (60+). One denial involves an error in the energy model boundary; the other is a documentation ambiguity in a materials credit. What is the team's best strategic option?","options":["Analyze each denial; technical errors and ambiguities are often worth appealing for Gold","Accept Silver and immediately start a new LEED O+M certification to achieve Gold","Appeal both credits simultaneously to maximize chances","Accept Silver — appealing is is generally not worth the cost"],"answer":0,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"BEST_FIRST","purpose":"Assess whether the learner can apply the Overview concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"energy model: a simulation used to estimate and compare building energy performance; credit: an optional LEED requirement that can earn points; certification: third-party confirmation that a project satisfies applicable LEED requirements; best: a word asking for the strongest or most effective option; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Distinguish the technical requirement from the document or evidence that verifies it; decisive evidence: Analyze each denial; technical errors and ambiguities are often worth appealing for Gold.","logic":"Strategic analysis of denial reasons is critical before deciding whether to appeal. Technical errors (wrong model boundary) are often correctable with high success probability. Documentation ambiguities can often be resolved with clarifying narratives. When only 2 credits separate certification levels (Silver vs. Gold), the appeal cost is usually justified.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu Overview, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; appeal: yêu cầu xem xét lại quyết định review đã ban hành; energy model: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Analyze mỗi denial; technical errors và ambiguities là often worth appealing cho Gold” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế. Trong bối cảnh câu hỏi, “Analyze mỗi denial; technical errors và ambiguities là often worth appealing cho Gold” áp dụng đúng nguyên tắc này; vì vậy phương án A đúng.","options_vi":["Analyze mỗi denial; technical errors và ambiguities là often worth appealing cho Gold","Accept Silver và immediately start một mới LEED O+M chứng nhận để achieve Gold","Appeal cả hai tín chỉ simultaneously để maximize chances","Accept Silver - appealing là Không bao giờ worth cost"],"evidence_en":"Strategic analysis of denial reasons is critical before deciding whether to appeal. Technical errors (wrong model boundary) are often correctable with high success probability. Documentation ambiguities can often be resolved with clarifying narratives. When only 2 credits separate certification levels (Silver vs. Gold), the appeal cost is usually justified.","evidence_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","mechanism_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","wrong_reasons_vi":["Đúng. Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","Sai. “Accept Silver và immediately start một mới LEED O+M chứng nhận để achieve Gold” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Appeal cả hai tín chỉ simultaneously để maximize chances” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Accept Silver - appealing là Không bao giờ worth cost” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 563; LEED Overview & Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “Accept Silver and immediately start a new LEED O+M certification to achieve Gold” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Analyze each denial; technical errors and ambiguities are often worth appealing for Gold.”","Incorrect. “Appeal both credits simultaneously to maximize chances” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Analyze each denial; technical errors and ambiguities are often worth appealing for Gold.”","Incorrect. “Accept Silver — appealing is never worth the cost” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Analyze each denial; technical errors and ambiguities are often worth appealing for Gold.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"Strategic analysis of denial reasons is critical before deciding whether to appeal. Technical errors (wrong model boundary) are often correctable with high success probability. Documentation ambiguities can often be resolved with clarifying narratives. When only 2 credits separate certification levels (Silver vs. Gold), the appeal cost is usually justified.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q063","core_concept_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-564","source_index":564,"q":"The Greenfield Innovation Hub is being developed on a remediated former industrial brownfield. The developer has cleaned up the contamination to residential standards (stricter than commercial). What LEED credit primarily rewards their site selection decision?","options":["Location & Transportation: High Priority Site (Brownfield Redevelopment)","Indoor Environmental Quality, because the occupants are protected from contamination","Sustainable Sites, because the contamination was in the soil","Energy & Atmosphere, because the remediation used renewable energy equipment"],"answer":0,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the Overview concept and solve this best-fit question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"renewable energy: energy from sources that are naturally replenished; indoor environmental quality: indoor conditions affecting occupant health, comfort, and well-being; brownfield: previously developed land with actual or perceived contamination; innovation: a strategy with significant benefit not adequately addressed by existing LEED credits; credit: an optional LEED requirement that can earn points","keywords":"Choose the option that addresses the stated LEED intent most directly, not a secondary benefit; decisive option: Location & Transportation: High Priority Site (Brownfield Redevelopment).","logic":"Brownfield redevelopment earns the High Priority Site credit and potentially the Sensitive Land Protection credit. Building on remediated brownfield rather than greenfield earns 3–4 LT points before any design decisions. Remediating to residential standards above commercial requirements demonstrates exceptional environmental stewardship worth recognizing.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm Overview đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Vị trí & giao thông: cao ưu tiên khu đất (khu đất ô nhiễm đã phát triển tái phát triển)","Chất lượng môi trường trong nhà, vì người sử dụng là protected từ contamination","Sustainable Sites, vì contamination là trong soil","Năng lượng & Atmosphere, vì remediation used năng lượng tái tạo thiết bị"],"evidence_en":"Brownfield redevelopment earns the High Priority Site credit and potentially the Sensitive Land Protection credit. Building on remediated brownfield rather than greenfield earns 3–4 LT points before any design decisions. Remediating to residential standards above commercial requirements demonstrates exceptional environmental stewardship worth recognizing.","evidence_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “Chất lượng môi trường trong nhà, vì người sử dụng là protected từ contamination” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Sustainable Sites, vì contamination là trong soil” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. Năng lượng tái tạo cần được đánh giá cùng quyền sở hữu và hủy thuộc tính môi trường để tránh tính trùng lợi ích. Trong khi đó, câu hỏi đang kiểm tra brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 564; LEED Overview & Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “Indoor Environmental Quality, because the occupants are protected from contamination” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Location & Transportation: High Priority Site (Brownfield Redevelopment).”","Incorrect. “Sustainable Sites, because the contamination was in the soil” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Location & Transportation: High Priority Site (Brownfield Redevelopment).”","Incorrect. “Energy & Atmosphere, because the remediation used renewable energy equipment” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Location & Transportation: High Priority Site (Brownfield Redevelopment).”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"Brownfield redevelopment earns the High Priority Site credit and potentially the Sensitive Land Protection credit. Building on remediated brownfield rather than greenfield earns 3–4 LT points before any design decisions. Remediating to residential standards above commercial requirements demonstrates exceptional environmental stewardship worth recognizing.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q064","core_concept_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-565","source_index":565,"q":"Millfield Elementary School has zero permanent irrigation. The landscape architect selected native prairie plants and established them with temporary drip irrigation for the first two growing seasons. After 3 years, the prairie thrives on natural rainfall alone. What level of outdoor water reduction can they claim, and how should it be documented?","options":["The 2-year temporary irrigation period means the credit cannot be earned","primarily 30% reduction can be claimed since the school used temporary irrigation during establishment","100% reduction — temporary establishment irrigation does not constitute a permanent system","The school can primarily claim 50% reduction since some irrigation was used historically"],"answer":2,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"BEST_FIRST","purpose":"Assess whether the learner can apply the WE concept and solve this sequence question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; water efficiency: reduction and responsible management of indoor, outdoor, and process water use; water performance: measured water consumption and the effectiveness of water-saving strategies","keywords":"Choose the action that must occur early enough to influence subsequent project decisions; decisive action: 100% reduction — temporary establishment irrigation does not constitute a permanent system.","logic":"LEED explicitly distinguishes between permanent irrigation systems (which define the baseline) and temporary establishment irrigation. Once temporary irrigation is removed and the landscape is self-sustaining on natural rainfall, the project legitimately claims 100% outdoor water reduction. Documentation includes design, removed temporary irrigation specs, and photos of the established landscape.","purpose_vi":"Kiểm tra khả năng xác định đúng hồ sơ hoặc dữ liệu dùng để chứng minh yêu cầu WE, không nhầm với tài liệu có chức năng khác.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; water efficiency: hiệu quả sử dụng nước; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","options_vi":["2-year temporary irrigation period có nghĩa là tín chỉ cannot là earned","Chỉ 30% mức giảm có thể là claimed vì school used temporary irrigation trong quá trình establishment","100% mức giảm - temporary establishment irrigation does không constitute permanent hệ thống","School có thể chỉ claim 50% mức giảm vì some irrigation là used historically"],"evidence_en":"LEED explicitly distinguishes between permanent irrigation systems (which define the baseline) and temporary establishment irrigation. Once temporary irrigation is removed and the landscape is self-sustaining on natural rainfall, the project legitimately claims 100% outdoor water reduction. Documentation includes design, removed temporary irrigation specs, and photos of the established landscape.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","wrong_reasons_vi":["Sai. “2-year temporary irrigation period có nghĩa là tín chỉ cannot là earned” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Chỉ 30% mức giảm có thể là claimed vì school used temporary irrigation trong quá trình establishment” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","Sai. “School có thể chỉ claim 50% mức giảm vì some irrigation là used historically” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 565; Water Efficiency","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “The 2-year temporary irrigation period means the credit cannot be earned” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “100% reduction — temporary establishment irrigation does not constitute a permanent system.”","Incorrect. “Only 30% reduction can be claimed since the school used temporary irrigation during establishment” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “100% reduction — temporary establishment irrigation does not constitute a permanent system.”","Correct. This option directly satisfies the governing condition.","Incorrect. “The school can only claim 50% reduction since some irrigation was used historically” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “100% reduction — temporary establishment irrigation does not constitute a permanent system.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED explicitly distinguishes between permanent irrigation systems (which define the baseline) and temporary establishment irrigation. Once temporary irrigation is removed and the landscape is self-sustaining on natural rainfall, the project legitimately claims 100% outdoor water reduction. Documentation includes design, removed temporary irrigation specs, and photos of the established landscape.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q065","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-566","source_index":566,"q":"Nova Science Museum's design includes a 2-acre surface parking lot for 350 cars. The sustainability director asks for a comprehensive cross-category impact assessment of this parking lot. What is the analysis?","options":["Surface parking lots have no environmental impact if they use LED lighting","Cross-category impacts: LT, SS (stormwater + heat island), WE, and missed solar opportunity","primarily the Sustainable Sites category is affected by parking lot design","Surface parking primarily affects the Location & Transportation category"],"answer":1,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"heat island: elevated temperatures caused by heat-absorbing built surfaces; location and transportation: strategies that reduce travel impacts through site selection and mobility options; transportation demand management: programs that reduce single-occupancy vehicle travel and parking demand","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Cross-category impacts: LT, SS (stormwater + heat island), WE, and missed solar opportunity.","logic":"Large surface parking lots are one of the most environmentally damaging single design decisions: they worsen stormwater (SS), create heat islands (SS), consume land that could be habitat (SS), fail the Reduced Parking Footprint credit (LT), and miss the solar canopy opportunity (EA). Comprehensive analysis reveals the full cross-category cost.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm LT đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"location and transportation: vị trí và giao thông; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Surface bãi đỗ xe lots có Không môi trường tác động if they sử dụng LED chiếu sáng","Cross-category tác động: LT, SS (stormwater + nhiệt island), WE, và missed mặt trời opportunity","Chỉ Sustainable Sites category là affected bằng bãi đỗ xe lot thiết kế","Surface bãi đỗ xe chỉ affects vị trí & giao thông category"],"evidence_en":"Large surface parking lots are one of the most environmentally damaging single design decisions: they worsen stormwater (SS), create heat islands (SS), consume land that could be habitat (SS), fail the Reduced Parking Footprint credit (LT), and miss the solar canopy opportunity (EA). Comprehensive analysis reveals the full cross-category cost.","evidence_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật.","Đúng. Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật.","Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 566; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Surface parking lots have no environmental impact if they use LED lighting” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Cross-category impacts: LT, SS (stormwater + heat island), WE, and missed solar opportunity.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Only the Sustainable Sites category is affected by parking lot design” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Cross-category impacts: LT, SS (stormwater + heat island), WE, and missed solar opportunity.”","Incorrect. “Surface parking only affects the Location & Transportation category” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Cross-category impacts: LT, SS (stormwater + heat island), WE, and missed solar opportunity.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"Large surface parking lots are one of the most environmentally damaging single design decisions: they worsen stormwater (SS), create heat islands (SS), consume land that could be habitat (SS), fail the Reduced Parking Footprint credit (LT), and miss the solar canopy opportunity (EA). Comprehensive analysis reveals the full cross-category cost.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q066","core_concept_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-567","source_index":567,"q":"Harborview Conference Center hosts 400-person events in a 10,000 sf ballroom designed for 200 occupants. During a sold-out event, a CO₂ monitor near the stage shows 2,400 ppm while the ASHRAE 62.1 design rate provides adequate ventilation only for 200 people. The event manager is asked to reduce attendance. What LEED credit should have prevented this situation?","options":["Demand-Controlled Ventilation — modulates outdoor air based on real-time CO₂","CO₂ above 2,000 ppm primarily affects occupants with pre-existing respiratory conditions","CO₂ above ASHRAE limits is acceptable for temporary events","Reducing the HVAC filter rating would improve air quality at high occupancy"],"answer":0,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Demand-Controlled Ventilation — modulates outdoor air based on real-time CO₂.","logic":"This case perfectly illustrates why DCV is valuable for variable-occupancy spaces. A fixed ventilation system sized for design occupancy (200) cannot respond to actual occupancy (400). DCV monitors CO₂ in real time and modulates outdoor air to maintain acceptable levels regardless of occupancy — protecting occupant health at peak events without requiring attendance reduction.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"ASHRAE 62.1 quy định thông gió và chất lượng không khí trong nhà chấp nhận được; không phải tiêu chuẩn năng lượng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Điều khiển theo nhu cầu thông gió - modulates ngoài trời không khí based về real-time CO₂","CO₂ above 2,000 ppm chỉ affects người sử dụng với pre-existing respiratory conditions","CO₂ above ASHRAE limits là acceptable cho temporary events","Giảm HVAC filter rating sẽ cải thiện không khí chất lượng at cao occupancy"],"evidence_en":"This case perfectly illustrates why DCV is valuable for variable-occupancy spaces. A fixed ventilation system sized for design occupancy (200) cannot respond to actual occupancy (400). DCV monitors CO₂ in real time and modulates outdoor air to maintain acceptable levels regardless of occupancy — protecting occupant health at peak events without requiring attendance reduction.","evidence_vi":"ASHRAE 62.1 quy định thông gió và chất lượng không khí trong nhà chấp nhận được; không phải tiêu chuẩn năng lượng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"ASHRAE 62.1 quy định thông gió và chất lượng không khí trong nhà chấp nhận được; không phải tiêu chuẩn năng lượng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. ASHRAE 62.1 quy định thông gió và chất lượng không khí trong nhà chấp nhận được; không phải tiêu chuẩn năng lượng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “CO₂ above 2,000 ppm chỉ affects người sử dụng với pre-existing respiratory conditions” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “CO₂ above ASHRAE limits là acceptable cho temporary events” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Giảm HVAC filter rating sẽ cải thiện không khí chất lượng at cao occupancy” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 567; Indoor Environmental Quality","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “CO₂ above 2,000 ppm only affects occupants with pre-existing respiratory conditions” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Demand-Controlled Ventilation — modulates outdoor air based on real-time CO₂.”","Incorrect. “CO₂ above ASHRAE limits is acceptable for temporary events” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Demand-Controlled Ventilation — modulates outdoor air based on real-time CO₂.”","Incorrect. “Reducing the HVAC filter rating would improve air quality at high occupancy” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Demand-Controlled Ventilation — modulates outdoor air based on real-time CO₂.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"This case perfectly illustrates why DCV is valuable for variable-occupancy spaces. A fixed ventilation system sized for design occupancy (200) cannot respond to actual occupancy (400). DCV monitors CO₂ in real time and modulates outdoor air to maintain acceptable levels regardless of occupancy — protecting occupant health at peak events without requiring attendance reduction.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q067","core_concept_vi":"ASHRAE 62.1 quy định thông gió và chất lượng không khí trong nhà chấp nhận được; không phải tiêu chuẩn năng lượng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-568","source_index":568,"q":"Harborfront Mixed-Use Development includes 300 residential units, 50,000 sf retail, and 30,000 sf office in a dense urban neighborhood with 15 qualifying transit lines within walking distance. How should the parking calculation for Reduced Parking Footprint account for the residential units?","options":["Residential units as the default approach require exactly 1 parking space each regardless of location","Use shared parking analysis since residential and commercial peaks don't coincide","Calculate parking demand based on the office component primarily, ignoring residential","The team must certify residential and commercial portions separately to calculate parking"],"answer":1,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"reduced parking footprint: a strategy that limits parking supply and associated environmental impacts; location and transportation: strategies that reduce travel impacts through site selection and mobility options; transportation demand management: programs that reduce single-occupancy vehicle travel and parking demand","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Use shared parking analysis since residential and commercial peaks don't coincide.","logic":"Shared parking analysis is valuable for mixed-use projects: residential needs overnight parking while commercial needs daytime parking. This temporal offset means fewer total spaces serve both uses than single-use analysis would require — a real cost saving that also earns the Reduced Parking Footprint credit.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm LT đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"location and transportation: vị trí và giao thông; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Residential units Luôn luôn yêu cầu exactly 1 bãi đỗ xe space mỗi regardless của vị trí","Sử dụng shared bãi đỗ xe phân tích vì residential và commercial peaks don't coincide","Calculate bãi đỗ xe demand based về office component chỉ, bỏ qua residential","Nhóm phải certify residential và commercial portions separately để calculate bãi đỗ xe"],"evidence_en":"Shared parking analysis is valuable for mixed-use projects: residential needs overnight parking while commercial needs daytime parking. This temporal offset means fewer total spaces serve both uses than single-use analysis would require — a real cost saving that also earns the Reduced Parking Footprint credit.","evidence_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người.","Đúng. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người.","Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 568; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Residential units always require exactly 1 parking space each regardless of location” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use shared parking analysis since residential and commercial peaks don't coincide.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Calculate parking demand based on the office component only, ignoring residential” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use shared parking analysis since residential and commercial peaks don't coincide.”","Incorrect. “The team must certify residential and commercial portions separately to calculate parking” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use shared parking analysis since residential and commercial peaks don't coincide.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"Shared parking analysis is valuable for mixed-use projects: residential needs overnight parking while commercial needs daytime parking. This temporal offset means fewer total spaces serve both uses than single-use analysis would require — a real cost saving that also earns the Reduced Parking Footprint credit.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q068","core_concept_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-569","source_index":569,"q":"Oakwood Corporate Campus generated: 850 tons concrete (recycled), 320 tons steel (recycled), 180 tons drywall (recycled), 90 tons wood (mulched), 45 tons cardboard (recycled), 35 tons mixed trash (landfilled), 20 tons hazardous waste (properly disposed). What is the project's C&D waste diversion rate?","options":["Mixed trash and hazardous waste must both be included in diversion rate calculations","A diversion rate below 100% cannot earn any LEED credit","100% since all recyclable materials were diverted","97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous waste) — exemplary performance"],"answer":3,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the MR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"waste diversion: keeping waste out of landfill or incineration through reuse, recycling, or recovery; exemplary performance: performance that substantially exceeds an existing LEED credit threshold; credit: an optional LEED requirement that can earn points","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: 97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous waste) — exemplary performance.","logic":"Calculation: excluding hazardous waste (separate regulated stream), total eligible = 1,520 tons; diverted = 850+320+180+90+45 = 1,485 tons; rate = 1,485 ÷ 1,520 = 97.7%. This significantly exceeds the standard 75% threshold and at 97.7% potentially qualifies for Exemplary Performance Innovation credit. Hazardous waste is correctly excluded from C&D calculations.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc MR vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; waste diversion: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; exemplary performance: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous chất thải) - exemplary hiệu suất” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới. Trong bối cảnh câu hỏi, “97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous chất thải) - exemplary hiệu suất” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Mixed trash và hazardous chất thải phải cả hai là included trong diversion rate calculations","Diversion rate below 100% cannot nhận bất kỳ LEED tín chỉ","100% vì tất cả recyclable vật liệu là diverted","97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous chất thải) - exemplary hiệu suất"],"evidence_en":"Calculation: excluding hazardous waste (separate regulated stream), total eligible = 1,520 tons; diverted = 850+320+180+90+45 = 1,485 tons; rate = 1,485 ÷ 1,520 = 97.7%. This significantly exceeds the standard 75% threshold and at 97.7% potentially qualifies for Exemplary Performance Innovation credit. Hazardous waste is correctly excluded from C&D calculations.","evidence_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","mechanism_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","wrong_reasons_vi":["Sai. “Mixed trash và hazardous chất thải phải cả hai là included trong diversion rate calculations” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Diversion rate below 100% cannot nhận bất kỳ LEED tín chỉ” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “100% vì tất cả recyclable vật liệu là diverted” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 569; Materials & Resources","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Mixed trash and hazardous waste must both be included in diversion rate calculations” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous waste) — exemplary performance.”","Incorrect. “A diversion rate below 100% cannot earn any LEED credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous waste) — exemplary performance.”","Incorrect. “100% since all recyclable materials were diverted” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “97.7% diversion: 1,485 ÷ 1,520 (excluding hazardous waste) — exemplary performance.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Calculation: excluding hazardous waste (separate regulated stream), total eligible = 1,520 tons; diverted = 850+320+180+90+45 = 1,485 tons; rate = 1,485 ÷ 1,520 = 97.7%. This significantly exceeds the standard 75% threshold and at 97.7% potentially qualifies for Exemplary Performance Innovation credit. Hazardous waste is correctly excluded from C&D calculations.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q069","core_concept_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-570","source_index":570,"q":"The Meridian Tower team registered under LEED BD+C: New Construction for a 45-story mixed-use tower. Halfway through design, the client decides to sell the office floors as individual condominiums. Is their rating system choice still appropriate?","options":["Continue with BD+C: New Construction — rating system changes are not permitted after registration","Re-evaluate the rating system per LEED guidance — possibly Multifamily Midrise or split certification","Submit a CIR requesting that residential floors be excluded from the LEED scope","Switch the entire project to LEED for Homes since it now has residential units"],"answer":1,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"certification: third-party confirmation that a project satisfies applicable LEED requirements; LEED: a third-party green building rating and certification system; compliance: satisfaction of the applicable requirement and documentation","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Re-evaluate the rating system per LEED guidance — possibly Multifamily Midrise or split certification.","logic":"When a project's program changes significantly mid-design, the rating system selection must be re-evaluated. LEED provides guidance on mixed-use and program-change scenarios. Contacting GBCI directly or submitting a CIR is the appropriate step when the applicable rating system is genuinely uncertain.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc Overview vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"CIR: yêu cầu giải thích chính thức cách áp dụng credit cho tình huống dự án; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; LEED: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; compliance: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Re-evaluate rating hệ thống per LEED guidance - possibly Multifamily Midrise hoặc split chứng nhận” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích. Trong bối cảnh câu hỏi, “Re-evaluate rating hệ thống per LEED guidance - possibly Multifamily Midrise hoặc split chứng nhận” áp dụng đúng nguyên tắc này; vì vậy phương án B đúng.","options_vi":["Continue với BD+C: mới thi công - rating hệ thống changes là không permitted sau khi registration","Re-evaluate rating hệ thống per LEED guidance - possibly Multifamily Midrise hoặc split chứng nhận","Nộp CIR requesting đó residential floors là excluded từ LEED phạm vi","Switch entire dự án để LEED cho Homes vì it now có residential units"],"evidence_en":"When a project's program changes significantly mid-design, the rating system selection must be re-evaluated. LEED provides guidance on mixed-use and program-change scenarios. Contacting GBCI directly or submitting a CIR is the appropriate step when the applicable rating system is genuinely uncertain.","evidence_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","mechanism_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","wrong_reasons_vi":["Sai. “Continue với BD+C: mới thi công - rating hệ thống changes là không permitted sau khi registration” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","Sai. “Nộp CIR requesting đó residential floors là excluded từ LEED phạm vi” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Switch entire dự án để LEED cho Homes vì it now có residential units” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 570; LEED Overview & Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Continue with BD+C: New Construction — rating system changes are not permitted after registration” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Re-evaluate the rating system per LEED guidance — possibly Multifamily Midrise or split certification.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Submit a CIR requesting that residential floors be excluded from the LEED scope” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Re-evaluate the rating system per LEED guidance — possibly Multifamily Midrise or split certification.”","Incorrect. “Switch the entire project to LEED for Homes since it now has residential units” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Re-evaluate the rating system per LEED guidance — possibly Multifamily Midrise or split certification.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"When a project's program changes significantly mid-design, the rating system selection must be re-evaluated. LEED provides guidance on mixed-use and program-change scenarios. Contacting GBCI directly or submitting a CIR is the appropriate step when the applicable rating system is genuinely uncertain.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q070","core_concept_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-571","source_index":571,"q":"Ferndale Elementary School's principal asks: 'Should we provide bicycle facilities since most of our students are too young to commute independently?' What is the correct response?","options":["Schools must provide identical bicycle facilities to commercial office buildings regardless of user age","Yes — facilities should serve staff and support safe routes for older students","primarily schools in cycling-friendly climates need to provide bicycle facilities","Bicycle facilities credits do not apply to schools since children cannot commute independently"],"answer":1,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; location and transportation: strategies that reduce travel impacts through site selection and mobility options; transportation demand management: programs that reduce single-occupancy vehicle travel and parking demand","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Yes — facilities should serve staff and support safe routes for older students.","logic":"LEED applies to real-world context. Elementary school bicycle facilities serve primarily staff (long-term storage, showers) and support safe routes to school programs (short-term racks). The credit intent — reducing vehicle trips, including parent drop-offs — is served by infrastructure enabling staff to arrive by active transportation.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc LT vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; location and transportation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; transportation demand management: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Có - facilities nên serve nhân viên và support safe routes cho older students” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu. Trong bối cảnh câu hỏi, “Có - facilities nên serve nhân viên và support safe routes cho older students” áp dụng đúng nguyên tắc này; vì vậy phương án B đúng.","options_vi":["Schools phải provide identical bicycle facilities để commercial office công trình regardless của user age","Có - facilities nên serve nhân viên và support safe routes cho older students","Chỉ schools trong cycling-friendly climates need để provide bicycle facilities","Bicycle facilities tín chỉ do không áp dụng để schools vì children cannot commute independently"],"evidence_en":"LEED applies to real-world context. Elementary school bicycle facilities serve primarily staff (long-term storage, showers) and support safe routes to school programs (short-term racks). The credit intent — reducing vehicle trips, including parent drop-offs — is served by infrastructure enabling staff to arrive by active transportation.","evidence_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","mechanism_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","wrong_reasons_vi":["Sai. “Schools phải provide identical bicycle facilities để commercial office công trình regardless của user age” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","Sai. “Chỉ schools trong cycling-friendly climates need để provide bicycle facilities” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Bicycle facilities tín chỉ do không áp dụng để schools vì children cannot commute independently” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 571; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Schools must provide identical bicycle facilities to commercial office buildings regardless of user age” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Yes — facilities should serve staff and support safe routes for older students.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Only schools in cycling-friendly climates need to provide bicycle facilities” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Yes — facilities should serve staff and support safe routes for older students.”","Incorrect. “Bicycle facilities credits do not apply to schools since children cannot commute independently” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Yes — facilities should serve staff and support safe routes for older students.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED applies to real-world context. Elementary school bicycle facilities serve primarily staff (long-term storage, showers) and support safe routes to school programs (short-term racks). The credit intent — reducing vehicle trips, including parent drop-offs — is served by infrastructure enabling staff to arrive by active transportation.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q071","core_concept_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-572","source_index":572,"q":"Riverside Community Center's ground-source heat pump shows COP of 2.1 in the first winter vs. design COP of 3.8. The contractor says 'heat pumps always perform below specification in the first winter.' The CxA disagrees. Who is correct?","options":["Ground-source heat pumps cannot operate efficiently below 32°F outdoor temperature","The contractor is correct — cold weather reduces heat pump performance","A COP of 2.1 in winter is acceptable for any heat pump system","CxA is right — 45% shortfall on a GSHP signals a system problem, not weather"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"BEST_FIRST","purpose":"Assess whether the learner can apply the EA concept and solve this sequence question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy; energy efficiency: delivery of the required service with less energy use","keywords":"Choose the action that must occur early enough to influence subsequent project decisions; decisive action: CxA is right — 45% shortfall on a GSHP signals a system problem, not weather.","logic":"A GSHP should be substantially unaffected by outdoor temperature since it exchanges heat with the ground at stable 50–60°F rather than outdoor air. A COP of 2.1 vs. 3.8 is a 45% shortfall strongly suggesting a system problem (antifreeze, flow rate, refrigerant charge, or controls), not weather. Post-occupancy COP measurement at this level is a commissioning failure that must be corrected.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Ground-source nhiệt pumps cannot operate efficiently below 32°F ngoài nhà nhiệt độ","Contractor là đúng - cold weather reduces nhiệt pump hiệu suất","COP của 2.1 trong winter là acceptable cho bất kỳ nhiệt pump hệ thống","CxA là right - 45% shortfall về một GSHP signals một hệ thống problem, không weather"],"evidence_en":"A GSHP should be substantially unaffected by outdoor temperature since it exchanges heat with the ground at stable 50–60°F rather than outdoor air. A COP of 2.1 vs. 3.8 is a 45% shortfall strongly suggesting a system problem (antifreeze, flow rate, refrigerant charge, or controls), not weather. Post-occupancy COP measurement at this level is a commissioning failure that must be corrected.","evidence_vi":"Commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. “Ground-source nhiệt pumps cannot operate efficiently below 32°F ngoài nhà nhiệt độ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Contractor là đúng - cold weather reduces nhiệt pump hiệu suất” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “COP của 2.1 trong winter là acceptable cho bất kỳ nhiệt pump hệ thống” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 572; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Ground-source heat pumps cannot operate efficiently below 32°F outdoor temperature” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “CxA is right — 45% shortfall on a GSHP signals a system problem, not weather.”","Incorrect. “The contractor is correct — cold weather reduces heat pump performance” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “CxA is right — 45% shortfall on a GSHP signals a system problem, not weather.”","Incorrect. “A COP of 2.1 in winter is acceptable for any heat pump system” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “CxA is right — 45% shortfall on a GSHP signals a system problem, not weather.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"A GSHP should be substantially unaffected by outdoor temperature since it exchanges heat with the ground at stable 50–60°F rather than outdoor air. A COP of 2.1 vs. 3.8 is a 45% shortfall strongly suggesting a system problem (antifreeze, flow rate, refrigerant charge, or controls), not weather. Post-occupancy COP measurement at this level is a commissioning failure that must be corrected.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q072","core_concept_vi":"Commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-573","source_index":573,"q":"The Old Town Redevelopment converts a historic 8-story building from warehousing to office use. The site is in a walkable urban neighborhood with excellent transit, is a documented remediated brownfield, and is in a historic district. What is the maximum number of LT credits this project can earn from site selection alone?","options":["Potentially 8–10 LT points from site selection alone before any design decisions","0 credits — site selection credits require building design elements","Site selection credits cannot be earned for buildings that have been contaminated","primarily 1 LT credit can be earned per project"],"answer":0,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"brownfield: previously developed land with actual or perceived contamination; credit: an optional LEED requirement that can earn points; maximum: the highest permitted value or level","keywords":"Identify the exact minimum, maximum, or numerical threshold requested; decisive value or condition: Potentially 8–10 LT points from site selection alone before any design decisions.","logic":"This case demonstrates the compounding LEED value of excellent site selection: brownfield + urban infill + walkable neighborhood + transit access + historic district = potentially 8–10 LT points purely from location before a single design decision. No amount of efficient HVAC or sustainable materials can earn LT points that only location provides.","purpose_vi":"Kiểm tra khả năng xác định đúng hồ sơ hoặc dữ liệu dùng để chứng minh yêu cầu LT, không nhầm với tài liệu có chức năng khác.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Có khả năng 8-10 LT điểm từ khu đất selection alone trước khi bất kỳ thiết kế quyết định","0 tín chỉ - khu đất selection tín chỉ yêu cầu công trình thiết kế elements","Khu đất selection tín chỉ cannot là earned cho công trình đó có được bị ô nhiễm","Chỉ 1 LT tín chỉ có thể là earned per dự án"],"evidence_en":"This case demonstrates the compounding LEED value of excellent site selection: brownfield + urban infill + walkable neighborhood + transit access + historic district = potentially 8–10 LT points purely from location before a single design decision. No amount of efficient HVAC or sustainable materials can earn LT points that only location provides.","evidence_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “0 tín chỉ - khu đất selection tín chỉ yêu cầu công trình thiết kế elements” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Khu đất selection tín chỉ cannot là earned cho công trình đó có được bị ô nhiễm” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Chỉ 1 LT tín chỉ có thể là earned per dự án” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 573; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “0 credits — site selection credits require building design elements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Potentially 8–10 LT points from site selection alone before any design decisions.”","Incorrect. “Site selection credits cannot be earned for buildings that have been contaminated” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Potentially 8–10 LT points from site selection alone before any design decisions.”","Incorrect. “Only 1 LT credit can be earned per project” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Potentially 8–10 LT points from site selection alone before any design decisions.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"This case demonstrates the compounding LEED value of excellent site selection: brownfield + urban infill + walkable neighborhood + transit access + historic district = potentially 8–10 LT points purely from location before a single design decision. No amount of efficient HVAC or sustainable materials can earn LT points that only location provides.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q073","core_concept_vi":"Brownfield là khu đất đã phát triển có ô nhiễm thực tế hoặc tiềm ẩn; tái phát triển giúp xử lý rủi ro và tận dụng hạ tầng hiện hữu. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-574","source_index":574,"q":"Sierra Pacific University wants to pursue a LEED Pilot Credit for 'Social Equity Within the Project Team' — rewarding equitable hiring practices, living wages, and workforce development in construction. Their general contractor resists, saying 'labor practices are outside LEED's scope.' What is the correct understanding and what documentation would be required?","options":["Social equity credits by itself earn LEED Gold certification","Labor practices are permanently outside LEED's scope and cannot earn any credit","LEED V5 Pilot Credits expand into social equity — workforce practices fit V5's quality of life pillar","Pilot Credits require unanimous agreement from all project team members"],"answer":2,"category":"Innovation & Regional Priority","source_domain":"Innovation & Regional Priority","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the PR concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; certification: third-party confirmation that a project satisfies applicable LEED requirements; documentation: records used to demonstrate compliance with a LEED requirement","keywords":"Distinguish the technical requirement from the document or evidence that verifies it; decisive evidence: LEED V5 Pilot Credits expand into social equity — workforce practices fit V5's quality of life pillar.","logic":"LEED V5's social equity expansion represents a genuine broadening of what 'sustainable building' means. Labor practices on construction sites — wages, safety, workforce development — directly affect the 'quality of life' pillar's social dimension. Pilot Credits allow these emerging concepts to be tested before formal inclusion. Documentation: payroll records, hiring data, training records, safety outcomes.","purpose_vi":"Kiểm tra khả năng chọn đúng hồ sơ hoặc dữ liệu chứng minh yêu cầu PR, phân biệt bằng chứng với biện pháp thiết kế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; certification: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; documentation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “LEED V5 Pilot tín chỉ expand thành social equity - workforce practices fit V5's chất lượng của cuộc sống pillar” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích. Trong bối cảnh câu hỏi, “LEED V5 Pilot tín chỉ expand thành social equity - workforce practices fit V5's chất lượng của cuộc sống pillar” áp dụng đúng nguyên tắc này; vì vậy phương án C đúng.","options_vi":["Social equity tín chỉ Tự động nhận LEED Gold certification","Labor practices là permanently outside LEED's phạm vi và cannot nhận bất kỳ tín chỉ","LEED V5 Pilot tín chỉ expand thành social equity - workforce practices fit V5's chất lượng của cuộc sống pillar","Pilot tín chỉ yêu cầu unanimous agreement từ tất cả dự án nhóm members"],"evidence_en":"LEED V5's social equity expansion represents a genuine broadening of what 'sustainable building' means. Labor practices on construction sites — wages, safety, workforce development — directly affect the 'quality of life' pillar's social dimension. Pilot Credits allow these emerging concepts to be tested before formal inclusion. Documentation: payroll records, hiring data, training records, safety outcomes.","evidence_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","mechanism_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","wrong_reasons_vi":["Sai. “Social equity tín chỉ Tự động nhận LEED Gold certification” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Labor practices là permanently outside LEED's phạm vi và cannot nhận bất kỳ tín chỉ” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","Sai. “Pilot tín chỉ yêu cầu unanimous agreement từ tất cả dự án nhóm members” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 574; Innovation & Regional Priority","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Social equity credits automatically earn LEED Gold certification” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED V5 Pilot Credits expand into social equity — workforce practices fit V5's quality of life pillar.”","Incorrect. “Labor practices are permanently outside LEED's scope and cannot earn any credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED V5 Pilot Credits expand into social equity — workforce practices fit V5's quality of life pillar.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Pilot Credits require unanimous agreement from all project team members” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED V5 Pilot Credits expand into social equity — workforce practices fit V5's quality of life pillar.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Ưu tiên khu vực - Innovation & Regional Priority","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED V5's social equity expansion represents a genuine broadening of what 'sustainable building' means. Labor practices on construction sites — wages, safety, workforce development — directly affect the 'quality of life' pillar's social dimension. Pilot Credits allow these emerging concepts to be tested before formal inclusion. Documentation: payroll records, hiring data, training records, safety outcomes.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q074","core_concept_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-575","source_index":575,"q":"Montrose Office Tower achieved a modeled 32% energy improvement over ASHRAE 90.1. After 2 years, Arc shows actual EUI of 68 kBtu/sf/yr vs. modeled 52 kBtu/sf/yr — a 31% gap. The building engineer insists the HVAC is working properly. What is the most systematic approach to diagnose and close this gap?","options":["Use M&V data systematically — schedules, plug loads, controls, and economizer first","The 31% gap is normal and no investigation is needed","Replace the energy model consultant since the model must be wrong","Report the gap to GBCI without investigation since post-occupancy performance is not a certification requirement"],"answer":0,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"energy model: a simulation used to estimate and compare building energy performance; certification: third-party confirmation that a project satisfies applicable LEED requirements; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Use M&V data systematically — schedules, plug loads, controls, and economizer first.","logic":"A 31% performance gap is well within the range that systematic retro-commissioning can address. The most common causes are HVAC operating outside occupied hours, plug loads exceeding model assumptions, and controls not functioning as designed (failed economizer, broken sensors). The M&V plan's submetering data isolates which system is responsible.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EA đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; energy and atmosphere: năng lượng và khí quyển; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["sử dụng M&V dữ liệu systematically - schedules, plug phụ tải, điều khiển, và economizer đầu tiên","31% gap là normal và Không investigation là needed","Replace năng lượng model consultant vì model phải là wrong","Báo cáo gap để GBCI mà không investigation vì sau khi đưa vào sử dụng hiệu suất là không một chứng nhận yêu cầu"],"evidence_en":"A 31% performance gap is well within the range that systematic retro-commissioning can address. The most common causes are HVAC operating outside occupied hours, plug loads exceeding model assumptions, and controls not functioning as designed (failed economizer, broken sensors). The M&V plan's submetering data isolates which system is responsible.","evidence_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “31% gap là normal và Không investigation là needed” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Replace năng lượng model consultant vì model phải là wrong” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Báo cáo gap để GBCI mà không investigation vì sau khi đưa vào sử dụng hiệu suất là không một chứng nhận yêu cầu” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 575; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “The 31% gap is normal and no investigation is needed” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use M&V data systematically — schedules, plug loads, controls, and economizer first.”","Incorrect. “Replace the energy model consultant since the model must be wrong” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use M&V data systematically — schedules, plug loads, controls, and economizer first.”","Incorrect. “Report the gap to GBCI without investigation since post-occupancy performance is not a certification requirement” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use M&V data systematically — schedules, plug loads, controls, and economizer first.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"A 31% performance gap is well within the range that systematic retro-commissioning can address. The most common causes are HVAC operating outside occupied hours, plug loads exceeding model assumptions, and controls not functioning as designed (failed economizer, broken sensors). The M&V plan's submetering data isolates which system is responsible.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q075","core_concept_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-576","source_index":576,"q":"Cascade Heights Residential Development wants zero stormwater runoff increase for all events up to the 2-year storm. Their civil engineer proposes an underground detention vault. The landscape architect proposes native plantings and bioswales. Which better serves both LEED and the client?","options":["Underground detention is mandatory since it is the primarily approach meeting LEED standards","Both approaches earn identical LEED credits","Underground detention is better because it is more reliable and requires less maintenance","Bioswales and natives — they earn Rainwater PLUS Habitat, Open Space, and Heat Island"],"answer":3,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"bioswale: a vegetated channel that slows, filters, and infiltrates stormwater; heat island: elevated temperatures caused by heat-absorbing built surfaces; credit: an optional LEED requirement that can earn points","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Bioswales and natives — they earn Rainwater PLUS Habitat, Open Space, and Heat Island.","logic":"Green infrastructure almost always outperforms gray in LEED: the bioswale approach addresses multiple credits (Rainwater Management + Habitat + Open Space + Heat Island Reduction) while the underground vault addresses only one. For comparable cost, the integrated landscape approach provides dramatically better LEED value and ecological co-benefits.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Underground detention là mandatory vì it là chỉ approach meeting LEED standards","Cả hai approaches nhận identical LEED tín chỉ","Underground detention là better vì it là nhiều hơn reliable và yêu cầu ít hơn maintenance","Bioswales và natives - they nhận Rainwater PLUS sinh cảnh, Open Space, và nhiệt Island"],"evidence_en":"Green infrastructure almost always outperforms gray in LEED: the bioswale approach addresses multiple credits (Rainwater Management + Habitat + Open Space + Heat Island Reduction) while the underground vault addresses only one. For comparable cost, the integrated landscape approach provides dramatically better LEED value and ecological co-benefits.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. “Underground detention là mandatory vì it là chỉ approach meeting LEED standards” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Cả hai approaches nhận identical LEED tín chỉ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Underground detention là better vì it là nhiều hơn reliable và yêu cầu ít hơn maintenance” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 576; Sustainable Sites","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Underground detention is mandatory since it is the only approach meeting LEED standards” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Bioswales and natives — they earn Rainwater PLUS Habitat, Open Space, and Heat Island.”","Incorrect. “Both approaches earn identical LEED credits” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Bioswales and natives — they earn Rainwater PLUS Habitat, Open Space, and Heat Island.”","Incorrect. “Underground detention is better because it is more reliable and requires less maintenance” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Bioswales and natives — they earn Rainwater PLUS Habitat, Open Space, and Heat Island.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Green infrastructure almost always outperforms gray in LEED: the bioswale approach addresses multiple credits (Rainwater Management + Habitat + Open Space + Heat Island Reduction) while the underground vault addresses only one. For comparable cost, the integrated landscape approach provides dramatically better LEED value and ecological co-benefits.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q076","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-577","source_index":577,"q":"Meadowbrook Elementary School achieved LEED Gold with 68 points. Their zip code has Regional Priority designations for: Rainwater Management (earned, 2 base credit points), Indoor Water Use Reduction (earned, 3 base credit points), Site Assessment (earned, 1 point), Protect or Restore Habitat (earned, 2 points), Heat Island Reduction (NOT earned), and Access to Quality Transit (NOT earned). How many RP bonus points does the project earn, and what is the final total LEED score?","options":["RP bonus points replace the base credit points rather than adding to them","The project earns 6 RP bonus points for all 6 RP-designated credits in their zip code","4 RP bonus points (only earned credits qualify) — final 72 points, still Gold","The project earns primarily 2 RP points since the maximum is determined by number of LEED categories"],"answer":2,"category":"Innovation & Regional Priority","source_domain":"Innovation & Regional Priority","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the PR concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"rainwater management: strategies that retain, infiltrate, evapotranspire, or reuse rainfall on site; indoor water use reduction: reduction of water used by indoor fixtures, fittings, and appliances; site assessment: analysis of site conditions used to inform sustainable design decisions; heat island: elevated temperatures caused by heat-absorbing built surfaces; regional priority: additional recognition for credits important to a project’s geographic region","keywords":"Identify the exact minimum, maximum, or numerical threshold requested; decisive value or condition: 4 RP bonus points (only earned credits qualify) — final 72 points, still Gold.","logic":"The RP calculation: 4 credits earned with RP designation × 1 bonus point each = 4 RP bonus points (also the maximum allowed). The 2 unearned RP credits earn 0 points regardless of designation. Base 68 + 4 RP = 72 total. This illustrates why identifying RP credits early is strategically valuable — the team earned 4 free bonus points simply from project location.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm PR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","options_vi":["RP bonus điểm replace base tín chỉ điểm rather hơn adding để them","Dự án đạt được 6 RP bonus điểm cho tất cả 6 RP-designated tín chỉ trong their zip code","4 RP bonus điểm (chỉ earned tín chỉ qualify) - cuối cùng 72 điểm, still Gold","Dự án đạt được chỉ 2 RP điểm vì tối đ là determined bằng number của LEED categories"],"evidence_en":"The RP calculation: 4 credits earned with RP designation × 1 bonus point each = 4 RP bonus points (also the maximum allowed). The 2 unearned RP credits earn 0 points regardless of designation. Base 68 + 4 RP = 72 total. This illustrates why identifying RP credits early is strategically valuable — the team earned 4 free bonus points simply from project location.","evidence_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","mechanism_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","wrong_reasons_vi":["Sai. “RP bonus điểm replace base tín chỉ điểm rather hơn adding để them” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Dự án đạt được 6 RP bonus điểm cho tất cả 6 RP-designated tín chỉ trong their zip code” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","Sai. “Dự án đạt được chỉ 2 RP điểm vì tối đ là determined bằng number của LEED categories” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 577; Innovation & Regional Priority","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “RP bonus points replace the base credit points rather than adding to them” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “4 RP bonus points (only earned credits qualify) — final 72 points, still Gold.”","Incorrect. “The project earns 6 RP bonus points for all 6 RP-designated credits in their zip code” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “4 RP bonus points (only earned credits qualify) — final 72 points, still Gold.”","Correct. This option directly satisfies the governing condition.","Incorrect. “The project earns only 2 RP points since the maximum is determined by number of LEED categories” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “4 RP bonus points (only earned credits qualify) — final 72 points, still Gold.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Ưu tiên khu vực - Innovation & Regional Priority","english_explanation_version":"v7.5.19-english-only","core_concept":"The RP calculation: 4 credits earned with RP designation × 1 bonus point each = 4 RP bonus points (also the maximum allowed). The 2 unearned RP credits earn 0 points regardless of designation. Base 68 + 4 RP = 72 total. This illustrates why identifying RP credits early is strategically valuable — the team earned 4 free bonus points simply from project location.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q077","core_concept_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-578","source_index":578,"q":"Cypress Creek Elementary School uses reclaimed water from a municipal recycled water system (purple pipe) for irrigation of their 2-acre school garden. The LEED team wants to claim this as an alternative water source for outdoor water use. The reviewer questions whether municipal reclaimed water qualifies. What is the correct answer?","options":["Yes — municipal reclaimed water is a recognized non-potable alternative water source","The school garden must use potable water to qualify for the LEED credit","Reclaimed water can primarily be used for cooling towers, not landscape irrigation","Municipal reclaimed water is not recognized as an alternative water source under LEED"],"answer":0,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the WE concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"cooling tower: heat-rejection equipment that commonly uses evaporation; credit: an optional LEED requirement that can earn points; water efficiency: reduction and responsible management of indoor, outdoor, and process water use","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Yes — municipal reclaimed water is a recognized non-potable alternative water source.","logic":"Municipal reclaimed water (purple pipe recycled water) is one of the most reliable and explicitly recognized alternative water sources in LEED. Unlike rainwater (weather-dependent) or graywater (requires on-site treatment), municipal reclaimed water is continuously available at appropriate quality for landscape irrigation. Document the connection, volume used, and cost.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm WE đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; water efficiency: hiệu quả sử dụng nước; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Có - municipal reclaimed nước là một recognized non-potable alternative nước nguồn","School garden phải sử dụng potable nước để qualify cho LEED tín chỉ","Reclaimed nước có thể chỉ là used cho cooling towers, không landscape irrigation","Municipal reclaimed nước là không recognized như alternative nước nguồn theo LEED"],"evidence_en":"Municipal reclaimed water (purple pipe recycled water) is one of the most reliable and explicitly recognized alternative water sources in LEED. Unlike rainwater (weather-dependent) or graywater (requires on-site treatment), municipal reclaimed water is continuously available at appropriate quality for landscape irrigation. Document the connection, volume used, and cost.","evidence_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “School garden phải sử dụng potable nước để qualify cho LEED tín chỉ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. Hiệu quả nước của tháp giải nhiệt phụ thuộc vào tăng an toàn chu kỳ cô đặc và kiểm soát xả đáy dựa trên chất lượng nước. Trong khi đó, câu hỏi đang kiểm tra thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh.","Sai. Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Trong khi đó, câu hỏi đang kiểm tra thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 578; Water Efficiency","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “The school garden must use potable water to qualify for the LEED credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Yes — municipal reclaimed water is a recognized non-potable alternative water source.”","Incorrect. “Reclaimed water can only be used for cooling towers, not landscape irrigation” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Yes — municipal reclaimed water is a recognized non-potable alternative water source.”","Incorrect. “Municipal reclaimed water is not recognized as an alternative water source under LEED” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Yes — municipal reclaimed water is a recognized non-potable alternative water source.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Municipal reclaimed water (purple pipe recycled water) is one of the most reliable and explicitly recognized alternative water sources in LEED. Unlike rainwater (weather-dependent) or graywater (requires on-site treatment), municipal reclaimed water is continuously available at appropriate quality for landscape irrigation. Document the connection, volume used, and cost.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q078","core_concept_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-579","source_index":579,"q":"Riverside Corporate Campus is LEED O+M certified. During the annual Arc performance review, the sustainability manager notices the Human Experience score has dropped from 78% to 61% over two years despite no major building changes. What is the most structured approach to diagnosing and addressing the decline?","options":["Occupant satisfaction naturally declines over time and no investigation is needed","Disaggregate the survey, cross-reference operations, interview occupants, target corrections","Replace all building HVAC equipment since a 17-point decline indicates major system failure","Accept the decline as normal variation and submit the survey results without investigation"],"answer":1,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants; occupant health: health outcomes influenced by indoor environmental conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Disaggregate the survey, cross-reference operations, interview occupants, target corrections.","logic":"A 17-point Human Experience drop with no major building changes is significant and almost certainly has identifiable causes. Structured diagnostic: disaggregate survey data by IEQ category, cross-reference with operational records (HVAC controls changes, cleaning protocols), interview dissatisfied occupants, compare building systems data with complaint areas, then target corrections — not arbitrary improvements.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"indoor environmental quality: chất lượng môi trường trong nhà; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Người sử dụng satisfaction naturally declines over time và Không investigation là needed","Disaggregate survey, cross-reference vận hành, interview người sử dụng, target corrections","Replace tất cả công trình HVAC thiết bị vì 17-điểm decline indicates chính hệ thống failure","Accept decline như normal variation và Nộp survey results không có investigation"],"evidence_en":"A 17-point Human Experience drop with no major building changes is significant and almost certainly has identifiable causes. Structured diagnostic: disaggregate survey data by IEQ category, cross-reference with operational records (HVAC controls changes, cleaning protocols), interview dissatisfied occupants, compare building systems data with complaint areas, then target corrections — not arbitrary improvements.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Người sử dụng satisfaction naturally declines over time và Không investigation là needed” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Replace tất cả công trình HVAC thiết bị vì 17-điểm decline indicates chính hệ thống failure” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Accept decline như normal variation và Nộp survey results không có investigation” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 579; Indoor Environmental Quality","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Occupant satisfaction naturally declines over time and no investigation is needed” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Disaggregate the survey, cross-reference operations, interview occupants, target corrections.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Replace all building HVAC equipment since a 17-point decline indicates major system failure” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Disaggregate the survey, cross-reference operations, interview occupants, target corrections.”","Incorrect. “Accept the decline as normal variation and submit the survey results without investigation” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Disaggregate the survey, cross-reference operations, interview occupants, target corrections.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"A 17-point Human Experience drop with no major building changes is significant and almost certainly has identifiable causes. Structured diagnostic: disaggregate survey data by IEQ category, cross-reference with operational records (HVAC controls changes, cleaning protocols), interview dissatisfied occupants, compare building systems data with complaint areas, then target corrections — not arbitrary improvements.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q079","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-580","source_index":580,"q":"The Catalyst Office Park parametric energy study evaluated 3,200 envelope combinations. It identified a 'Pareto optimal' solution achieving 38% energy improvement over ASHRAE 90.1 at a cost equivalent to a conventional high-performing building. The mechanical engineer then sized HVAC 25% smaller than originally planned. What does this demonstrate?","options":["Parametric studies as the default approach reduce construction costs — this is standard practice","Parametric analysis identified an optimum unfindable manually, enabling HVAC right-sizing","Parametric studies are primarily valuable for large projects over 500,000 sf","The mechanical engineer made an error by undersizing the HVAC system"],"answer":1,"category":"Integrative Process","source_domain":"Integrative Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the IP concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"integrative process: early cross-disciplinary analysis used to improve project decisions; systems thinking: evaluation of interactions among building, site, water, energy, and occupant systems","keywords":"Distinguish the technical requirement from the document or evidence that verifies it; decisive evidence: Parametric analysis identified an optimum unfindable manually, enabling HVAC right-sizing.","logic":"This case study illustrates the complete integrative process value proposition: computational optimization discovers performance levels unachievable through conventional design, which enables system right-sizing, which produces capital cost savings that far exceed the analysis investment. Design fees turn into construction savings plus performance gains.","purpose_vi":"Kiểm tra khả năng xác định đúng hồ sơ hoặc dữ liệu dùng để chứng minh yêu cầu IP, không nhầm với tài liệu có chức năng khác.","vocabulary_vi":"key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng; verification: việc dùng dữ liệu hoặc hồ sơ để xác nhận yêu cầu đã được đáp ứng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Parametric studies Luôn luôn giảm thi công costs - này là standard practice","Parametric phân tích identified một optimum unfindable manually, enabling HVAC right-sizing","Parametric studies là chỉ valuable cho large các dự án over 500,000 sf","Mechanical engineer made một error bằng undersizing HVAC hệ thống"],"evidence_en":"This case study illustrates the complete integrative process value proposition: computational optimization discovers performance levels unachievable through conventional design, which enables system right-sizing, which produces capital cost savings that far exceed the analysis investment. Design fees turn into construction savings plus performance gains.","evidence_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Parametric studies Luôn luôn giảm thi công costs - này là standard practice” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Parametric studies là chỉ valuable cho large các dự án over 500,000 sf” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Mechanical engineer made một error bằng undersizing HVAC hệ thống” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 580; Integrative Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Parametric studies always reduce construction costs — this is standard practice” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Parametric analysis identified an optimum unfindable manually, enabling HVAC right-sizing.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Parametric studies are only valuable for large projects over 500,000 sf” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Parametric analysis identified an optimum unfindable manually, enabling HVAC right-sizing.”","Incorrect. “The mechanical engineer made an error by undersizing the HVAC system” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Parametric analysis identified an optimum unfindable manually, enabling HVAC right-sizing.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Quy trình tích hợp - quy trình tích hợp","english_explanation_version":"v7.5.19-english-only","core_concept":"This case study illustrates the complete integrative process value proposition: computational optimization discovers performance levels unachievable through conventional design, which enables system right-sizing, which produces capital cost savings that far exceed the analysis investment. Design fees turn into construction savings plus performance gains.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q080","core_concept_vi":"ASHRAE 90.1 là tiêu chuẩn về hiệu suất năng lượng công trình, được dùng làm đường cơ sở hoặc yêu cầu tối thiểu tùy hệ thống đánh giá. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-581","source_index":581,"q":"Solaris Data Center operates 24/7 with a PUE of 1.35 vs. industry average of 1.58. The LEED energy model shows 22% improvement over ASHRAE baseline. The data center manager claims this is excellent performance. A sustainability consultant challenges this. Who is correct?","options":["A 22% improvement over ASHRAE is by itself the maximum achievable for data centers","PUE is the primarily energy metric that matters for data centers","The manager is correct — 1.35 PUE and 22% improvement are both excellent metrics","Consultant is right — LEED measures total building energy vs. ASHRAE, not just PUE"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; energy model: a simulation used to estimate and compare building energy performance; maximum: the highest permitted value or level","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Consultant is right — LEED measures total building energy vs. ASHRAE, not just PUE.","logic":"PUE measures one dimension of data center efficiency — overhead relative to IT load. LEED measures total building energy vs. baseline. A data center can have excellent PUE while still having poor absolute energy performance if IT equipment itself is inefficient. LEED BD+C: Data Centers uses appropriate baselines that account for IT loads, cooling, and power distribution.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EA vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"baseline: đường cơ sở dùng làm mốc so sánh hiệu suất; energy model: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; maximum: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Consultant là right - LEED đo tổng công trình năng lượng vs. ASHRAE, không just PUE” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế. Trong bối cảnh câu hỏi, “Consultant là right - LEED đo tổng công trình năng lượng vs. ASHRAE, không just PUE” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Một 22% improvement over ASHRAE là Tự động maximum achievable cho dữ liệu centers","PUE là chỉ năng lượng metric đó matters cho dữ liệu centers","Manager là đúng - 1.35 PUE và 22% improvement là cả hai excellent metrics","Consultant là right - LEED đo tổng công trình năng lượng vs. ASHRAE, không just PUE"],"evidence_en":"PUE measures one dimension of data center efficiency — overhead relative to IT load. LEED measures total building energy vs. baseline. A data center can have excellent PUE while still having poor absolute energy performance if IT equipment itself is inefficient. LEED BD+C: Data Centers uses appropriate baselines that account for IT loads, cooling, and power distribution.","evidence_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","mechanism_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","wrong_reasons_vi":["Sai. “Một 22% improvement over ASHRAE là Tự động maximum achievable cho dữ liệu centers” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “PUE là chỉ năng lượng metric đó matters cho dữ liệu centers” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Manager là đúng - 1.35 PUE và 22% improvement là cả hai excellent metrics” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 581; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “A 22% improvement over ASHRAE is automatically the maximum achievable for data centers” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Consultant is right — LEED measures total building energy vs. ASHRAE, not just PUE.”","Incorrect. “PUE is the only energy metric that matters for data centers” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Consultant is right — LEED measures total building energy vs. ASHRAE, not just PUE.”","Incorrect. “The manager is correct — 1.35 PUE and 22% improvement are both excellent metrics” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Consultant is right — LEED measures total building energy vs. ASHRAE, not just PUE.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"PUE measures one dimension of data center efficiency — overhead relative to IT load. LEED measures total building energy vs. baseline. A data center can have excellent PUE while still having poor absolute energy performance if IT equipment itself is inefficient. LEED BD+C: Data Centers uses appropriate baselines that account for IT loads, cooling, and power distribution.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q081","core_concept_vi":"Mô phỏng năng lượng là công cụ so sánh phương án với đường cơ sở trên cùng giả định, không phải dự báo chính xác hóa đơn tương lai. Kết quả có giá trị khi được dùng đủ sớm để tác động thiết kế.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-582","source_index":582,"q":"Skyline Medical Center included the commissioning authority (CxA) from the first design meeting — 18 months before construction. The CxA identified 12 systems interaction issues during design, recommended controls language reducing projected energy use by 4%, and helped avoid $340,000 in construction change orders — at $85,000 in additional commissioning cost. What LEED process does this exemplify?","options":["This exemplifies construction management best practice unrelated to LEED","Early CxA engagement is an optional practice that no LEED credit rewards","LEED's Enhanced Commissioning credit — early CxA engagement with 4:1 ROI","This is primarily required for the Fundamental Commissioning prerequisite"],"answer":2,"category":"Integrative Process","source_domain":"Integrative Process","question_style":"BEST_FIRST","purpose":"Assess whether the learner can apply the IP concept and solve this sequence question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"commissioning: a quality-focused process that verifies systems meet the owner’s project requirements; prerequisite: a mandatory requirement that earns no points but is required for certification; credit: an optional LEED requirement that can earn points; best: a word asking for the strongest or most effective option","keywords":"Choose the action that must occur early enough to influence subsequent project decisions; decisive action: LEED's Enhanced Commissioning credit — early CxA engagement with 4:1 ROI.","logic":"Early CxA engagement is the defining characteristic of LEED's Enhanced Commissioning credit. The $85K additional investment preventing $340K in change orders (4:1 ROI) is consistent with industry research showing Enhanced Commissioning typically returns $3–$7 for every $1 invested, while also improving energy performance.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm IP đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; commissioning: quá trình xác minh có hệ thống rằng công trình và hệ thống đáp ứng OPR và BOD; prerequisite: điều kiện tiên quyết bắt buộc để dự án đủ điều kiện chứng nhận; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"CxA dẫn dắt việc xác minh hệ thống có đáp ứng OPR và BOD thông qua rà soát, thử nghiệm và theo dõi vấn đề. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","options_vi":["Này exemplifies thi công quản lý tốt nhất practice unrelated để LEED","Sớm CxA engagement là optional practice đó Không LEED tín chỉ ghi nhận","LEED's tăng cường commissioning tín chỉ - sớm CxA engagement với 4:1 ROI","Này là chỉ được yêu cầu cho Fundamental commissioning điều kiện tiên quyết"],"evidence_en":"Early CxA engagement is the defining characteristic of LEED's Enhanced Commissioning credit. The $85K additional investment preventing $340K in change orders (4:1 ROI) is consistent with industry research showing Enhanced Commissioning typically returns $3–$7 for every $1 invested, while also improving energy performance.","evidence_vi":"CxA dẫn dắt việc xác minh hệ thống có đáp ứng OPR và BOD thông qua rà soát, thử nghiệm và theo dõi vấn đề. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","mechanism_vi":"CxA dẫn dắt việc xác minh hệ thống có đáp ứng OPR và BOD thông qua rà soát, thử nghiệm và theo dõi vấn đề. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","wrong_reasons_vi":["Sai. “Này exemplifies thi công quản lý tốt nhất practice unrelated để LEED” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Sớm CxA engagement là optional practice đó Không LEED tín chỉ ghi nhận” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. CxA dẫn dắt việc xác minh hệ thống có đáp ứng OPR và BOD thông qua rà soát, thử nghiệm và theo dõi vấn đề. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","Sai. Commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD. Trong khi đó, câu hỏi đang kiểm tra commissioning xác minh hệ thống được thiết kế, lắp đặt, thử nghiệm, điều khiển và vận hành phù hợp với OPR và BOD."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 582; Integrative Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “This exemplifies construction management best practice unrelated to LEED” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED's Enhanced Commissioning credit — early CxA engagement with 4:1 ROI.”","Incorrect. “Early CxA engagement is an optional practice that no LEED credit rewards” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED's Enhanced Commissioning credit — early CxA engagement with 4:1 ROI.”","Correct. This option directly satisfies the governing condition.","Incorrect. “This is only required for the Fundamental Commissioning prerequisite” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED's Enhanced Commissioning credit — early CxA engagement with 4:1 ROI.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Quy trình tích hợp - quy trình tích hợp","english_explanation_version":"v7.5.19-english-only","core_concept":"Early CxA engagement is the defining characteristic of LEED's Enhanced Commissioning credit. The $85K additional investment preventing $340K in change orders (4:1 ROI) is consistent with industry research showing Enhanced Commissioning typically returns $3–$7 for every $1 invested, while also improving energy performance.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q082","core_concept_vi":"CxA dẫn dắt việc xác minh hệ thống có đáp ứng OPR và BOD thông qua rà soát, thử nghiệm và theo dõi vấn đề. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án C đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-583","source_index":583,"q":"Harborview Community Center's actual water consumption is 180% of the design prediction despite WaterSense-specified fixtures throughout. What is the systematic approach to diagnosing and correcting this performance gap?","options":["Report the variance to GBCI as a certification misrepresentation issue","Use systematic submetering data to isolate the source — leaks, occupancy, irrigation","The WaterSense certification must be invalid — replace all fixtures immediately","Accept the variance as normal operating fluctuation"],"answer":1,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the WE concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"submetering: separate measurement of water or energy use by system or end use; certification: third-party confirmation that a project satisfies applicable LEED requirements; water efficiency: reduction and responsible management of indoor, outdoor, and process water use","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Use systematic submetering data to isolate the source — leaks, occupancy, irrigation.","logic":"180% of design prediction is a significant variance requiring systematic investigation. The diagnosis hierarchy follows the data: confirm meter accuracy, check occupancy assumptions, use submetering to isolate the responsible system, then inspect physically. Running toilets (200+ gal/day) and irrigation leaks are the most common causes of large unexplained variances.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm WE đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; water efficiency: hiệu quả sử dụng nước; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Báo cáo variance để GBCI như certification misrepresentation issue","Sử dụng systematic submetering dữ liệu để isolate nguồn - leaks, occupancy, irrigation","WaterSense certification phải là invalid - replace tất cả fixtures immediately","Accept variance như normal operating fluctuation"],"evidence_en":"180% of design prediction is a significant variance requiring systematic investigation. The diagnosis hierarchy follows the data: confirm meter accuracy, check occupancy assumptions, use submetering to isolate the responsible system, then inspect physically. Running toilets (200+ gal/day) and irrigation leaks are the most common causes of large unexplained variances.","evidence_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Báo cáo variance để GBCI như certification misrepresentation issue” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Trong khi đó, câu hỏi đang kiểm tra đo đếm chỉ tạo giá trị khi dữ liệu được xem xét và dùng để phát hiện bất thường, ưu tiên cải tiến và xác minh tiết kiệm.","Sai. “Accept variance như normal operating fluctuation” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 583; Water Efficiency","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Report the variance to GBCI as a certification misrepresentation issue” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use systematic submetering data to isolate the source — leaks, occupancy, irrigation.”","Correct. This option directly satisfies the governing condition.","Incorrect. “The WaterSense certification must be invalid — replace all fixtures immediately” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use systematic submetering data to isolate the source — leaks, occupancy, irrigation.”","Incorrect. “Accept the variance as normal operating fluctuation” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use systematic submetering data to isolate the source — leaks, occupancy, irrigation.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"180% of design prediction is a significant variance requiring systematic investigation. The diagnosis hierarchy follows the data: confirm meter accuracy, check occupancy assumptions, use submetering to isolate the responsible system, then inspect physically. Running toilets (200+ gal/day) and irrigation leaks are the most common causes of large unexplained variances.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q083","core_concept_vi":"WaterSense xác nhận thiết bị và sản phẩm sử dụng nước đạt tiêu chí hiệu quả sử dụng nước; không đánh giá quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-584","source_index":584,"q":"The Bayview Financial Center team wants to provide only 200 parking spaces where zoning requires 450. The traffic engineer says this will cause shortages. The sustainability consultant disagrees. Who is correct, and what LEED credit is at stake?","options":["Both are wrong — LEED requires zero parking in downtown buildings","The consultant is correct — induced demand research supports reducing parking + TDM","The traffic engineer is correct — parking shortages harm building marketability","The decision should be based principally on local zoning requirements with no LEED consideration"],"answer":1,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; location and transportation: strategies that reduce travel impacts through site selection and mobility options; transportation demand management: programs that reduce single-occupancy vehicle travel and parking demand","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: The consultant is correct — induced demand research supports reducing parking + TDM.","logic":"Induced demand research is clear: in transit-rich urban areas, providing maximum parking induces maximum driving. Reducing supply, combined with quality alternatives (transit subsidies, car sharing, guaranteed ride home), shifts behavior. Tenants in downtown buildings with minimal parking and good TDM show significantly higher transit mode share.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm LT đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; location and transportation: vị trí và giao thông; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Cả hai là wrong - LEED yêu cầu zero bãi đỗ xe trong downtown công trình","Consultant là đúng - induced demand research supports giảm bãi đỗ xe + TDM","Traffic engineer là đúng - bãi đỗ xe shortages harm công trình marketability","Quyết định nên là based solely trên đị phương zoning yêu cầu với Không LEED consideration"],"evidence_en":"Induced demand research is clear: in transit-rich urban areas, providing maximum parking induces maximum driving. Reducing supply, combined with quality alternatives (transit subsidies, car sharing, guaranteed ride home), shifts behavior. Tenants in downtown buildings with minimal parking and good TDM show significantly higher transit mode share.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Trong khi đó, câu hỏi đang kiểm tra arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online.","Sai. “Quyết định nên là based solely trên đị phương zoning yêu cầu với Không LEED consideration” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 584; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Both are wrong — LEED requires zero parking in downtown buildings” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “The consultant is correct — induced demand research supports reducing parking + TDM.”","Correct. This option directly satisfies the governing condition.","Incorrect. “The traffic engineer is correct — parking shortages harm building marketability” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “The consultant is correct — induced demand research supports reducing parking + TDM.”","Incorrect. “The decision should be based solely on local zoning requirements with no LEED consideration” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “The consultant is correct — induced demand research supports reducing parking + TDM.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"Induced demand research is clear: in transit-rich urban areas, providing maximum parking induces maximum driving. Reducing supply, combined with quality alternatives (transit subsidies, car sharing, guaranteed ride home), shifts behavior. Tenants in downtown buildings with minimal parking and good TDM show significantly higher transit mode share.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q084","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-585","source_index":585,"q":"The Harbor View Apartments design team held a pre-design energy charette. The architect showed solar analysis revealing the south facade receives 6+ sun hours year-round. The civil engineer noted a shallow groundwater table. The mechanical engineer had originally proposed a gas-fired boiler. What integrative process outcome should the team pursue?","options":["Add solar panels to supplement the gas boiler for heating","Use GSHP powered by rooftop PV — eliminating gas while exploiting both site assets","Conduct separate engineering studies for each system and compare costs independently","Proceed with the original gas boiler proposal since it meets code minimums"],"answer":1,"category":"Integrative Process","source_domain":"Integrative Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the IP concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"integrative process: an early collaborative process used to identify system interactions and improve decisions; minimum: the lowest acceptable value or level; systems thinking: evaluation of interactions among building, site, water, energy, and occupant systems","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Use GSHP powered by rooftop PV — eliminating gas while exploiting both site assets.","logic":"This is the integrative process at its best: information from different disciplines (solar access from architecture, groundwater depth from civil, heating loads from mechanical) combines to reveal an optimal integrated strategy — GSHP at low drilling cost, powered by PV, eliminating carbon lock-in — that no single consultant would have identified working alone.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm IP đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng; verification: việc dùng dữ liệu hoặc hồ sơ để xác nhận yêu cầu đã được đáp ứng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Add mặt trời panels để supplement gas boiler cho heating","sử dụng GSHP powered bằng rooftop PV - eliminating gas trong khi exploiting cả hai khu đất assets","Conduct separate engineering studies cho mỗi hệ thống và compare costs independently","Proceed với original gas boiler proposal vì it meets code minimums"],"evidence_en":"This is the integrative process at its best: information from different disciplines (solar access from architecture, groundwater depth from civil, heating loads from mechanical) combines to reveal an optimal integrated strategy — GSHP at low drilling cost, powered by PV, eliminating carbon lock-in — that no single consultant would have identified working alone.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Add mặt trời panels để supplement gas boiler cho heating” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Conduct separate engineering studies cho mỗi hệ thống và compare costs independently” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Proceed với original gas boiler proposal vì it meets code minimums” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 585; Integrative Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Add solar panels to supplement the gas boiler for heating” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use GSHP powered by rooftop PV — eliminating gas while exploiting both site assets.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Conduct separate engineering studies for each system and compare costs independently” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use GSHP powered by rooftop PV — eliminating gas while exploiting both site assets.”","Incorrect. “Proceed with the original gas boiler proposal since it meets code minimums” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Use GSHP powered by rooftop PV — eliminating gas while exploiting both site assets.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Quy trình tích hợp - quy trình tích hợp","english_explanation_version":"v7.5.19-english-only","core_concept":"This is the integrative process at its best: information from different disciplines (solar access from architecture, groundwater depth from civil, heating loads from mechanical) combines to reveal an optimal integrated strategy — GSHP at low drilling cost, powered by PV, eliminating carbon lock-in — that no single consultant would have identified working alone.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q085","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-586","source_index":586,"q":"Parkside Office Building is evaluating three parking lot alternatives to the current dark asphalt (SRI ~5): (A) white concrete (SRI 86), (B) open-grid pavers with gravel, (C) shade trees covering 50% of the lot. All three can satisfy the Heat Island Reduction credit. Which provides the most overall value?","options":["primarily white concrete meets LEED standards — other options are not recognized","Trees provide the most co-benefits: stormwater, habitat, carbon, comfort beyond credit value","Choose the cheapest option since all three earn the same LEED credit points","Shade trees cannot substitute for high-SRI paving in the LEED calculation"],"answer":1,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"heat island: elevated temperatures caused by heat-absorbing built surfaces; credit: an optional LEED requirement that can earn points; sustainable sites: strategies that protect site ecology and manage construction and operational site impacts","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Trees provide the most co-benefits: stormwater, habitat, carbon, comfort beyond credit value.","logic":"Multi-benefit analysis is the correct LEED approach: all three options earn the Heat Island Reduction credit, but shade trees add habitat (Protect/Restore Habitat), open space, carbon sequestration, psychological benefits, and a cooler microclimate. The team should select based on the full value package relative to cost, not just which option is cheapest.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm SS đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; sustainable sites: khu đất bền vững; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Chỉ white concrete meets LEED standards - khác options là không recognized","Trees provide nhiều nhất co-benefits: stormwater, sinh cảnh, carbon, comfort beyond tín chỉ value","Choose cheapest phương án vì tất cả three nhận same LEED tín chỉ điểm","Shade trees cannot substitute cho high-SRI paving trong LEED calculation"],"evidence_en":"Multi-benefit analysis is the correct LEED approach: all three options earn the Heat Island Reduction credit, but shade trees add habitat (Protect/Restore Habitat), open space, carbon sequestration, psychological benefits, and a cooler microclimate. The team should select based on the full value package relative to cost, not just which option is cheapest.","evidence_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Chỉ white concrete meets LEED standards - khác options là không recognized” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Choose cheapest phương án vì tất cả three nhận same LEED tín chỉ điểm” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Shade trees cannot substitute cho high-SRI paving trong LEED calculation” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 586; Sustainable Sites","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Only white concrete meets LEED standards — other options are not recognized” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Trees provide the most co-benefits: stormwater, habitat, carbon, comfort beyond credit value.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Choose the cheapest option since all three earn the same LEED credit points” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Trees provide the most co-benefits: stormwater, habitat, carbon, comfort beyond credit value.”","Incorrect. “Shade trees cannot substitute for high-SRI paving in the LEED calculation” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Trees provide the most co-benefits: stormwater, habitat, carbon, comfort beyond credit value.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"Multi-benefit analysis is the correct LEED approach: all three options earn the Heat Island Reduction credit, but shade trees add habitat (Protect/Restore Habitat), open space, carbon sequestration, psychological benefits, and a cooler microclimate. The team should select based on the full value package relative to cost, not just which option is cheapest.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q086","core_concept_vi":"Giảm đảo nhiệt hạn chế hấp thụ và tái bức xạ nhiệt từ mái và bề mặt cứng bằng phản xạ cao, che bóng hoặc thảm thực vật. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-587","source_index":587,"q":"Horizon Community Center installed 25,000 sf of bamboo flooring. The salesperson claimed the bamboo is 'rapidly renewable,' 'carbon neutral,' and 'FSC certified.' The sustainability manager verifies the FSC certificate but discovers it covers only the bamboo fiber, not the formaldehyde-based binder used in the strand woven product. What are the LEED documentation issues?","options":["FSC certification covers all aspects of the bamboo product including binders and adhesives","Bamboo qualifies for sourcing, but the formaldehyde binder needs separate emissions testing","Bamboo products are by itself exempt from VOC emission testing requirements","Since the bamboo itself is FSC certified, all LEED documentation requirements are met"],"answer":1,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"NOT_EXCEPT","purpose":"Assess whether the learner can apply the MR concept and solve this exception question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"certification: third-party confirmation that a project satisfies applicable LEED requirements; documentation: records used to demonstrate compliance with a LEED requirement; materials and resources: strategies addressing life-cycle impacts, product selection, sourcing, and waste","keywords":"Identify the exception or the option that does not satisfy the common LEED condition; decisive option: Bamboo qualifies for sourcing, but the formaldehyde binder needs separate emissions testing.","logic":"'Sustainable material' claims require disaggregated evaluation. Bamboo fiber is FSC-certified and rapidly renewable (qualifying for those credits), but the strand-woven product's formaldehyde-based binder is a critical Low-Emitting Materials concern. The flooring system must be tested per CDPH 01350 and an HPD obtained for the complete product including binders.","purpose_vi":"Kiểm tra khả năng đọc đúng từ khóa phủ định và xác định phương án đi ngược mục tiêu kỹ thuật của yêu cầu, thay vì chọn một giải pháp phù hợp.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; materials and resources: vật liệu và tài nguyên; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đánh dấu từ phủ định trước khi xét phương án. Chọn giải pháp đi ngược cơ chế của credit; trong câu này dấu hiệu loại trừ dẫn đến “Bamboo qualifies cho nguồn cung, nhưng formaldehyde binder needs separate phát thải testing”.","logic_vi":"FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["FSC certification covers tất cả aspects của bamboo sản phẩm including binders và adhesives","Bamboo qualifies cho nguồn cung, nhưng formaldehyde binder needs separate phát thải testing","Bamboo sản phẩm là Tự động exempt từ VOC emission testing yêu cầu","Vì bamboo itself là FSC certified, tất cả LEED hồ sơ các yêu cầu là met"],"evidence_en":"'Sustainable material' claims require disaggregated evaluation. Bamboo fiber is FSC-certified and rapidly renewable (qualifying for those credits), but the strand-woven product's formaldehyde-based binder is a critical Low-Emitting Materials concern. The flooring system must be tested per CDPH 01350 and an HPD obtained for the complete product including binders.","evidence_vi":"FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Chức năng này không trùng với đối tượng và phạm vi mà câu hỏi yêu cầu.","Đúng. FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai nếu chọn. “Bamboo sản phẩm là Tự động exempt từ VOC emission testing yêu cầu” vẫn hỗ trợ mục tiêu được nêu; đây không phải phương án đi ngược yêu cầu mà từ khóa phủ định đang tìm.","Sai. FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Chức năng này không trùng với đối tượng và phạm vi mà câu hỏi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 587; Materials & Resources","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “FSC certification covers all aspects of the bamboo product including binders and adhesives” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Bamboo qualifies for sourcing, but the formaldehyde binder needs separate emissions testing.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Bamboo products are automatically exempt from VOC emission testing requirements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Bamboo qualifies for sourcing, but the formaldehyde binder needs separate emissions testing.”","Incorrect. “Since the bamboo itself is FSC certified, all LEED documentation requirements are met” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Bamboo qualifies for sourcing, but the formaldehyde binder needs separate emissions testing.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"'Sustainable material' claims require disaggregated evaluation. Bamboo fiber is FSC-certified and rapidly renewable (qualifying for those credits), but the strand-woven product's formaldehyde-based binder is a critical Low-Emitting Materials concern. The flooring system must be tested per CDPH 01350 and an HPD obtained for the complete product including binders.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q087","core_concept_vi":"FSC xác minh nguồn gỗ và chuỗi hành trình sản phẩm từ rừng được quản lý có trách nhiệm. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-588","source_index":588,"q":"Silverton Office Building (500 occupants) has specified: 0.5 GPM faucets (baseline 2.2 GPM), 1.1/1.6 GPF dual-flush toilets (baseline 1.6 GPF), and 0.5 GPF urinals (baseline 1.0 GPF). Which fixture type provides the GREATEST percentage reduction per use and which provides the SMALLEST?","options":["Faucets give the largest % per use (77%); dual-flush toilets the smallest (~19%)","Toilets as the default approach provide the greatest reduction because they are most frequently used","Toilets provide the greatest reduction; faucets provide the smallest","All fixture types provide equivalent percentage reductions"],"answer":0,"category":"Water Efficiency","source_domain":"Water Efficiency","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the WE concept and solve this threshold question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"baseline: the reference case against which project performance is compared; water efficiency: reduction and responsible management of indoor, outdoor, and process water use; water performance: measured water consumption and the effectiveness of water-saving strategies","keywords":"Identify the exact minimum, maximum, or numerical threshold requested; decisive value or condition: Faucets give the largest % per use (77%); dual-flush toilets the smallest (~19%).","logic":"Percentage reduction and total volume saved are different metrics: faucets have the largest percentage reduction per use (0.5/2.2 = 77%) but toilets are the largest total water consumers due to frequency. Urinals provide moderate reduction (50%). LEED calculates based on total annual consumption, not just per-use efficiency.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc WE vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"baseline: đường cơ sở dùng làm mốc so sánh hiệu suất; water efficiency: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; water performance: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Faucets give largest % per sử dụng (77%); dual-flush toilets smallest (~19%)” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị. Trong bối cảnh câu hỏi, “Faucets give largest % per sử dụng (77%); dual-flush toilets smallest (~19%)” áp dụng đúng nguyên tắc này; vì vậy phương án A đúng.","options_vi":["Faucets give largest % per sử dụng (77%); dual-flush toilets smallest (~19%)","Toilets Luôn luôn provide greatest mức giảm vì they là nhiều nhất frequently used","Toilets provide greatest mức giảm; faucets provide smallest","Tất cả fixture types provide tương đương percentage reductions"],"evidence_en":"Percentage reduction and total volume saved are different metrics: faucets have the largest percentage reduction per use (0.5/2.2 = 77%) but toilets are the largest total water consumers due to frequency. Urinals provide moderate reduction (50%). LEED calculates based on total annual consumption, not just per-use efficiency.","evidence_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","mechanism_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","wrong_reasons_vi":["Đúng. Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","Sai. “Toilets Luôn luôn provide greatest mức giảm vì they là nhiều nhất frequently used” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Toilets provide greatest mức giảm; faucets provide smallest” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Tất cả fixture types provide tương đương percentage reductions” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 588; Water Efficiency","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “Toilets always provide the greatest reduction because they are most frequently used” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Faucets give the largest % per use (77%); dual-flush toilets the smallest (~19%).”","Incorrect. “Toilets provide the greatest reduction; faucets provide the smallest” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Faucets give the largest % per use (77%); dual-flush toilets the smallest (~19%).”","Incorrect. “All fixture types provide equivalent percentage reductions” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Faucets give the largest % per use (77%); dual-flush toilets the smallest (~19%).”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Hiệu quả sử dụng nước - nước hiệu suất","english_explanation_version":"v7.5.19-english-only","core_concept":"Percentage reduction and total volume saved are different metrics: faucets have the largest percentage reduction per use (0.5/2.2 = 77%) but toilets are the largest total water consumers due to frequency. Urinals provide moderate reduction (50%). LEED calculates based on total annual consumption, not just per-use efficiency.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q088","core_concept_vi":"Giảm nước trong nhà dựa trên lưu lượng hoặc lượng xả của thiết bị so với đường cơ sở và mô hình sử dụng. WaterSense hỗ trợ nhận diện sản phẩm hiệu quả nhưng phải áp dụng đúng loại thiết bị.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-589","source_index":589,"q":"Azure Technology Park project team has 4 weeks until construction review submission. They are at 57 points (Silver) and want to reach 60 for Gold. They identify: (A) LEED AP already on the team — 1 Innovation point not yet claimed; (B) C&D waste diversion currently at 82% — could be documented as Exemplary Performance if it reaches 90%+; (C) an earned RP credit designation for Outdoor Water Use Reduction (100% reduction earned). Current accounting: how many points are immediately available without any additional construction activity?","options":["All three strategies require GBCI special approval before they can be claimed","LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate points = 59; need 1 more for Gold","None — all strategies require new construction activities to implement","They cannot reach Gold since construction is nearly complete"],"answer":1,"category":"Innovation & Regional Priority","source_domain":"Innovation & Regional Priority","question_style":"NOT_EXCEPT","purpose":"Assess whether the learner can apply the PR concept and solve this exception question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"outdoor water use reduction: reduction of potable water used for landscape irrigation; waste diversion: keeping waste out of landfill or incineration through reuse, recycling, or recovery; exemplary performance: performance that substantially exceeds an existing LEED credit threshold; innovation: a strategy with significant benefit not adequately addressed by existing LEED credits; credit: an optional LEED requirement that can earn points","keywords":"Identify the exception or the option that does not satisfy the common LEED condition; decisive option: LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate points = 59; need 1 more for Gold.","logic":"The LEED AP point and RP bonus point are immediately claimable with no additional construction activity — they simply weren't documented. Together they bring the score from 57 to 59. C&D waste at 82% is below Exemplary threshold (~95%) and would require operational improvement during the remaining 4 weeks. With targeted waste optimization, reaching 95% and the final Gold point is achievable.","purpose_vi":"Kiểm tra khả năng nhận diện từ khóa phủ định và loại phương án đi ngược nguyên tắc kỹ thuật của nhóm PR.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; outdoor water use reduction: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; waste diversion: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; exemplary performance: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đọc từ khóa phủ định trước khi xét nội dung. Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate điểm = 59; need 1 nhiều hơn cho Gold” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới. Trong bối cảnh câu hỏi, “LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate điểm = 59; need 1 nhiều hơn cho Gold” áp dụng đúng nguyên tắc này; vì vậy phương án B đúng.","options_vi":["Tất cả three giải pháp yêu cầu GBCI special phê duyệt trước khi they có thể là claimed","LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate điểm = 59; need 1 nhiều hơn cho Gold","None - tất cả giải pháp yêu cầu mới thi công activities để Triển khai","They cannot reach Gold vì thi công là nearly complete"],"evidence_en":"The LEED AP point and RP bonus point are immediately claimable with no additional construction activity — they simply weren't documented. Together they bring the score from 57 to 59. C&D waste at 82% is below Exemplary threshold (~95%) and would require operational improvement during the remaining 4 weeks. With targeted waste optimization, reaching 95% and the final Gold point is achievable.","evidence_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","mechanism_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","wrong_reasons_vi":["Sai nếu chọn. “Tất cả three giải pháp yêu cầu GBCI special phê duyệt trước khi they có thể là claimed” vẫn phù hợp hoặc hỗ trợ mục tiêu của yêu cầu; đề bài đang tìm phương án ngoại lệ hoặc ít phù hợp nhất.","Đúng. Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","Sai nếu chọn. “None - tất cả giải pháp yêu cầu mới thi công activities để Triển khai” vẫn phù hợp hoặc hỗ trợ mục tiêu của yêu cầu; đề bài đang tìm phương án ngoại lệ hoặc ít phù hợp nhất.","Sai nếu chọn. “They cannot reach Gold vì thi công là nearly complete” vẫn phù hợp hoặc hỗ trợ mục tiêu của yêu cầu; đề bài đang tìm phương án ngoại lệ hoặc ít phù hợp nhất."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 589; Innovation & Regional Priority","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “All three strategies require GBCI special approval before they can be claimed” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate points = 59; need 1 more for Gold.”","Correct. This option directly satisfies the governing condition.","Incorrect. “None — all strategies require new construction activities to implement” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate points = 59; need 1 more for Gold.”","Incorrect. “They cannot reach Gold since construction is nearly complete” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “LEED AP (1 pt) + RP bonus (1 pt) = 2 immediate points = 59; need 1 more for Gold.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Ưu tiên khu vực - Innovation & Regional Priority","english_explanation_version":"v7.5.19-english-only","core_concept":"The LEED AP point and RP bonus point are immediately claimable with no additional construction activity — they simply weren't documented. Together they bring the score from 57 to 59. C&D waste at 82% is below Exemplary threshold (~95%) and would require operational improvement during the remaining 4 weeks. With targeted waste optimization, reaching 95% and the final Gold point is achievable.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q089","core_concept_vi":"Innovation có thể ghi nhận chiến lược đổi mới, pilot credit hoặc exemplary performance khi đáp ứng đường dẫn áp dụng. LEED AP là một đường dẫn riêng, không thay thế bằng việc tự tuyên bố đổi mới.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-590","source_index":590,"q":"Harborview Hotel chain operates 45 hotels across North America. Their sustainability director wants a standardized energy strategy maximizing LEED performance across the portfolio. Which three strategies provide the most universal impact?","options":["The answer depends entirely on each hotel's location and cannot be generalized","primarily renewable energy installations provide universal LEED benefit across a hotel portfolio","Hotels cannot earn any EA credits because of their unique energy profile","Guestroom controls, LED + controls, and exhaust heat recovery — universally high-impact"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"renewable energy: energy from sources that are naturally replenished; credit: an optional LEED requirement that can earn points; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Guestroom controls, LED + controls, and exhaust heat recovery — universally high-impact.","logic":"Portfolio standardization works best when strategies are both high-impact and universally applicable. Guestroom occupancy controls (25–40% energy reduction in unoccupied rooms) directly address hotels' unique challenge. LED + controls (50–60% lighting energy reduction) and heat recovery from exhaust or laundry (free hot water preheat) apply to all 45 properties.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EA vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"renewable energy: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; credit: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy and atmosphere: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Guestroom điều khiển, LED + điều khiển, và exhaust nhiệt recovery - universally high-tác động” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích. Trong bối cảnh câu hỏi, “Guestroom điều khiển, LED + điều khiển, và exhaust nhiệt recovery - universally high-tác động” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Đáp án depends entirely trên mỗi hotel's vị trí và cannot là generalized","Chỉ năng lượng tái tạo installations provide universal LEED benefit across một hotel portfolio","Hotels cannot nhận bất kỳ EA tín chỉ vì của their unique năng lượng profile","Guestroom điều khiển, LED + điều khiển, và exhaust nhiệt recovery - universally high-tác động"],"evidence_en":"Portfolio standardization works best when strategies are both high-impact and universally applicable. Guestroom occupancy controls (25–40% energy reduction in unoccupied rooms) directly address hotels' unique challenge. LED + controls (50–60% lighting energy reduction) and heat recovery from exhaust or laundry (free hot water preheat) apply to all 45 properties.","evidence_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","mechanism_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","wrong_reasons_vi":["Sai. “Đáp án depends entirely trên mỗi hotel's vị trí và cannot là generalized” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Chỉ năng lượng tái tạo installations provide universal LEED benefit across một hotel portfolio” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Hotels cannot nhận bất kỳ EA tín chỉ vì của their unique năng lượng profile” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 590; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “The answer depends entirely on each hotel's location and cannot be generalized” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Guestroom controls, LED + controls, and exhaust heat recovery — universally high-impact.”","Incorrect. “Only renewable energy installations provide universal LEED benefit across a hotel portfolio” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Guestroom controls, LED + controls, and exhaust heat recovery — universally high-impact.”","Incorrect. “Hotels cannot earn any EA credits because of their unique energy profile” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Guestroom controls, LED + controls, and exhaust heat recovery — universally high-impact.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"Portfolio standardization works best when strategies are both high-impact and universally applicable. Guestroom occupancy controls (25–40% energy reduction in unoccupied rooms) directly address hotels' unique challenge. LED + controls (50–60% lighting energy reduction) and heat recovery from exhaust or laundry (free hot water preheat) apply to all 45 properties.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q090","core_concept_vi":"Giá trị môi trường của điện tái tạo phụ thuộc quyền sở hữu và hủy thuộc tính môi trường. Nếu thuộc tính đã bán hoặc bị bên khác yêu cầu, dự án không được tính trùng lợi ích.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-591","source_index":591,"q":"The Sycamore Research Park is a remote campus for 500 employees accessible only by car. The marketing team wants to claim LEED 'transportation sustainability.' What is the most honest characterization of this project's LT credit potential?","options":["Honestly: low transit-dependent points but achievable EV, Reduced Parking, and Bike credits","Remote campuses should not pursue LEED since LT credits are impossible","Remote campuses can claim full LT credit parity with urban buildings","The project can claim transit sustainability through corporate shuttle programs even without nearby public transit"],"answer":0,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"public transit: shared passenger transportation available to the public; credit: an optional LEED requirement that can earn points; location and transportation: strategies that reduce travel impacts through site selection and mobility options","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Honestly: low transit-dependent points but achievable EV, Reduced Parking, and Bike credits.","logic":"Honest LEED strategy for remote campuses means accepting low transit-dependent LT scores while maximizing what's achievable: Electric Vehicles credit (EV charging and preferred parking for EVs/carpools), Reduced Parking Footprint with TDM, Bicycle Facilities for on-campus use. Overpromising 'transportation sustainability' for a car-dependent campus misleads stakeholders.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm LT đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; location and transportation: vị trí và giao thông; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Honestly: thấp transit-dependent điểm nhưng achievable EV, Reduced bãi đỗ xe, và Bike tín chỉ","Remote campuses nên không pursue LEED vì LT tín chỉ là impossible","Remote campuses có thể claim full LT tín chỉ parity với urban công trình","Dự án có thể claim transit sustainability thông qua corporate shuttle programs kể cả không có nearby công khai transit"],"evidence_en":"Honest LEED strategy for remote campuses means accepting low transit-dependent LT scores while maximizing what's achievable: Electric Vehicles credit (EV charging and preferred parking for EVs/carpools), Reduced Parking Footprint with TDM, Bicycle Facilities for on-campus use. Overpromising 'transportation sustainability' for a car-dependent campus misleads stakeholders.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “Remote campuses nên không pursue LEED vì LT tín chỉ là impossible” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Remote campuses có thể claim full LT tín chỉ parity với urban công trình” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Dự án có thể claim transit sustainability thông qua corporate shuttle programs kể cả không có nearby công khai transit” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 591; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “Remote campuses should not pursue LEED since LT credits are impossible” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Honestly: low transit-dependent points but achievable EV, Reduced Parking, and Bike credits.”","Incorrect. “Remote campuses can claim full LT credit parity with urban buildings” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Honestly: low transit-dependent points but achievable EV, Reduced Parking, and Bike credits.”","Incorrect. “The project can claim transit sustainability through corporate shuttle programs even without nearby public transit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Honestly: low transit-dependent points but achievable EV, Reduced Parking, and Bike credits.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"Honest LEED strategy for remote campuses means accepting low transit-dependent LT scores while maximizing what's achievable: Electric Vehicles credit (EV charging and preferred parking for EVs/carpools), Reduced Parking Footprint with TDM, Bicycle Facilities for on-campus use. Overpromising 'transportation sustainability' for a car-dependent campus misleads stakeholders.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q091","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-592","source_index":592,"q":"Two office buildings are built simultaneously: Building A is net-zero energy in a suburban office park requiring all 500 employees to drive. Building B is standard-efficiency in a transit-rich walkable downtown. Which has the lower total carbon footprint including occupant transportation?","options":["Building A definitely has lower total carbon because it is net-zero energy","Building B likely lower — 500 employees driving may exceed Building A's energy savings","Building A definitely has lower carbon — energy use is the primarily factor that matters","It is impossible to make any comparison between these two buildings"],"answer":1,"category":"Location & Transportation","source_domain":"Location & Transportation","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the LT concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"location and transportation: strategies that reduce travel impacts through site selection and mobility options; transportation demand management: programs that reduce single-occupancy vehicle travel and parking demand","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Building B likely lower — 500 employees driving may exceed Building A's energy savings.","logic":"This illustrates one of LEED V5's most important conceptual advances: transportation emissions are often comparable to or larger than operational building emissions. A net-zero building in a car-dependent location may have higher TOTAL lifecycle carbon than a standard-efficiency building in a transit-rich location. Comprehensive carbon accounting must include Scope 3 transportation.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc LT vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"location and transportation: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; transportation demand management: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; evidence: dữ liệu hoặc hồ sơ dùng để chứng minh tuân thủ","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Công trình B likely thấp hơn - 500 employees driving có thể exceed công trình A's năng lượng savings” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu. Trong bối cảnh câu hỏi, “Công trình B likely thấp hơn - 500 employees driving có thể exceed công trình A's năng lượng savings” áp dụng đúng nguyên tắc này; vì vậy phương án B đúng.","options_vi":["Công trình một definitely có thấp hơn tổng carbon vì it là net-zero năng lượng","Công trình B likely thấp hơn - 500 employees driving có thể exceed công trình A's năng lượng savings","Công trình definitely có thấp hơn carbon - mức sử dụng năng lượng là chỉ factor đó matters","It là impossible để make bất kỳ comparison trong khoảng các two các công trình"],"evidence_en":"This illustrates one of LEED V5's most important conceptual advances: transportation emissions are often comparable to or larger than operational building emissions. A net-zero building in a car-dependent location may have higher TOTAL lifecycle carbon than a standard-efficiency building in a transit-rich location. Comprehensive carbon accounting must include Scope 3 transportation.","evidence_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","mechanism_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","wrong_reasons_vi":["Sai. “Công trình một definitely có thấp hơn tổng carbon vì it là net-zero năng lượng” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","Sai. “Công trình definitely có thấp hơn carbon - mức sử dụng năng lượng là chỉ factor đó matters” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “It là impossible để make bất kỳ comparison trong khoảng các two các công trình” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 592; Location & Transportation","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Building A definitely has lower total carbon because it is net-zero energy” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Building B likely lower — 500 employees driving may exceed Building A's energy savings.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Building A definitely has lower carbon — energy use is the only factor that matters” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Building B likely lower — 500 employees driving may exceed Building A's energy savings.”","Incorrect. “It is impossible to make any comparison between these two buildings” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Building B likely lower — 500 employees driving may exceed Building A's energy savings.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vị trí và giao thông - Location & Transportation","english_explanation_version":"v7.5.19-english-only","core_concept":"This illustrates one of LEED V5's most important conceptual advances: transportation emissions are often comparable to or larger than operational building emissions. A net-zero building in a car-dependent location may have higher TOTAL lifecycle carbon than a standard-efficiency building in a transit-rich location. Comprehensive carbon accounting must include Scope 3 transportation.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q092","core_concept_vi":"Chiến lược giao thông bền vững phải làm giảm nhu cầu lái xe một người, quãng đường xe chạy hoặc phát thải chuyến đi bằng vị trí, giao thông công cộng, đi bộ, xe đạp hoặc quản lý nhu cầu.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-593","source_index":593,"q":"Apex Corporate Center (500,000 sf, Climate Zone 4A) is evaluating three HVAC options: (A) gas boiler + electric chiller, (B) all-electric air-source heat pump + chiller, (C) ground-source heat pump with borehole field. The owner wants a 20-year life cycle cost analysis including carbon pricing at $100/tonne. Which option likely wins?","options":["Option A as the default approach wins on cost because gas is cheaper than electricity","Carbon pricing has no effect on HVAC system selection","Option B is as the default approach the best choice in all climate zones regardless of carbon pricing","Option C (GSHP) — eliminates gas combustion and avoids $50–80K/year in carbon costs"],"answer":3,"category":"Energy & Atmosphere","source_domain":"Energy & Atmosphere","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EA concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"best: a word asking for the strongest or most effective option; energy and atmosphere: strategies addressing energy demand, efficiency, refrigerants, and renewable energy; energy efficiency: delivery of the required service with less energy use","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Option C (GSHP) — eliminates gas combustion and avoids $50–80K/year in carbon costs.","logic":"At $100/tonne carbon pricing, continuous on-site gas combustion becomes increasingly costly over 20 years. GSHP's superior COP reduces total energy consumption by 30–50% vs. Option A and completely eliminates direct gas combustion carbon costs. The 20-year LCC typically shows GSHP's higher initial cost is recovered within 8–12 years through lower energy and carbon costs.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc EA vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"best: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy and atmosphere: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; energy efficiency: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Phương án C (GSHP) - eliminates gas combustion và avoids $50-80K/year trong carbon costs” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Điện hóa thay thiết bị đốt nhiên liệu tại chỗ bằng hệ thống điện hiệu suất cao như heat pump. Giải pháp giảm phát thải trực tiếp và có lợi hơn khi lưới điện tiếp tục giảm carbon. Trong bối cảnh câu hỏi, “Phương án C (GSHP) - eliminates gas combustion và avoids $50-80K/year trong carbon costs” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Phương án Luôn luôn wins trên chi phí vì gas là cheaper hơn điện","Carbon pricing có Không effect về HVAC hệ thống selection","Phương án B là Luôn luôn tốt nhất choice trong tất cả climate zones regardless của carbon pricing","Phương án C (GSHP) - eliminates gas combustion và avoids $50-80K/year trong carbon costs"],"evidence_en":"At $100/tonne carbon pricing, continuous on-site gas combustion becomes increasingly costly over 20 years. GSHP's superior COP reduces total energy consumption by 30–50% vs. Option A and completely eliminates direct gas combustion carbon costs. The 20-year LCC typically shows GSHP's higher initial cost is recovered within 8–12 years through lower energy and carbon costs.","evidence_vi":"Điện hóa thay thiết bị đốt nhiên liệu tại chỗ bằng hệ thống điện hiệu suất cao như heat pump. Giải pháp giảm phát thải trực tiếp và có lợi hơn khi lưới điện tiếp tục giảm carbon.","mechanism_vi":"Điện hóa thay thiết bị đốt nhiên liệu tại chỗ bằng hệ thống điện hiệu suất cao như heat pump. Giải pháp giảm phát thải trực tiếp và có lợi hơn khi lưới điện tiếp tục giảm carbon.","wrong_reasons_vi":["Sai. “Phương án Luôn luôn wins trên chi phí vì gas là cheaper hơn điện” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Carbon pricing có Không effect về HVAC hệ thống selection” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Phương án B là Luôn luôn tốt nhất choice trong tất cả climate zones regardless của carbon pricing” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Điện hóa thay thiết bị đốt nhiên liệu tại chỗ bằng hệ thống điện hiệu suất cao như heat pump. Giải pháp giảm phát thải trực tiếp và có lợi hơn khi lưới điện tiếp tục giảm carbon."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 593; Energy & Atmosphere","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Option A always wins on cost because gas is cheaper than electricity” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Option C (GSHP) — eliminates gas combustion and avoids $50–80K/year in carbon costs.”","Incorrect. “Carbon pricing has no effect on HVAC system selection” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Option C (GSHP) — eliminates gas combustion and avoids $50–80K/year in carbon costs.”","Incorrect. “Option B is always the best choice in all climate zones regardless of carbon pricing” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Option C (GSHP) — eliminates gas combustion and avoids $50–80K/year in carbon costs.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Năng lượng và khí quyển - năng lượng & Atmosphere","english_explanation_version":"v7.5.19-english-only","core_concept":"At $100/tonne carbon pricing, continuous on-site gas combustion becomes increasingly costly over 20 years. GSHP's superior COP reduces total energy consumption by 30–50% vs. Option A and completely eliminates direct gas combustion carbon costs. The 20-year LCC typically shows GSHP's higher initial cost is recovered within 8–12 years through lower energy and carbon costs.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q093","core_concept_vi":"Điện hóa thay thiết bị đốt nhiên liệu tại chỗ bằng hệ thống điện hiệu suất cao như heat pump. Giải pháp giảm phát thải trực tiếp và có lợi hơn khi lưới điện tiếp tục giảm carbon.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-594","source_index":594,"q":"Lakewood Office Center wants to compare embodied carbon of structural options using EC3. They have EPDs for concrete mixes from 3 regional suppliers (all using ASTM PCR-0007), structural steel from 2 manufacturers (different PCR), and mass timber CLT (yet another PCR). The architect asks: 'How can we trust these comparisons when EPDs use different methodologies?' What is the correct guidance?","options":["EPD comparisons are is generally not reliable since all methodologies are different","All EPDs use identical methodologies so no adjustment is needed for comparison","Mass timber cannot be compared to concrete or steel since it stores carbon","Compare same PCRs within categories; normalize across systems by GWP per m² of floor area"],"answer":3,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the MR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"embodied carbon: greenhouse gas emissions associated with materials and construction; EPD: an Environmental Product Declaration reporting verified life-cycle impacts; materials and resources: strategies addressing life-cycle impacts, product selection, sourcing, and waste","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Compare same PCRs within categories; normalize across systems by GWP per m² of floor area.","logic":"Valid embodied carbon comparisons require same PCR within product categories, and building-level normalization across different structural systems. One cannot compare steel kg CO₂e/kg to concrete kg CO₂e/kg without accounting for very different densities and quantities needed for equivalent structural performance. EC3's building-level comparison correctly accounts for these differences.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm MR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"embodied carbon: carbon hàm chứa; materials and resources: vật liệu và tài nguyên; key condition: điều kiện quyết định dùng để loại các phương án gần đúng","keywords_vi":"Tập trung vào “embodied carbon”. Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["EPD comparisons là Không bao giờ reliable vì tất cả methodologies là different","Tất cả EPDs sử dụng identical methodologies so Không adjustment là needed cho comparison","Mass timber cannot là compared để concrete hoặc steel vì it stores carbon","Compare same PCRs within categories; normalize across hệ thống bằng GWP per m² của floor khu vực"],"evidence_en":"Valid embodied carbon comparisons require same PCR within product categories, and building-level normalization across different structural systems. One cannot compare steel kg CO₂e/kg to concrete kg CO₂e/kg without accounting for very different densities and quantities needed for equivalent structural performance. EC3's building-level comparison correctly accounts for these differences.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. “EPD comparisons là Không bao giờ reliable vì tất cả methodologies là different” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Tất cả EPDs sử dụng identical methodologies so Không adjustment là needed cho comparison” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Mass timber cannot là compared để concrete hoặc steel vì it stores carbon” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 594; Materials & Resources","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “EPD comparisons are never reliable since all methodologies are different” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Compare same PCRs within categories; normalize across systems by GWP per m² of floor area.”","Incorrect. “All EPDs use identical methodologies so no adjustment is needed for comparison” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Compare same PCRs within categories; normalize across systems by GWP per m² of floor area.”","Incorrect. “Mass timber cannot be compared to concrete or steel since it stores carbon” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Compare same PCRs within categories; normalize across systems by GWP per m² of floor area.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Valid embodied carbon comparisons require same PCR within product categories, and building-level normalization across different structural systems. One cannot compare steel kg CO₂e/kg to concrete kg CO₂e/kg without accounting for very different densities and quantities needed for equivalent structural performance. EC3's building-level comparison correctly accounts for these differences.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q094","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-595","source_index":595,"q":"The Greenway Transit Hub is above a light rail station with zero ground-level open space — the entire 1-acre site footprint is building and infrastructure. The LEED team argues that the rail station's public plaza (outside their project boundary) should earn them the Open Space credit. Is this valid, and how can they actually earn the credit?","options":["Dense urban sites above transit stations are permanently exempt from Open Space requirements","The transit connection by itself earns the Open Space credit","The team must acquire adjacent land to provide qualifying open space","No — but the team can earn it via an accessible vegetated rooftop terrace"],"answer":3,"category":"Sustainable Sites","source_domain":"Sustainable Sites","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the SS concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; sustainable sites: strategies that protect site ecology and manage construction and operational site impacts; site disturbance: physical alteration of soil, vegetation, or existing site conditions","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: No — but the team can earn it via an accessible vegetated rooftop terrace.","logic":"LEED credits must be earned within the project boundary — features outside (like the rail station plaza) cannot earn credits for the project. The solution for 100% hardscape sites is the green rooftop terrace option: LEED explicitly accommodates dense urban sites by allowing rooftop open space to substitute for ground-level open space.","purpose_vi":"Kiểm tra khả năng áp dụng nguyên tắc SS vào tình huống cụ thể và phân biệt các lựa chọn theo cơ chế tác động thực tế.","vocabulary_vi":"credit: yêu cầu tự chọn có thể mang lại điểm; sustainable sites: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi; site disturbance: thuật ngữ cần đọc theo đúng phạm vi kỹ thuật của câu hỏi","keywords_vi":"Đối chiếu động từ của câu hỏi với cơ chế kỹ thuật: “Không - nhưng nhóm có thể nhận it via accessible vegetated rooftop terrace” phù hợp khi áp dụng nguyên tắc nêu trong phần logic, còn các phương án khác giải quyết sai nguồn, sai thời điểm hoặc sai phạm vi.","logic_vi":"Minimum Program Requirements xác định điều kiện nền tảng để dự án đủ tư cách áp dụng LEED, như ranh giới hợp lý, tính lâu dài và quy mô tối thiểu theo hệ thống. Trong bối cảnh câu hỏi, “Không - nhưng nhóm có thể nhận it via accessible vegetated rooftop terrace” áp dụng đúng nguyên tắc này; vì vậy phương án D đúng.","options_vi":["Dense urban sites above transit stations là permanently exempt từ Open Space các yêu cầu","Transit connection Tự động đạt được Open Space tín chỉ","Nhóm phải acquire adjacent land để provide qualifying open space","Không - nhưng nhóm có thể nhận it via accessible vegetated rooftop terrace"],"evidence_en":"LEED credits must be earned within the project boundary — features outside (like the rail station plaza) cannot earn credits for the project. The solution for 100% hardscape sites is the green rooftop terrace option: LEED explicitly accommodates dense urban sites by allowing rooftop open space to substitute for ground-level open space.","evidence_vi":"Minimum Program Requirements xác định điều kiện nền tảng để dự án đủ tư cách áp dụng LEED, như ranh giới hợp lý, tính lâu dài và quy mô tối thiểu theo hệ thống.","mechanism_vi":"Minimum Program Requirements xác định điều kiện nền tảng để dự án đủ tư cách áp dụng LEED, như ranh giới hợp lý, tính lâu dài và quy mô tối thiểu theo hệ thống.","wrong_reasons_vi":["Sai. “Dense urban sites above transit stations là permanently exempt từ Open Space các yêu cầu” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Transit connection Tự động đạt được Open Space tín chỉ” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Sai. “Nhóm phải acquire adjacent land để provide qualifying open space” không xử lý đúng nguồn tác động, thời điểm hoặc đối tượng được nêu; vì thế không tạo ra kết quả mà nguyên tắc cốt lõi yêu cầu.","Đúng. Minimum Program Requirements xác định điều kiện nền tảng để dự án đủ tư cách áp dụng LEED, như ranh giới hợp lý, tính lâu dài và quy mô tối thiểu theo hệ thống."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 595; Sustainable Sites","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9.1-semantic-reviewed","wrong_reasons_en":["Incorrect. “Dense urban sites above transit stations are permanently exempt from Open Space requirements” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “No — but the team can earn it via an accessible vegetated rooftop terrace.”","Incorrect. “The transit connection automatically earns the Open Space credit” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “No — but the team can earn it via an accessible vegetated rooftop terrace.”","Incorrect. “The team must acquire adjacent land to provide qualifying open space” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “No — but the team can earn it via an accessible vegetated rooftop terrace.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Khu đất bền vững - Sustainable Sites","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED credits must be earned within the project boundary — features outside (like the rail station plaza) cannot earn credits for the project. The solution for 100% hardscape sites is the green rooftop terrace option: LEED explicitly accommodates dense urban sites by allowing rooftop open space to substitute for ground-level open space.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q095","core_concept_vi":"Minimum Program Requirements xác định điều kiện nền tảng để dự án đủ tư cách áp dụng LEED, như ranh giới hợp lý, tính lâu dài và quy mô tối thiểu theo hệ thống.","vi_alignment_source":"question|correct_answer|core_concept|theme_rule|option_role","semantic_review_status":"SEMANTIC_REVIEW_COMPLETED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-596","source_index":596,"q":"Clearwater Office Tower claims views to the outdoors for 85% of regularly occupied floor area. During the certification review, the reviewer questions whether views to the adjacent parking garage qualify as 'quality views.' The team argues that any view to the outdoors qualifies. Is the reviewer's concern valid?","options":["Any view to the outdoors qualifies for the Quality Views credit under all LEED versions","Reviewer is right — Quality Views needs nature, sky, distance, or human activity","Views to parking structures as the default approach qualify since parking garages are human-built environments","The reviewer has no authority to question view quality — any window qualifies"],"answer":1,"category":"Indoor Environmental Quality","source_domain":"Indoor Environmental Quality","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the EQ concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"credit: an optional LEED requirement that can earn points; certification: third-party confirmation that a project satisfies applicable LEED requirements; indoor environmental quality: conditions affecting indoor air, thermal comfort, lighting, acoustics, and occupants","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Reviewer is right — Quality Views needs nature, sky, distance, or human activity.","logic":"Quality Views is not just about transparency — it's about the quality of the connection to the outdoor environment. The credit typically requires views to contain at least two of three elements: flora/fauna/sky; human activity; objects more than 25 feet away. A view directly into a concrete parking garage facade with none of these may not qualify even though it is technically 'outdoors.'","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm EQ đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; indoor environmental quality: chất lượng môi trường trong nhà","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["Bất kỳ view để outdoors qualifies cho chất lượng Views tín chỉ theo tất cả LEED versions","Reviewer là right - chất lượng Views needs nature, sky, distance, hoặc human activity","Views để bãi đỗ xe structures Luôn luôn qualify vì bãi đỗ xe garages là human-built environments","Reviewer có Không authority để question view chất lượng - bất kỳ window qualifies"],"evidence_en":"Quality Views is not just about transparency — it's about the quality of the connection to the outdoor environment. The credit typically requires views to contain at least two of three elements: flora/fauna/sky; human activity; objects more than 25 feet away. A view directly into a concrete parking garage facade with none of these may not qualify even though it is technically 'outdoors.'","evidence_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “Bất kỳ view để outdoors qualifies cho chất lượng Views tín chỉ theo tất cả LEED versions” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Chức năng này không trùng với đối tượng và phạm vi mà câu hỏi yêu cầu.","Sai. “Reviewer có Không authority để question view chất lượng - bất kỳ window qualifies” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 596; Indoor Environmental Quality","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Any view to the outdoors qualifies for the Quality Views credit under all LEED versions” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Reviewer is right — Quality Views needs nature, sky, distance, or human activity.”","Correct. This option directly satisfies the governing condition.","Incorrect. “Views to parking structures always qualify since parking garages are human-built environments” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Reviewer is right — Quality Views needs nature, sky, distance, or human activity.”","Incorrect. “The reviewer has no authority to question view quality — any window qualifies” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Reviewer is right — Quality Views needs nature, sky, distance, or human activity.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Chất lượng môi trường trong nhà - Indoor Environmental chất lượng","english_explanation_version":"v7.5.19-english-only","core_concept":"Quality Views is not just about transparency — it's about the quality of the connection to the outdoor environment. The credit typically requires views to contain at least two of three elements: flora/fauna/sky; human activity; objects more than 25 feet away. A view directly into a concrete parking garage facade with none of these may not qualify even though it is technically 'outdoors.'.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q096","core_concept_vi":"Giảm nguồn cung và quản lý nhu cầu đỗ xe làm giảm động lực sử dụng xe cá nhân một người. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-597","source_index":597,"q":"The Emerald Hill Hospital procurement team has collected product documentation: Product A — HPD listing phthalates (REACH SVHC), Declare label denied; Product B — HPD with no Red List chemicals, Declare label certified, product-specific EPD (GWP 45 kg CO₂e/m²); Product C — no HPD or EPD available, manufacturer says 'all natural materials'; Product D — industry-wide EPD (GWP 62 kg CO₂e/m²), no HPD. Which product is most strongly aligned with LEED V5 Material Ingredients optimization?","options":["Product D is preferred because it has the most detailed EPD documentation","Product A is acceptable since phthalates are primarily an issue in children's spaces","Product C — 'all natural materials' is as the default approach the LEED-preferred choice","Product B — HPD without Red List, Declare label, AND lower-GWP EPD"],"answer":3,"category":"Materials & Resources","source_domain":"Materials & Resources","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the MR concept and solve this documentation question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"documentation: records used to demonstrate compliance with a LEED requirement; EPD: an Environmental Product Declaration reporting verified life-cycle impacts; HPD: a Health Product Declaration reporting product ingredients and health information","keywords":"Distinguish the technical requirement from the document or evidence that verifies it; decisive evidence: Product B — HPD without Red List, Declare label, AND lower-GWP EPD.","logic":"Product B exemplifies LEED V5's integrated materials ideal: full ingredient transparency (HPD), Red List chemical avoidance (Declare label), AND lower embodied carbon (45 vs. 62 kg CO₂e/m²). Product A is disqualified by Red List chemicals (phthalates). Product C's 'all natural' claim without documentation is greenwashing. Product D has carbon data but lacks ingredient transparency.","purpose_vi":"Kiểm tra khả năng xác định đúng hồ sơ hoặc dữ liệu dùng để chứng minh yêu cầu MR, không nhầm với tài liệu có chức năng khác.","vocabulary_vi":"key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng; verification: việc dùng dữ liệu hoặc hồ sơ để xác nhận yêu cầu đã được đáp ứng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Declare công bố thành phần vật liệu và hỗ trợ minh bạch hóa hóa chất; không chứng nhận thực hành quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Sản phẩm D là preferred vì it có nhiều nhất detailed EPD hồ sơ","Sản phẩm là acceptable vì phthalates là chỉ issue trong children's spaces","Sản phẩm C - 'tất cả natural vật liệu' là Luôn luôn LEED-preferred choice","Sản phẩm B - HPD không có Red List, Declare label, và thấp hơn-GWP EPD"],"evidence_en":"Product B exemplifies LEED V5's integrated materials ideal: full ingredient transparency (HPD), Red List chemical avoidance (Declare label), AND lower embodied carbon (45 vs. 62 kg CO₂e/m²). Product A is disqualified by Red List chemicals (phthalates). Product C's 'all natural' claim without documentation is greenwashing. Product D has carbon data but lacks ingredient transparency.","evidence_vi":"Declare công bố thành phần vật liệu và hỗ trợ minh bạch hóa hóa chất; không chứng nhận thực hành quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Declare công bố thành phần vật liệu và hỗ trợ minh bạch hóa hóa chất; không chứng nhận thực hành quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. “Sản phẩm D là preferred vì it có nhiều nhất detailed EPD hồ sơ” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Sản phẩm là acceptable vì phthalates là chỉ issue trong children's spaces” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Sản phẩm C - 'tất cả natural vật liệu' là Luôn luôn LEED-preferred choice” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Declare công bố thành phần vật liệu và hỗ trợ minh bạch hóa hóa chất; không chứng nhận thực hành quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 597; Materials & Resources","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “Product D is preferred because it has the most detailed EPD documentation” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Product B — HPD without Red List, Declare label, AND lower-GWP EPD.”","Incorrect. “Product A is acceptable since phthalates are only an issue in children's spaces” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Product B — HPD without Red List, Declare label, AND lower-GWP EPD.”","Incorrect. “Product C — 'all natural materials' is always the LEED-preferred choice” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Product B — HPD without Red List, Declare label, AND lower-GWP EPD.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Vật liệu và tài nguyên - vật liệu & Resources","english_explanation_version":"v7.5.19-english-only","core_concept":"Product B exemplifies LEED V5's integrated materials ideal: full ingredient transparency (HPD), Red List chemical avoidance (Declare label), AND lower embodied carbon (45 vs. 62 kg CO₂e/m²). Product A is disqualified by Red List chemicals (phthalates). Product C's 'all natural' claim without documentation is greenwashing. Product D has carbon data but lacks ingredient transparency.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q097","core_concept_vi":"Declare công bố thành phần vật liệu và hỗ trợ minh bạch hóa hóa chất; không chứng nhận thực hành quản lý rừng. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-598","source_index":598,"q":"The Pinewood Elementary School team skipped the pre-design integrative process to save time. Nine months into design development, they discover the classroom wing has an east-west orientation causing excessive afternoon solar gain on west-facing windows — uncorrectable without rebuilding the structural framing. What does this illustrate?","options":["Textbook MacLeamy curve cost — early analysis would have caught it for free","This is a normal occurrence in school design that cannot be avoided","It demonstrates that solar orientation analysis is optional for school projects","The MEP engineer is responsible for checking orientation during MEP design"],"answer":0,"category":"Integrative Process","source_domain":"Integrative Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the IP concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"integrative process: an early collaborative process used to identify system interactions and improve decisions; systems thinking: evaluation of interactions among building, site, water, energy, and occupant systems","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Textbook MacLeamy curve cost — early analysis would have caught it for free.","logic":"The MacLeamy curve is directly illustrated: a 2-hour pre-design solar analysis catches a problem that, discovered 9 months later, requires expensive structural redesign costing $200,000–$500,000 and 3 months of schedule delay. The integrative process prerequisite exists precisely to prevent this outcome.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm IP đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng; verification: việc dùng dữ liệu hoặc hồ sơ để xác nhận yêu cầu đã được đáp ứng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Quy trình tích hợp phải diễn ra đủ sớm để phân tích tương tác hệ thống còn có thể ảnh hưởng đến quyết định thiết kế lớn. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","options_vi":["Textbook MacLeamy curve chi phí - sớm phân tích sẽ có caught it cho free","Này là normal occurrence trong school thiết kế đó cannot là avoided","It demonstrates đó mặt trời orientation phân tích là optional cho school dự án","MEP engineer là responsible cho checking orientation trong quá trình MEP thiết kế"],"evidence_en":"The MacLeamy curve is directly illustrated: a 2-hour pre-design solar analysis catches a problem that, discovered 9 months later, requires expensive structural redesign costing $200,000–$500,000 and 3 months of schedule delay. The integrative process prerequisite exists precisely to prevent this outcome.","evidence_vi":"Quy trình tích hợp phải diễn ra đủ sớm để phân tích tương tác hệ thống còn có thể ảnh hưởng đến quyết định thiết kế lớn. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","mechanism_vi":"Quy trình tích hợp phải diễn ra đủ sớm để phân tích tương tác hệ thống còn có thể ảnh hưởng đến quyết định thiết kế lớn. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","wrong_reasons_vi":["Đúng. Quy trình tích hợp phải diễn ra đủ sớm để phân tích tương tác hệ thống còn có thể ảnh hưởng đến quyết định thiết kế lớn. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","Sai. “Này là normal occurrence trong school thiết kế đó cannot là avoided” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “It demonstrates đó mặt trời orientation phân tích là optional cho school dự án” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “MEP engineer là responsible cho checking orientation trong quá trình MEP thiết kế” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 598; Integrative Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Correct. This option directly satisfies the governing condition.","Incorrect. “This is a normal occurrence in school design that cannot be avoided” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Textbook MacLeamy curve cost — early analysis would have caught it for free.”","Incorrect. “It demonstrates that solar orientation analysis is optional for school projects” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Textbook MacLeamy curve cost — early analysis would have caught it for free.”","Incorrect. “The MEP engineer is responsible for checking orientation during MEP design” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Textbook MacLeamy curve cost — early analysis would have caught it for free.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Quy trình tích hợp - quy trình tích hợp","english_explanation_version":"v7.5.19-english-only","core_concept":"The MacLeamy curve is directly illustrated: a 2-hour pre-design solar analysis catches a problem that, discovered 9 months later, requires expensive structural redesign costing $200,000–$500,000 and 3 months of schedule delay. The integrative process prerequisite exists precisely to prevent this outcome.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q098","core_concept_vi":"Quy trình tích hợp phải diễn ra đủ sớm để phân tích tương tác hệ thống còn có thể ảnh hưởng đến quyết định thiết kế lớn. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án A đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-599","source_index":599,"q":"Tremont Community Center project team has identified four potential Innovation credits: (1) Exemplary Performance in C&D Waste Management (92% diversion); (2) Innovation in Design — comprehensive food systems program including on-site garden, composting, and cafeteria local food sourcing; (3) LEED AP BD+C on the project team; (4) Exemplary Performance in Outdoor Water Use Reduction (using only captured rainwater for native plant establishment irrigation). Which qualify as valid Innovation credits?","options":["All four earn 1 point each = 4 total Innovation points","primarily the LEED AP BD+C earns Innovation points — the other strategies don't qualify","All four qualify, earning 4 Innovation points","Items 1, 2, and 3 qualify; Item 4 doesn't — 100% reduction has no higher Exemplary threshold"],"answer":3,"category":"Innovation & Regional Priority","source_domain":"Innovation & Regional Priority","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the PR concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"outdoor water use reduction: reduction of potable water used for landscape irrigation; exemplary performance: performance that substantially exceeds an existing LEED credit threshold; innovation: a strategy with significant benefit not adequately addressed by existing LEED credits; credit: an optional LEED requirement that can earn points","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Items 1, 2, and 3 qualify; Item 4 doesn't — 100% reduction has no higher Exemplary threshold.","logic":"Item 4 is the trap: 'no permanent irrigation' already IS the 100% outdoor water reduction — there is no higher threshold to achieve 'Exemplary Performance.' You cannot exceed 100%. Items 1 (92% C&D > 75% standard), 2 (food systems Innovation in Design), and 3 (LEED AP) are valid. The team has 3 confirmed points and needs 2 more strategies for the 6-point maximum.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm PR đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"credit: tín chỉ tự chọn có thể mang lại điểm khi đáp ứng yêu cầu; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","options_vi":["Tất cả four nhận 1 điểm mỗi = 4 tổng Innovation điểm","Chỉ LEED AP BD+C đạt được Innovation điểm - khác giải pháp don't qualify","Tất cả four qualify, earning 4 Innovation điểm","Items 1, 2, và 3 qualify; Item 4 doesn't - 100% mức giảm có Không cao hơn Exemplary ngưỡng"],"evidence_en":"Item 4 is the trap: 'no permanent irrigation' already IS the 100% outdoor water reduction — there is no higher threshold to achieve 'Exemplary Performance.' You cannot exceed 100%. Items 1 (92% C&D > 75% standard), 2 (food systems Innovation in Design), and 3 (LEED AP) are valid. The team has 3 confirmed points and needs 2 more strategies for the 6-point maximum.","evidence_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","mechanism_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","wrong_reasons_vi":["Sai. “Tất cả four nhận 1 điểm mỗi = 4 tổng Innovation điểm” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Chỉ LEED AP BD+C đạt được Innovation điểm - khác giải pháp don't qualify” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “Tất cả four qualify, earning 4 Innovation điểm” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 599; Innovation & Regional Priority","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “All four earn 1 point each = 4 total Innovation points” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Items 1, 2, and 3 qualify; Item 4 doesn't — 100% reduction has no higher Exemplary threshold.”","Incorrect. “Only the LEED AP BD+C earns Innovation points — the other strategies don't qualify” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Items 1, 2, and 3 qualify; Item 4 doesn't — 100% reduction has no higher Exemplary threshold.”","Incorrect. “All four qualify, earning 4 Innovation points” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Items 1, 2, and 3 qualify; Item 4 doesn't — 100% reduction has no higher Exemplary threshold.”","Correct. This option directly satisfies the governing condition."],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Ưu tiên khu vực - Innovation & Regional Priority","english_explanation_version":"v7.5.19-english-only","core_concept":"Item 4 is the trap: 'no permanent irrigation' already IS the 100% outdoor water reduction — there is no higher threshold to achieve 'Exemplary Performance.' You cannot exceed 100%. Items 1 (92% C&D > 75% standard), 2 (food systems Innovation in Design), and 3 (LEED AP) are valid. The team has 3 confirmed points and needs 2 more strategies for the 6-point maximum.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q099","core_concept_vi":"Thực vật bản địa hoặc thích nghi phù hợp điều kiện địa phương, thường giảm nhu cầu tưới và hỗ trợ sinh cảnh. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án D đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"},{"id":"UD-600","source_index":600,"q":"Summit Research Institute is deciding between LEED and the WELL Building Standard for their new laboratory where scientists spend 60+ hours per week. How should the sustainability consultant respond to the CEO's question: 'Which is better for our scientists?'","options":["LEED is better because it has more market recognition","Pursue both — LEED covers environmental performance; WELL provides health depth","The institute should choose based principally on which certification costs less","WELL is better — LEED is primarily for energy and water"],"answer":1,"category":"LEED Overview & Process","source_domain":"LEED Overview & Process","question_style":"SCENARIO","purpose":"Assess whether the learner can apply the Overview concept and solve this concept question using the governing LEED v5 intent, scope, or requirement.","vocabulary":"certification: third-party confirmation that a project satisfies applicable LEED requirements; LEED: a third-party green building rating and certification system; compliance: satisfaction of the applicable requirement and documentation","keywords":"Match the term, scope, or function in the question to the exact LEED concept; decisive answer: Pursue both — LEED covers environmental performance; WELL provides health depth.","logic":"LEED and WELL are complementary, not competitive. For high-intensity occupancy like a research facility where scientists spend extreme hours, both certifications together provide comprehensive coverage — LEED for environmental sustainability across carbon, energy, water, materials, and site; WELL for depth of health coverage that 60-hour occupancy demands.","purpose_vi":"Kiểm tra khả năng nhận diện khái niệm Overview đang được mô tả và phân biệt các phương án theo đúng chức năng, đối tượng và phạm vi áp dụng.","vocabulary_vi":"certification: sự xác nhận của bên thứ ba đối với một bộ tiêu chí xác định; key condition: điều kiện quyết định dùng để loại các phương án gần đúng; scope: phạm vi đối tượng hoặc tác động mà yêu cầu áp dụng","keywords_vi":"Đối chiếu chức năng được hỏi với phạm vi thực của từng phương án; đáp án phải giải quyết đúng cơ chế, không chỉ cùng chủ đề.","logic_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","options_vi":["LEED là better vì it có nhiều hơn market recognition","Pursue cả hai - LEED covers môi trường hiệu suất; WELL provides sức khỏe depth","Institute nên choose based solely trên mà certification costs ít hơn","WELL là better - LEED là chỉ cho năng lượng và nước"],"evidence_en":"LEED and WELL are complementary, not competitive. For high-intensity occupancy like a research facility where scientists spend extreme hours, both certifications together provide comprehensive coverage — LEED for environmental sustainability across carbon, energy, water, materials, and site; WELL for depth of health coverage that 60-hour occupancy demands.","evidence_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","mechanism_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","wrong_reasons_vi":["Sai. “LEED là better vì it có nhiều hơn market recognition” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Đúng. Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","Sai. “Institute nên choose based solely trên mà certification costs ít hơn” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi.","Sai. “WELL là better - LEED là chỉ cho năng lượng và nước” không có cùng chức năng, đối tượng hoặc cơ chế với yêu cầu được mô tả; phương án này chỉ liên quan bề mặt đến chủ đề câu hỏi."],"source":"Exam sample (Udemy).docx - user-provided source","source_ref":"Source question 600; LEED Overview & Process","source_integrity":"Question, options, correct answer and explanation imported from the user-provided file without rewriting.","quote_status":"SOURCE_EXPLANATION_TRANSLATED_NOT_USGBC_QUOTE","vi_library_version":"v9-semantic-editorial","wrong_reasons_en":["Incorrect. “LEED is better because it has more market recognition” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Pursue both — LEED covers environmental performance; WELL provides health depth.”","Correct. This option directly satisfies the governing condition.","Incorrect. “The institute should choose based solely on which certification costs less” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Pursue both — LEED covers environmental performance; WELL provides health depth.”","Incorrect. “WELL is better — LEED is only for energy and water” does not satisfy the decisive condition in this question. It addresses a different intent, scope, metric, project stage, or level of compliance than “Pursue both — LEED covers environmental performance; WELL provides health depth.”"],"explanation_format":"VI_SEMANTIC_EDITORIAL_V9","topic_vi":"Tổng quan LEED - LEED Overview & Process","english_explanation_version":"v7.5.19-english-only","core_concept":"LEED and WELL are complementary, not competitive. For high-intensity occupancy like a research facility where scientists spend extreme hours, both certifications together provide comprehensive coverage — LEED for environmental sustainability across carbon, energy, water, materials, and site; WELL for depth of health coverage that 60-hour occupancy demands.","core_concept_version":"v7.5.21-all-12-tests","translation_batch":"T6-SEM-Q100","core_concept_vi":"Arc là nền tảng theo dõi và chấm điểm dữ liệu hiệu suất; không thay thế chức năng nộp hồ sơ chứng nhận của LEED Online. Đối chiếu cơ chế này với điều kiện của đề bài cho thấy phương án B đúng.","vi_alignment_source":"question|answer|core_concept|option_roles","semantic_review_status":"SEMANTIC_RULE_VALIDATED","deep_editorial_status":"PENDING_SOURCE_BY_SOURCE_REWRITE"}];
